#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub struct ChromiumCapabilitySelection {
    browser_events: bool,
    content: bool,
    dom_content: bool,
    context_creation: bool,
    context_lifecycle: bool,
    page_creation: bool,
    page_lifecycle: bool,
    evaluation: bool,
    handle_evaluation: bool,
    handle_lifecycle: bool,
    navigation: bool,
    network_events: bool,
    locator: bool,
    locator_screenshot: bool,
    page_events: bool,
}

impl ChromiumCapabilitySelection {
    pub const fn none() -> Self {
        Self {
            browser_events: false,
            content: false,
            dom_content: false,
            context_creation: false,
            context_lifecycle: false,
            page_creation: false,
            page_lifecycle: false,
            evaluation: false,
            handle_evaluation: false,
            handle_lifecycle: false,
            navigation: false,
            network_events: false,
            locator: false,
            locator_screenshot: false,
            page_events: false,
        }
    }

    pub const fn with_context_creation(mut self) -> Self {
        self.context_creation = true;
        self
    }

    pub const fn with_browser_events(mut self) -> Self {
        self.browser_events = true;
        self
    }

    pub const fn with_content(mut self) -> Self {
        self.content = true;
        self
    }

    pub const fn with_dom_content(mut self) -> Self {
        self.dom_content = true;
        self
    }

    pub const fn with_context_lifecycle(mut self) -> Self {
        self.context_lifecycle = true;
        self
    }

    pub const fn with_page_creation(mut self) -> Self {
        self.page_creation = true;
        self
    }

    pub const fn with_page_lifecycle(mut self) -> Self {
        self.page_lifecycle = true;
        self
    }

    pub const fn with_navigation(mut self) -> Self {
        self.navigation = true;
        self
    }

    pub const fn with_network_events(mut self) -> Self {
        self.network_events = true;
        self
    }

    pub const fn with_evaluation(mut self) -> Self {
        self.evaluation = true;
        self
    }

    pub const fn with_handle_evaluation(mut self) -> Self {
        self.handle_evaluation = true;
        self
    }

    pub const fn with_handle_lifecycle(mut self) -> Self {
        self.handle_lifecycle = true;
        self
    }

    pub const fn with_locator(mut self) -> Self {
        self.locator = true;
        self
    }

    pub const fn with_locator_screenshot(mut self) -> Self {
        self.locator_screenshot = true;
        self
    }

    pub const fn with_page_events(mut self) -> Self {
        self.page_events = true;
        self
    }

    pub const fn navigation(self) -> bool {
        self.navigation
    }

    pub const fn network_events(self) -> bool {
        self.network_events
    }

    pub const fn browser_events(self) -> bool {
        self.browser_events
    }

    pub const fn content(self) -> bool {
        self.content
    }

    pub const fn dom_content(self) -> bool {
        self.dom_content
    }

    pub const fn evaluation(self) -> bool {
        self.evaluation
    }

    pub const fn handle_evaluation(self) -> bool {
        self.handle_evaluation
    }

    pub const fn handle_lifecycle(self) -> bool {
        self.handle_lifecycle
    }

    pub const fn context_creation(self) -> bool {
        self.context_creation
    }

    pub const fn context_lifecycle(self) -> bool {
        self.context_lifecycle
    }

    pub const fn page_lifecycle(self) -> bool {
        self.page_lifecycle
    }

    pub const fn page_creation(self) -> bool {
        self.page_creation
    }

    pub const fn locator(self) -> bool {
        self.locator
    }

    pub const fn locator_screenshot(self) -> bool {
        self.locator_screenshot
    }

    pub const fn page_events(self) -> bool {
        self.page_events
    }

    pub const fn is_empty(self) -> bool {
        !self.browser_events
            && !self.content
            && !self.dom_content
            && !self.context_creation
            && !self.context_lifecycle
            && !self.page_creation
            && !self.page_lifecycle
            && !self.evaluation
            && !self.handle_evaluation
            && !self.handle_lifecycle
            && !self.navigation
            && !self.network_events
            && !self.locator
            && !self.locator_screenshot
            && !self.page_events
    }

    pub const fn len(self) -> usize {
        self.browser_events as usize
            + self.content as usize
            + self.dom_content as usize
            + self.context_creation as usize
            + self.context_lifecycle as usize
            + self.page_creation as usize
            + self.page_lifecycle as usize
            + self.evaluation as usize
            + self.handle_evaluation as usize
            + self.handle_lifecycle as usize
            + self.navigation as usize
            + self.network_events as usize
            + self.locator as usize
            + self.locator_screenshot as usize
            + self.page_events as usize
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct CapabilityWireProfile {
    version: ProtocolVersion,
    send_limits: FrameLimits,
    receive_limits: FrameLimits,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct ContentInstallationProfile {
    backend: CdpScreenshotProductionProfile,
    codec: ContentCodecLimits,
    wire: CapabilityWireProfile,
}

impl ContentInstallationProfile {
    pub const fn new(
        backend: CdpScreenshotProductionProfile,
        codec: ContentCodecLimits,
        wire: CapabilityWireProfile,
    ) -> Self {
        Self {
            backend,
            codec,
            wire,
        }
    }

    pub const fn backend(self) -> CdpScreenshotProductionProfile {
        self.backend
    }

    pub const fn codec(self) -> ContentCodecLimits {
        self.codec
    }

    pub const fn wire(self) -> CapabilityWireProfile {
        self.wire
    }

    fn unbudgeted_protocol(self) -> WireProtocol<ContentCodec> {
        let screenshot_bytes = u64::try_from(self.codec.screenshot_bytes).unwrap_or(u64::MAX);
        let ledger = pwright_core::ResourceLedger::new(ResourceLimits::deny_all(1, 1).with_class(
            ResourceClass::ScreenshotBytes,
            screenshot_bytes,
            screenshot_bytes,
        ));
        WireProtocol::new_exact_directional(
            ContentCodec::new(self.codec, ledger),
            self.wire.version,
            self.wire.send_limits,
            self.wire.receive_limits,
        )
    }
}

