/// Fixed reservation for native target/session strings retained by page
/// routing.
///
/// Every route owns one target/session pair for stable identity comparison,
/// and its `CdpSession` owns a second pair for command dispatch. The profile
/// therefore reserves four native-ID string slots per live Page. Frame-world
/// routes, including locator utility worlds, have independent capability
/// budgets and do not inflate this base Page route.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct CdpPageRouteProductionProfile {
    resource_scope: ResourceScope,
    max_pages: usize,
    max_native_id_bytes: usize,
    maximum_retained_bytes: u64,
    requirements: ResourceRequirements,
}

impl CdpPageRouteProductionProfile {
    pub fn from_topology(
        resource_scope: ResourceScope,
        topology: CdpTopologyProductionProfile,
    ) -> Self {
        let limits = topology.limits();
        let maximum_retained_bytes = u64::try_from(limits.pages)
            .unwrap_or(u64::MAX)
            .saturating_mul(4)
            .saturating_mul(u64::try_from(limits.native_id_bytes).unwrap_or(u64::MAX));
        let requirements = if maximum_retained_bytes == 0 {
            ResourceRequirements::none()
        } else {
            ResourceRequirements::none()
                .with_class(
                    ResourceClass::BackendStateBytes,
                    maximum_retained_bytes,
                    maximum_retained_bytes,
                )
                .with_metadata(1, 1)
        };
        Self {
            resource_scope,
            max_pages: limits.pages,
            max_native_id_bytes: limits.native_id_bytes,
            maximum_retained_bytes,
            requirements,
        }
    }

    pub const fn resource_scope(self) -> ResourceScope {
        self.resource_scope
    }

    pub const fn max_pages(self) -> usize {
        self.max_pages
    }

    pub const fn max_native_id_bytes(self) -> usize {
        self.max_native_id_bytes
    }

    pub const fn maximum_retained_bytes(self) -> u64 {
        self.maximum_retained_bytes
    }

    pub const fn requirements(self) -> ResourceRequirements {
        self.requirements
    }
}

/// Production limits for browser-side objects retained by `evaluateHandle`.
///
/// Each live route owns one `RemoteHandle` unit plus the exact bytes retained
/// by its optional CDP object ID and portable preview. The maximum is declared
/// before attachment so an omitted Handle plugin cannot consume the shared
/// connection ledger later.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct ChromiumHandleRouteProductionProfile {
    resource_scope: ResourceScope,
    max_handles: usize,
    max_native_id_bytes: usize,
    max_preview_bytes: usize,
    maximum_retained_bytes: u64,
    requirements: ResourceRequirements,
}

impl ChromiumHandleRouteProductionProfile {
    pub fn new(
        resource_scope: ResourceScope,
        max_handles: usize,
        max_native_id_bytes: usize,
        max_preview_bytes: usize,
    ) -> Self {
        // Keep selected leaf ownership accounting authoritative, including
        // independently enabled native-release identity storage.
        let requirements = ChromiumHandleLeafRouteProfile::new(
            resource_scope,
            max_handles,
            max_native_id_bytes,
            max_preview_bytes,
        )
        .requirements();
        let maximum_retained_bytes = requirements.class(ResourceClass::BackendStateBytes).global;
        Self {
            resource_scope,
            max_handles,
            max_native_id_bytes,
            max_preview_bytes,
            maximum_retained_bytes,
            requirements,
        }
    }

    pub const fn resource_scope(self) -> ResourceScope {
        self.resource_scope
    }

    pub const fn max_handles(self) -> usize {
        self.max_handles
    }

    pub const fn max_native_id_bytes(self) -> usize {
        self.max_native_id_bytes
    }

    pub const fn max_preview_bytes(self) -> usize {
        self.max_preview_bytes
    }

    pub const fn maximum_retained_bytes(self) -> u64 {
        self.maximum_retained_bytes
    }

    pub const fn requirements(self) -> ResourceRequirements {
        self.requirements
    }

    /// Preserves the aggregate profile's exact ownership and byte bounds while
    /// handing route-registry installation to the independent lifecycle leaf.
    pub const fn leaf_profile(self) -> ChromiumHandleLeafRouteProfile {
        ChromiumHandleLeafRouteProfile::new(
            self.resource_scope,
            self.max_handles,
            self.max_native_id_bytes,
            self.max_preview_bytes,
        )
    }
}

