macro_rules! impl_page_cancellation {
    ($command:ty, $field:ident, $service:ty, $error:ident) => {
        impl CommandCancellation<$command> for CdpPageServices {
            type Future<'a> = Pin<
                Box<
                    dyn Future<
                            Output = Result<
                                (),
                                OperationError<
                                    <$command as pwright_core::CommandSpec>::ErrorDetails,
                                >,
                            >,
                        > + Send
                        + 'a,
                >,
            >;

            fn cancel(
                &self,
                context: OperationContext,
                reason: CancellationReason,
            ) -> Self::Future<'_> {
                let service = self
                    .route(context.object_id())
                    .map_err($error)
                    .map(|entry| entry.and_then(|entry| entry.$field.clone()));
                Box::pin(async move {
                    let Some(service) = service? else {
                        // A topology-driven target detach may retire the route
                        // before the cancelled call observes its signal. There
                        // is then no live browser-side operation left to stop.
                        return Ok(());
                    };
                    <$service as CommandCancellation<$command>>::cancel(
                        service.as_ref(),
                        context,
                        reason,
                    )
                    .await
                })
            }
        }
    };
}

