impl CommandCancellation<PageScreenshot> for CdpPageServices {
    type Future<'a> =
        Pin<Box<dyn Future<Output = Result<(), OperationError<ContentErrorDetails>>> + Send + 'a>>;

    fn cancel(&self, context: OperationContext, reason: CancellationReason) -> Self::Future<'_> {
        let service = self
            .route(context.object_id())
            .map_err(content_route_state_error)
            .map(|entry| entry.and_then(|entry| entry.screenshot.clone()));
        Box::pin(async move {
            let Some(service) = service? else {
                return Ok(());
            };
            <CdpScreenshotService as CommandCancellation<PageScreenshot>>::cancel(
                service.as_ref(),
                context,
                reason,
            )
            .await
        })
    }
}

impl CommandCancellation<LocatorScreenshot> for CdpPageServices {
    type Future<'a> = Pin<
        Box<
            dyn Future<Output = Result<(), OperationError<LocatorScreenshotErrorDetails>>>
                + Send
                + 'a,
        >,
    >;

    fn cancel(&self, context: OperationContext, reason: CancellationReason) -> Self::Future<'_> {
        let service = self
            .locator_screenshot_route(context.object_id())
            .map_err(locator_screenshot_route_state_error);
        Box::pin(async move {
            let Some(service) = service? else {
                return Ok(());
            };
            <CdpLocatorScreenshotService as CommandCancellation<LocatorScreenshot>>::cancel(
                service.as_ref(),
                context,
                reason,
            )
            .await
        })
    }
}

macro_rules! impl_dom_read_cancellation {
    ($command:ty) => {
        impl CommandCancellation<$command> for CdpPageServices {
            type Future<'a> = Pin<
                Box<
                    dyn Future<Output = Result<(), OperationError<DomContentErrorDetails>>>
                        + Send
                        + 'a,
                >,
            >;

            fn cancel(
                &self,
                _context: OperationContext,
                _reason: CancellationReason,
            ) -> Self::Future<'_> {
                // CDP has no operation-local cancellation primitive for Runtime.evaluate.
                // Dropping the call releases DOM-content admission and discards any
                // late renderer result without affecting unrelated Frame work.
                Box::pin(async { Ok(()) })
            }
        }
    };
}

impl_dom_read_cancellation!(FrameContent);
impl_dom_read_cancellation!(FrameTitle);

impl CommandCancellation<EvaluateValue> for CdpPageServices {
    type Future<'a> = Pin<
        Box<dyn Future<Output = Result<(), OperationError<EvaluationErrorDetails>>> + Send + 'a>,
    >;

    fn cancel(&self, _context: OperationContext, _reason: CancellationReason) -> Self::Future<'_> {
        // CDP has no operation-local cancellation primitive for Runtime.evaluate.
        // Dropping the call rejects the portable result without terminating
        // unrelated JavaScript in the same renderer.
        Box::pin(async { Ok(()) })
    }
}

#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub struct ChromiumHandleRouteMetrics {
    pub current: usize,
    pub peak: usize,
    pub retained_bytes: u64,
    pub peak_retained_bytes: u64,
    pub created: u64,
    pub explicitly_disposed: u64,
    pub parent_retired: u64,
    pub topology_retired: u64,
    pub connection_retired: u64,
}

struct ChromiumHandleRouteEntry {
    owner_frame: ObjectId,
    owner_page: ObjectId,
    native: CdpEvaluatedHandle,
    retained_bytes: u64,
    _resource: Option<ResourceLease>,
}

type ResolvedChromiumHandleArguments = Vec<(ObjectId, CdpEvaluatedHandle)>;

#[derive(Default)]
struct ChromiumHandleRouteState {
    routes: BTreeMap<ObjectId, ChromiumHandleRouteEntry>,
    metrics: ChromiumHandleRouteMetrics,
}

#[derive(Clone)]
struct ChromiumHandleRouteResources {
    ledger: pwright_core::ResourceLedger,
    profile: ChromiumHandleRouteProductionProfile,
}

#[derive(Clone)]
pub struct ChromiumHandleRoutes {
    state: Arc<Mutex<ChromiumHandleRouteState>>,
    max_handles: usize,
    resources: Option<ChromiumHandleRouteResources>,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ChromiumHandleRetirementReason {
    ExplicitDispose,
    ParentDestroyed,
    TopologyInvalidated,
    ConnectionClosed,
}

#[must_use = "dropping prepared Handle-route retirement preserves every route"]
pub struct PreparedChromiumHandleRouteRetirement<'a> {
    state: MutexGuard<'a, ChromiumHandleRouteState>,
    object_ids: Vec<ObjectId>,
    reason: ChromiumHandleRetirementReason,
}

impl PreparedChromiumHandleRouteRetirement<'_> {
    fn commit(mut self) -> usize {
        retire_handle_routes(&mut self.state, &self.object_ids, self.reason)
    }
}

fn retire_handle_routes(
    state: &mut ChromiumHandleRouteState,
    object_ids: &[ObjectId],
    reason: ChromiumHandleRetirementReason,
) -> usize {
    let mut removed = 0usize;
    let mut retained_bytes = 0_u64;
    for object_id in object_ids {
        if let Some(route) = state.routes.remove(object_id) {
            removed = removed.saturating_add(1);
            retained_bytes = retained_bytes.saturating_add(route.retained_bytes);
        }
    }
    state.metrics.current = state.metrics.current.saturating_sub(removed);
    state.metrics.retained_bytes = state.metrics.retained_bytes.saturating_sub(retained_bytes);
    let removed = u64::try_from(removed).unwrap_or(u64::MAX);
    match reason {
        ChromiumHandleRetirementReason::ExplicitDispose => {
            state.metrics.explicitly_disposed =
                state.metrics.explicitly_disposed.saturating_add(removed);
        }
        ChromiumHandleRetirementReason::ParentDestroyed => {
            state.metrics.parent_retired = state.metrics.parent_retired.saturating_add(removed);
        }
        ChromiumHandleRetirementReason::TopologyInvalidated => {
            state.metrics.topology_retired = state.metrics.topology_retired.saturating_add(removed);
        }
        ChromiumHandleRetirementReason::ConnectionClosed => {
            state.metrics.connection_retired =
                state.metrics.connection_retired.saturating_add(removed);
        }
    }
    usize::try_from(removed).unwrap_or(usize::MAX)
}

impl ChromiumHandleRoutes {
    pub fn new(max_handles: usize) -> Self {
        Self {
            state: Arc::new(Mutex::new(ChromiumHandleRouteState::default())),
            max_handles,
            resources: None,
        }
    }

    pub fn new_with_production_resources(
        profile: ChromiumHandleRouteProductionProfile,
        resources: &ProductionResourceLedger,
    ) -> Result<Self, ProductionResourceError> {
        let ledger = resources.claim(profile.requirements())?;
        Ok(Self {
            state: Arc::new(Mutex::new(ChromiumHandleRouteState::default())),
            max_handles: profile.max_handles(),
            resources: Some(ChromiumHandleRouteResources { ledger, profile }),
        })
    }

    pub const fn max_handles(&self) -> usize {
        self.max_handles
    }

    pub fn len(&self) -> Result<usize, OperationError<HandleEvaluationErrorDetails>> {
        self.state
            .lock()
            .map(|state| state.routes.len())
            .map_err(|_| handle_route_state_error("handle route table is poisoned"))
    }

    pub fn is_empty(&self) -> Result<bool, OperationError<HandleEvaluationErrorDetails>> {
        self.state
            .lock()
            .map(|state| state.routes.is_empty())
            .map_err(|_| handle_route_state_error("handle route table is poisoned"))
    }

    pub fn contains(
        &self,
        object_id: ObjectId,
    ) -> Result<bool, OperationError<HandleEvaluationErrorDetails>> {
        self.state
            .lock()
            .map(|state| state.routes.contains_key(&object_id))
            .map_err(|_| handle_route_state_error("handle route table is poisoned"))
    }

    #[cfg(test)]
    fn resolve_arguments(
        &self,
        owner_frame: ObjectId,
        owner_page: ObjectId,
        client: &Arc<dyn CdpClient>,
        object_ids: &[ObjectId],
    ) -> Result<ResolvedChromiumHandleArguments, OperationError<HandleEvaluationErrorDetails>> {
        let state = self
            .state
            .lock()
            .map_err(|_| handle_route_state_error("handle route table is poisoned"))?;
        resolve_handle_arguments(&state, owner_frame, owner_page, client, object_ids)
    }

    fn resolve_creation_arguments(
        &self,
        owner_frame: ObjectId,
        owner_page: ObjectId,
        client: &Arc<dyn CdpClient>,
        object_ids: &[ObjectId],
    ) -> Result<ResolvedChromiumHandleArguments, OperationError<HandleEvaluationErrorDetails>> {
        let state = self
            .state
            .lock()
            .map_err(|_| handle_route_state_error("handle route table is poisoned"))?;
        resolve_handle_arguments(&state, owner_frame, owner_page, client, object_ids)
    }

    pub fn metrics(
        &self,
    ) -> Result<ChromiumHandleRouteMetrics, OperationError<HandleEvaluationErrorDetails>> {
        self.state
            .lock()
            .map(|state| state.metrics)
            .map_err(|_| handle_route_state_error("handle route table is poisoned"))
    }

    fn reserve_route(
        &self,
        native_id_bytes: usize,
        preview_bytes: usize,
    ) -> Result<Option<ResourceLease>, OperationError<HandleEvaluationErrorDetails>> {
        let Some(resources) = &self.resources else {
            return Ok(None);
        };
        if resources.profile.max_native_id_bytes() != native_id_bytes
            || resources.profile.max_preview_bytes() != preview_bytes
        {
            return Err(handle_route_state_error(
                "Handle service limits do not match the production route profile",
            ));
        }
        let mut requests = vec![ResourceRequest::new(ResourceClass::RemoteHandle, 1)];
        let retained_bytes = u64::try_from(resources.profile.max_native_id_bytes())
            .unwrap_or(u64::MAX)
            .saturating_add(
                u64::try_from(resources.profile.max_preview_bytes()).unwrap_or(u64::MAX),
            );
        if retained_bytes > 0 {
            requests.push(ResourceRequest::new(
                ResourceClass::BackendStateBytes,
                retained_bytes,
            ));
        }
        resources
            .ledger
            .reserve_many(resources.profile.resource_scope(), &requests)
            .map(Some)
            .map_err(handle_route_resource_error)
    }

    fn prepare_retirement(
        &self,
        object_ids: &[ObjectId],
        reason: ChromiumHandleRetirementReason,
    ) -> Result<
        PreparedChromiumHandleRouteRetirement<'_>,
        OperationError<HandleEvaluationErrorDetails>,
    > {
        let state = self
            .state
            .lock()
            .map_err(|_| handle_route_state_error("handle route table is poisoned"))?;
        Ok(PreparedChromiumHandleRouteRetirement {
            state,
            object_ids: object_ids.to_vec(),
            reason,
        })
    }

    fn prepare_topology_retirement(
        &self,
        update: &CdpTopologyUpdate,
    ) -> Result<
        PreparedChromiumHandleTopologyRetirement<'_>,
        OperationError<HandleEvaluationErrorDetails>,
    > {
        let state = self
            .state
            .lock()
            .map_err(|_| handle_route_state_error("handle route table is poisoned"))?;
        let mut invalid_frames = BTreeSet::new();
        let mut crashed_pages = BTreeSet::new();
        let mut retire_all = false;
        for effect in update.effects() {
            match effect {
                CdpTopologyEffect::WorldChanged {
                    frame,
                    kind: pwright_backend_cdp::CdpWorldKind::Main,
                }
                | CdpTopologyEffect::WorldRemoved {
                    frame,
                    kind: pwright_backend_cdp::CdpWorldKind::Main,
                } => {
                    invalid_frames.insert(*frame);
                }
                CdpTopologyEffect::PageCrashed { page, .. } => {
                    crashed_pages.insert(*page);
                }
                CdpTopologyEffect::ReconnectStarted { .. } => retire_all = true,
                _ => {}
            }
        }
        let explicit_disposals = state
            .routes
            .iter()
            .filter_map(|(object_id, entry)| {
                (retire_all
                    || invalid_frames.contains(&entry.owner_frame)
                    || crashed_pages.contains(&entry.owner_page))
                .then_some(*object_id)
            })
            .collect::<Vec<_>>();
        Ok(PreparedChromiumHandleTopologyRetirement {
            retirement: PreparedChromiumHandleRouteRetirement {
                state,
                object_ids: explicit_disposals.clone(),
                reason: ChromiumHandleRetirementReason::TopologyInvalidated,
            },
            explicit_disposals,
        })
    }

    fn prepare_connection_retirement(
        &self,
    ) -> Result<PreparedChromiumHandleRouteRetirement<'_>, RuntimeStateError> {
        let state = self
            .state
            .lock()
            .map_err(|_| RuntimeStateError::StatePoisoned)?;
        let object_ids = state.routes.keys().copied().collect();
        Ok(PreparedChromiumHandleRouteRetirement {
            state,
            object_ids,
            reason: ChromiumHandleRetirementReason::ConnectionClosed,
        })
    }
}

fn resolve_handle_arguments(
    state: &ChromiumHandleRouteState,
    owner_frame: ObjectId,
    owner_page: ObjectId,
    client: &Arc<dyn CdpClient>,
    object_ids: &[ObjectId],
) -> Result<ResolvedChromiumHandleArguments, OperationError<HandleEvaluationErrorDetails>> {
    object_ids
        .iter()
        .map(|object_id| {
            let route = state.routes.get(object_id).ok_or_else(|| {
                OperationError::new(
                    FailureKind::TargetClosed,
                    format!("Handle `{object_id}` is disposed or unknown"),
                    Some(HandleEvaluationErrorDetails::InvalidValue(format!(
                        "portable Handle `{object_id}` has no live Chromium route"
                    ))),
                )
            })?;
            if route.owner_frame != owner_frame {
                return Err(OperationError::new(
                    FailureKind::ProtocolViolation,
                    format!(
                        "Handle `{object_id}` belongs to Frame `{}`, not Frame `{owner_frame}`",
                        route.owner_frame
                    ),
                    Some(HandleEvaluationErrorDetails::InvalidValue(
                        "JSHandle arguments must belong to the target execution context".to_owned(),
                    )),
                ));
            }
            if route.owner_page != owner_page || !route.native.belongs_to_client(client) {
                return Err(OperationError::new(
                    FailureKind::ProtocolViolation,
                    format!("Handle `{object_id}` belongs to a different CDP target"),
                    Some(HandleEvaluationErrorDetails::InvalidValue(
                        "Handle argument and target Frame do not share one CDP session".to_owned(),
                    )),
                ));
            }
            Ok((*object_id, route.native.clone()))
        })
        .collect()
}

#[must_use = "dropping prepared topology retirement preserves every Handle route"]
struct PreparedChromiumHandleTopologyRetirement<'a> {
    retirement: PreparedChromiumHandleRouteRetirement<'a>,
    explicit_disposals: Vec<ObjectId>,
}

impl PreparedChromiumHandleTopologyRetirement<'_> {
    fn lifecycle_messages(&self) -> impl Iterator<Item = ControlMessage> + '_ {
        self.explicit_disposals
            .iter()
            .copied()
            .map(|object_id| ControlMessage::Dispose { object_id })
    }

    fn include_removed(
        &mut self,
        removed: &[pwright_core::ObjectRecord<pwright_core::ObjectKindTag>],
    ) {
        for record in removed {
            let object_id = record.id();
            if self.retirement.state.routes.contains_key(&object_id)
                && !self.retirement.object_ids.contains(&object_id)
            {
                self.retirement.object_ids.push(object_id);
            }
        }
    }

    fn commit(self) -> usize {
        self.retirement.commit()
    }
}

#[must_use = "dropping prepared aggregate Handle topology retirement preserves every route"]
enum PreparedChromiumAggregateHandleTopologyRetirement<'a> {
    Compatibility(PreparedChromiumHandleTopologyRetirement<'a>),
    LifecycleLeaf(PreparedChromiumHandleLeafOwnerRetirement<'a>),
}

impl PreparedChromiumAggregateHandleTopologyRetirement<'_> {
    fn lifecycle_messages(&self) -> Vec<ControlMessage> {
        match self {
            Self::Compatibility(retirement) => retirement.lifecycle_messages().collect(),
            Self::LifecycleLeaf(retirement) => retirement.lifecycle_messages().collect(),
        }
    }

    fn include_removed(
        &mut self,
        removed: &[pwright_core::ObjectRecord<pwright_core::ObjectKindTag>],
    ) {
        match self {
            Self::Compatibility(retirement) => retirement.include_removed(removed),
            Self::LifecycleLeaf(retirement) => {
                let object_ids = removed.iter().map(|record| record.id()).collect::<Vec<_>>();
                retirement.include_removed(&object_ids);
            }
        }
    }

    fn commit(self) -> usize {
        match self {
            Self::Compatibility(retirement) => retirement.commit(),
            Self::LifecycleLeaf(retirement) => retirement.commit(),
        }
    }
}

fn prepare_aggregate_handle_topology_retirement<'a>(
    services: &'a CdpPageServices,
    update: &CdpTopologyUpdate,
) -> Result<Option<PreparedChromiumAggregateHandleTopologyRetirement<'a>>, ChromiumCompositionError>
{
    if let Some(routes) = &services.handle_routes {
        return routes
            .prepare_topology_retirement(update)
            .map(PreparedChromiumAggregateHandleTopologyRetirement::Compatibility)
            .map(Some)
            .map_err(|error| ChromiumCompositionError::HandleRoutes(error.to_string()));
    }
    let Some(routes) = &services.handle_leaf_routes else {
        return Ok(None);
    };
    let mut invalid_frames = Vec::new();
    let mut invalid_pages = Vec::new();
    let mut retire_all = false;
    for effect in update.effects() {
        match effect {
            CdpTopologyEffect::WorldChanged {
                frame,
                kind: pwright_backend_cdp::CdpWorldKind::Main,
            }
            | CdpTopologyEffect::WorldRemoved {
                frame,
                kind: pwright_backend_cdp::CdpWorldKind::Main,
            } => invalid_frames.push(*frame),
            CdpTopologyEffect::PageCrashed { page, .. } => invalid_pages.push(*page),
            CdpTopologyEffect::ReconnectStarted { .. } => retire_all = true,
            _ => {}
        }
    }
    routes
        .prepare_owner_retirement(&invalid_frames, &invalid_pages, retire_all)
        .map(PreparedChromiumAggregateHandleTopologyRetirement::LifecycleLeaf)
        .map(Some)
        .map_err(|error| ChromiumCompositionError::HandleRoutes(error.to_string()))
}

/// Adds Handle-route cleanup to a caller-selected runtime only when the
/// Handle capability is installed.
///
/// Remote-control composition can use this wrapper as both its cancellation
/// and transport-close target. Losing the Pwright connection then drains the
/// runtime object graph and releases every Handle route lease under one lock
/// ordering boundary; the underlying CDP connection owns native invalidation.
pub trait ChromiumPreparedHandleConnectionRetirement {
    fn commit(self) -> usize;
}

pub trait ChromiumHandleConnectionRouteOwner: Clone + Send + Sync {
    type Prepared<'a>: ChromiumPreparedHandleConnectionRetirement
    where
        Self: 'a;

    fn prepare_connection_retirement(&self) -> Result<Self::Prepared<'_>, RuntimeStateError>;
}

impl ChromiumPreparedHandleConnectionRetirement for PreparedChromiumHandleRouteRetirement<'_> {
    fn commit(self) -> usize {
        PreparedChromiumHandleRouteRetirement::commit(self)
    }
}

impl ChromiumHandleConnectionRouteOwner for ChromiumHandleRoutes {
    type Prepared<'a> = PreparedChromiumHandleRouteRetirement<'a>;

    fn prepare_connection_retirement(&self) -> Result<Self::Prepared<'_>, RuntimeStateError> {
        ChromiumHandleRoutes::prepare_connection_retirement(self)
    }
}

impl ChromiumPreparedHandleConnectionRetirement
    for PreparedChromiumHandleLeafConnectionRetirement<'_>
{
    fn commit(self) -> usize {
        PreparedChromiumHandleLeafConnectionRetirement::commit(self)
    }
}

impl ChromiumHandleConnectionRouteOwner for ChromiumHandleLeafLifecycleRoutes {
    type Prepared<'a> = PreparedChromiumHandleLeafConnectionRetirement<'a>;

    fn prepare_connection_retirement(&self) -> Result<Self::Prepared<'_>, RuntimeStateError> {
        ChromiumHandleLeafLifecycleRoutes::prepare_connection_retirement(self)
            .map_err(|_| RuntimeStateError::StatePoisoned)
    }
}

#[derive(Clone)]
pub struct ChromiumHandleAwareRuntime<Runtime, Routes = ChromiumHandleRoutes> {
    inner: Runtime,
    routes: Routes,
}

impl<Runtime, Routes> ChromiumHandleAwareRuntime<Runtime, Routes> {
    pub const fn new(inner: Runtime, routes: Routes) -> Self {
        Self { inner, routes }
    }

    pub const fn inner(&self) -> &Runtime {
        &self.inner
    }

    pub const fn routes(&self) -> &Routes {
        &self.routes
    }

    pub fn close_transport(
        &self,
    ) -> Result<pwright_runtime::TransportCloseOutcome, RuntimeStateError>
    where
        Runtime: pwright_runtime_control::TransportCloseTarget,
        Routes: ChromiumHandleConnectionRouteOwner,
    {
        let retirement = self.routes.prepare_connection_retirement()?;
        let outcome = pwright_runtime_control::TransportCloseTarget::close_transport(&self.inner)?;
        retirement.commit();
        Ok(outcome)
    }
}

impl<Runtime, Routes> pwright_runtime_control::CancellationTarget
    for ChromiumHandleAwareRuntime<Runtime, Routes>
where
    Runtime: pwright_runtime_control::CancellationTarget,
    Routes: Clone + Send + Sync,
{
    fn cancel_call(
        &self,
        call_id: pwright_core::CallId,
        cancellation: pwright_core::CancellationId,
        reason: CancellationReason,
    ) -> Result<pwright_core::CancellationRequestOutcome, RuntimeStateError> {
        pwright_runtime_control::CancellationTarget::cancel_call(
            &self.inner,
            call_id,
            cancellation,
            reason,
        )
    }

    fn is_object_live(&self, object_id: ObjectId) -> Result<bool, RuntimeStateError> {
        pwright_runtime_control::CancellationTarget::is_object_live(&self.inner, object_id)
    }
}

impl<Runtime, Routes> pwright_runtime_control::TransportCloseTarget
    for ChromiumHandleAwareRuntime<Runtime, Routes>
where
    Runtime: pwright_runtime_control::TransportCloseTarget,
    Routes: ChromiumHandleConnectionRouteOwner,
{
    fn close_transport(&self) -> Result<pwright_runtime::TransportCloseOutcome, RuntimeStateError> {
        ChromiumHandleAwareRuntime::close_transport(self)
    }
}

impl<Runtime, Routes> pwright_runtime_control::ControlMessageSource
    for ChromiumHandleAwareRuntime<Runtime, Routes>
where
    Runtime: pwright_runtime_control::ControlMessageSource,
    Routes: Clone + Send + Sync,
{
    fn claim_control_message(
        &self,
    ) -> Result<Option<pwright_runtime::ControlMessageClaim>, RuntimeStateError> {
        pwright_runtime_control::ControlMessageSource::claim_control_message(&self.inner)
    }
}

/// Coordinates one retained RemoteObject with one portable runtime object.
#[derive(Clone)]
pub struct ChromiumEvaluateHandleCommandService {
    page_services: CdpPageServices,
    runtime: ControlledLifecycleHandle,
    object_ids: Arc<dyn ObjectIdSource>,
    routes: ChromiumHandleRoutes,
    native_id_bytes: usize,
    preview_bytes: usize,
}

impl ChromiumEvaluateHandleCommandService {
    pub fn new(
        page_services: CdpPageServices,
        runtime: ControlledLifecycleHandle,
        object_ids: Arc<dyn ObjectIdSource>,
        routes: ChromiumHandleRoutes,
        native_id_bytes: usize,
        preview_bytes: usize,
    ) -> Self {
        Self {
            page_services,
            runtime,
            object_ids,
            routes,
            native_id_bytes,
            preview_bytes,
        }
    }

    async fn evaluate(
        &self,
        frame_id: ObjectId,
        metadata: CallMetadata,
        params: EvaluateHandleParams,
    ) -> Result<HandleInitializer, OperationError<HandleEvaluationErrorDetails>> {
        if metadata.timeout.is_some() {
            return Err(OperationError::new(
                FailureKind::ProtocolViolation,
                "Frame.evaluateHandle does not accept timeout metadata",
                None,
            ));
        }
        match self.runtime.is_object_live(frame_id) {
            Ok(true) => {}
            Ok(false) => {
                return Err(OperationError::new(
                    FailureKind::TargetClosed,
                    format!("Frame `{frame_id}` is closed"),
                    None,
                ));
            }
            Err(error) => return Err(map_runtime_handle_evaluation_error(error)),
        }
        let evaluation = self
            .page_services
            .handle_evaluation_route(frame_id)
            .map_err(|error| handle_route_state_error(&error.to_string()))?
            .ok_or_else(|| {
                OperationError::new(
                    FailureKind::TargetClosed,
                    format!("Frame `{frame_id}` has no active evaluation route"),
                    Some(HandleEvaluationErrorDetails::InvalidBackendResponse(
                        "portable Frame is absent from Chromium execution-world routes".to_owned(),
                    )),
                )
            })?;
        let handle_ids = params
            .referenced_handles(evaluation.service.limits().value)
            .map_err(|error| {
                OperationError::new(
                    FailureKind::ProtocolViolation,
                    format!("invalid evaluateHandle argument: {error}"),
                    Some(HandleEvaluationErrorDetails::InvalidValue(
                        error.to_string(),
                    )),
                )
            })?;
        let object_id = self.object_ids.next_object_id().map_err(|error| {
            OperationError::new(
                FailureKind::ResourceExhausted,
                error.to_string(),
                Some(HandleEvaluationErrorDetails::InvalidBackendResponse(
                    error.to_string(),
                )),
            )
        })?;
        let native_arguments = self.routes.resolve_creation_arguments(
            frame_id,
            evaluation.page_object_id,
            &evaluation.service.client(),
            &handle_ids,
        )?;
        self.ensure_handle_capacity()?;
        let mut route_resource = self
            .routes
            .reserve_route(self.native_id_bytes, self.preview_bytes)?;

        let backend = CdpHandleEvaluationService::from_evaluation(
            evaluation.service.as_ref().clone(),
            self.native_id_bytes,
            self.preview_bytes,
        );
        let native = backend
            .call(CdpHandleEvaluationRequest::new(params, native_arguments))
            .await?;
        let retained_bytes = u64::try_from(
            native
                .native_argument_bytes()
                .saturating_add(native.preview().len()),
        )
        .unwrap_or(u64::MAX);
        if let Some(resource) = &mut route_resource
            && resource.units(ResourceClass::BackendStateBytes).is_some()
            && let Err(error) =
                resource.try_resize(ResourceClass::BackendStateBytes, retained_bytes)
        {
            return release_failed_handle(native, handle_route_resource_error(error)).await;
        }
        let actual_kind = native.object_kind();
        let prepared = match self
            .runtime
            .prepare_object_creation(object_id, Some(frame_id), actual_kind)
            .map_err(map_runtime_handle_evaluation_error)
        {
            Ok(prepared) => prepared,
            Err(primary) => return release_failed_handle(native, primary).await,
        };

        let initializer = HandleInitializer::new(
            object_id,
            frame_id,
            actual_kind,
            native.preview().to_owned(),
        );
        match publish_handle_route(
            &self.routes,
            prepared,
            frame_id,
            evaluation.page_object_id,
            native,
            retained_bytes,
            route_resource,
        ) {
            Ok(()) => Ok(initializer),
            Err(failure) => {
                let (native, primary) = *failure;
                release_failed_handle(native, primary).await
            }
        }
    }

    fn ensure_handle_capacity(&self) -> Result<(), OperationError<HandleEvaluationErrorDetails>> {
        let routes = self
            .routes
            .state
            .lock()
            .map_err(|_| handle_route_state_error("handle route table is poisoned"))?;
        if routes.routes.len() >= self.routes.max_handles {
            Err(handle_capacity_error(self.routes.max_handles))
        } else {
            Ok(())
        }
    }
}

fn publish_handle_route(
    routes: &ChromiumHandleRoutes,
    prepared: PreparedObjectCreation,
    owner_frame: ObjectId,
    owner_page: ObjectId,
    native: CdpEvaluatedHandle,
    retained_bytes: u64,
    resource: Option<ResourceLease>,
) -> Result<
    (),
    Box<(
        CdpEvaluatedHandle,
        OperationError<HandleEvaluationErrorDetails>,
    )>,
> {
    let object_id = prepared.object_id();
    let mut state = match routes.state.lock() {
        Ok(table) => table,
        Err(_) => {
            return Err(Box::new((
                native,
                handle_route_state_error("handle route table is poisoned"),
            )));
        }
    };
    if state.routes.len() >= routes.max_handles {
        return Err(Box::new((
            native,
            handle_capacity_error(routes.max_handles),
        )));
    }
    if let Err(error) = prepared.commit() {
        return Err(Box::new((
            native,
            map_runtime_handle_evaluation_error(error),
        )));
    }
    let replaced = state.routes.insert(
        object_id,
        ChromiumHandleRouteEntry {
            owner_frame,
            owner_page,
            native,
            retained_bytes,
            _resource: resource,
        },
    );
    debug_assert!(replaced.is_none());
    state.metrics.current = state.metrics.current.saturating_add(1);
    state.metrics.peak = state.metrics.peak.max(state.metrics.current);
    state.metrics.retained_bytes = state.metrics.retained_bytes.saturating_add(retained_bytes);
    state.metrics.peak_retained_bytes = state
        .metrics
        .peak_retained_bytes
        .max(state.metrics.retained_bytes);
    state.metrics.created = state.metrics.created.saturating_add(1);
    Ok(())
}

impl Service<Command<EvaluateHandle>> for ChromiumEvaluateHandleCommandService {
    type Response = CommandResult<EvaluateHandle>;
    type Error = Infallible;
    type Future<'a> =
        Pin<Box<dyn Future<Output = Result<Self::Response, Self::Error>> + Send + 'a>>;

    fn call(&self, command: Command<EvaluateHandle>) -> Self::Future<'_> {
        let (call_id, frame_id, metadata, params) = command.into_parts();
        Box::pin(async move {
            Ok(CommandResult::new(
                call_id,
                self.evaluate(frame_id, metadata, params).await,
            ))
        })
    }
}

/// Applies explicit handle disposal to both the native route and runtime graph.
#[derive(Clone)]
pub struct ChromiumHandleDisposeCommandService {
    runtime: ControlledLifecycleHandle,
    routes: ChromiumHandleRoutes,
}

impl ChromiumHandleDisposeCommandService {
    pub const fn new(runtime: ControlledLifecycleHandle, routes: ChromiumHandleRoutes) -> Self {
        Self { runtime, routes }
    }

    async fn dispose(
        &self,
        object_id: ObjectId,
        metadata: CallMetadata,
    ) -> Result<(), OperationError<HandleLifecycleErrorDetails>> {
        if metadata != CallMetadata::default() {
            return Err(OperationError::new(
                FailureKind::ProtocolViolation,
                "Handle.dispose does not accept timeout or cancellation metadata",
                None,
            ));
        }
        match self.runtime.is_object_live(object_id) {
            Ok(false) => return Ok(()),
            Ok(true) => {}
            Err(error) => return Err(map_runtime_handle_dispose_error(error)),
        }
        let prepared = self
            .runtime
            .prepare_object_disposal(object_id)
            .map_err(map_runtime_handle_dispose_error)?;
        let native = self
            .routes
            .state
            .lock()
            .map_err(|_| handle_dispose_state_error("handle route table is poisoned"))?
            .routes
            .get(&object_id)
            .map(|route| route.native.clone())
            .ok_or_else(|| {
                OperationError::new(
                    FailureKind::TargetClosed,
                    format!("Handle `{object_id}` has no native route"),
                    Some(HandleLifecycleErrorDetails::Backend(
                        "portable handle is absent from Chromium handle routes".to_owned(),
                    )),
                )
            })?;
        native.release().await.map_err(|error| {
            OperationError::new(
                FailureKind::Backend,
                format!("CDP Runtime.releaseObject failed: {error}"),
                Some(HandleLifecycleErrorDetails::Backend(error.to_string())),
            )
        })?;
        let retirement = self
            .routes
            .prepare_retirement(
                &[object_id],
                ChromiumHandleRetirementReason::ExplicitDispose,
            )
            .map_err(map_handle_route_lifecycle_error)?;
        prepared
            .commit()
            .map_err(map_runtime_handle_dispose_error)?;
        retirement.commit();
        Ok(())
    }
}

impl Service<Command<HandleDispose>> for ChromiumHandleDisposeCommandService {
    type Response = CommandResult<HandleDispose>;
    type Error = Infallible;
    type Future<'a> =
        Pin<Box<dyn Future<Output = Result<Self::Response, Self::Error>> + Send + 'a>>;

    fn call(&self, command: Command<HandleDispose>) -> Self::Future<'_> {
        let (call_id, object_id, metadata, ()) = command.into_parts();
        Box::pin(async move {
            Ok(CommandResult::new(
                call_id,
                self.dispose(object_id, metadata).await,
            ))
        })
    }
}

fn handle_capacity_error(limit: usize) -> OperationError<HandleEvaluationErrorDetails> {
    OperationError::new(
        FailureKind::ResourceExhausted,
        format!("live handle route limit {limit} was reached"),
        Some(HandleEvaluationErrorDetails::InvalidBackendResponse(
            "bounded Chromium handle route table is full".to_owned(),
        )),
    )
}

fn handle_route_state_error(message: &str) -> OperationError<HandleEvaluationErrorDetails> {
    OperationError::new(
        FailureKind::Cleanup,
        message,
        Some(HandleEvaluationErrorDetails::Cleanup {
            primary: "handle publication failed".to_owned(),
            cleanup: message.to_owned(),
        }),
    )
}

fn handle_route_resource_error(
    error: ResourceError,
) -> OperationError<HandleEvaluationErrorDetails> {
    OperationError::new(
        FailureKind::ResourceExhausted,
        format!("Chromium Handle route resource admission failed: {error}"),
        Some(HandleEvaluationErrorDetails::InvalidBackendResponse(
            error.to_string(),
        )),
    )
}

fn map_handle_route_lifecycle_error(
    error: OperationError<HandleEvaluationErrorDetails>,
) -> OperationError<HandleLifecycleErrorDetails> {
    OperationError::new(
        error.kind(),
        error.message(),
        Some(HandleLifecycleErrorDetails::Backend(error.to_string())),
    )
}

fn handle_dispose_state_error(message: &str) -> OperationError<HandleLifecycleErrorDetails> {
    OperationError::new(
        FailureKind::Cleanup,
        message,
        Some(HandleLifecycleErrorDetails::Cleanup {
            primary: "handle disposal state failed".to_owned(),
            cleanup: message.to_owned(),
        }),
    )
}

fn map_runtime_handle_evaluation_error(
    error: RuntimeStateError,
) -> OperationError<HandleEvaluationErrorDetails> {
    let kind = match error {
        RuntimeStateError::TransportClosed => FailureKind::TransportClosed,
        RuntimeStateError::ObjectGraph(ObjectGraphError::CapacityExceeded { .. })
        | RuntimeStateError::Resource(_) => FailureKind::ResourceExhausted,
        RuntimeStateError::ObjectGraph(_) => FailureKind::ProtocolViolation,
        _ => FailureKind::Cleanup,
    };
    OperationError::new(
        kind,
        format!("runtime could not publish handle: {error}"),
        Some(HandleEvaluationErrorDetails::InvalidBackendResponse(
            error.to_string(),
        )),
    )
}

fn map_runtime_handle_dispose_error(
    error: RuntimeStateError,
) -> OperationError<HandleLifecycleErrorDetails> {
    let kind = match error {
        RuntimeStateError::TransportClosed => FailureKind::TransportClosed,
        RuntimeStateError::ObjectGraph(_) => FailureKind::TargetClosed,
        _ => FailureKind::Cleanup,
    };
    OperationError::new(
        kind,
        format!("runtime could not dispose handle: {error}"),
        Some(HandleLifecycleErrorDetails::Backend(error.to_string())),
    )
}

async fn release_failed_handle(
    native: CdpEvaluatedHandle,
    primary: OperationError<HandleEvaluationErrorDetails>,
) -> Result<HandleInitializer, OperationError<HandleEvaluationErrorDetails>> {
    match native.release().await {
        Ok(()) => Err(primary),
        Err(cleanup) => Err(OperationError::new(
            FailureKind::Cleanup,
            format!("{}; handle cleanup failed: {cleanup}", primary.message()),
            Some(HandleEvaluationErrorDetails::Cleanup {
                primary: primary.to_string(),
                cleanup: cleanup.to_string(),
            }),
        )),
    }
}

pub type SharedChromiumTopology = Arc<Mutex<ProductionCdpTopology>>;

/// Coordinates portable identity, runtime capacity, CDP creation, topology
/// publication, and compensation for one no-options Browser.newContext call.
#[derive(Clone)]
pub struct ChromiumBrowserNewContextCommandService {
    backend: CdpBrowserContextCreationService,
    browser_client: Arc<dyn CdpClient>,
    topology: SharedChromiumTopology,
    runtime: ControlledLifecycleHandle,
    object_ids: Arc<dyn ObjectIdSource>,
    browser_object_id: ObjectId,
}

impl ChromiumBrowserNewContextCommandService {
    pub fn new(
        backend: CdpBrowserContextCreationService,
        browser_client: Arc<dyn CdpClient>,
        topology: SharedChromiumTopology,
        runtime: ControlledLifecycleHandle,
        object_ids: Arc<dyn ObjectIdSource>,
        browser_object_id: ObjectId,
    ) -> Self {
        Self {
            backend,
            browser_client,
            topology,
            runtime,
            object_ids,
            browser_object_id,
        }
    }

    async fn create(
        &self,
        target: ObjectId,
        metadata: CallMetadata,
    ) -> Result<BrowserContextInitializer, OperationError<ContextCreationErrorDetails>> {
        if metadata != CallMetadata::default() {
            return Err(OperationError::new(
                FailureKind::ProtocolViolation,
                "Browser.newContext does not accept timeout or cancellation metadata",
                None,
            ));
        }
        if target != self.browser_object_id {
            return Err(OperationError::new(
                FailureKind::ProtocolViolation,
                format!(
                    "Browser.newContext targeted Browser `{target}`, expected `{}`",
                    self.browser_object_id
                ),
                None,
            ));
        }
        match self.runtime.is_object_live(target) {
            Ok(true) => {}
            Ok(false) => {
                return Err(OperationError::new(
                    FailureKind::TargetClosed,
                    format!("Browser `{target}` is closed"),
                    None,
                ));
            }
            Err(error) => return Err(map_runtime_context_creation_error(error)),
        }

        let object_id = self.object_ids.next_object_id().map_err(|error| {
            OperationError::new(
                FailureKind::ResourceExhausted,
                error.to_string(),
                Some(ContextCreationErrorDetails::Publication(error.to_string())),
            )
        })?;
        let prepared_runtime = self
            .runtime
            .prepare_object_creation(
                object_id,
                Some(self.browser_object_id),
                BROWSER_CONTEXT_OBJECT_KIND.tag,
            )
            .map_err(map_runtime_context_creation_error)?;
        let created = self.backend.call(()).await?;
        let native_id = created.browser_context_id();
        let publication = publish_created_context(
            &self.topology,
            prepared_runtime,
            native_id,
            object_id,
            self.browser_object_id,
        );
        if let Err(primary) = publication {
            return compensate_failed_context_publication(
                self.browser_client.as_ref(),
                native_id,
                primary,
            )
            .await;
        }
        Ok(BrowserContextInitializer::new(
            object_id,
            self.browser_object_id,
            BROWSER_CONTEXT_OBJECT_KIND.tag,
        ))
    }
}

impl Service<Command<BrowserNewContext>> for ChromiumBrowserNewContextCommandService {
    type Response = CommandResult<BrowserNewContext>;
    type Error = Infallible;
    type Future<'a> =
        Pin<Box<dyn Future<Output = Result<Self::Response, Self::Error>> + Send + 'a>>;

    fn call(&self, command: Command<BrowserNewContext>) -> Self::Future<'_> {
        let (call_id, object_id, metadata, ()) = command.into_parts();
        Box::pin(async move {
            let outcome = self.create(object_id, metadata).await;
            Ok(CommandResult::new(call_id, outcome))
        })
    }
}

/// Coordinates one Playwright-aligned explicit Page creation across portable
/// identity, runtime capacity, CDP readiness, topology, and Page routing.
#[derive(Clone)]
pub struct ChromiumBrowserContextNewPageCommandService {
    backend: CdpPageCreationService,
    topology: SharedChromiumTopology,
    page_services: CdpPageServices,
    runtime: ControlledLifecycleHandle,
    object_ids: Arc<dyn ObjectIdSource>,
    network_registration: Option<ChromiumNetworkPageRegistrationHandle>,
    network_session_factory: Option<Arc<dyn SessionFactory>>,
}

impl ChromiumBrowserContextNewPageCommandService {
    pub fn new(
        backend: CdpPageCreationService,
        topology: SharedChromiumTopology,
        page_services: CdpPageServices,
        runtime: ControlledLifecycleHandle,
        object_ids: Arc<dyn ObjectIdSource>,
    ) -> Self {
        Self {
            backend,
            topology,
            page_services,
            runtime,
            object_ids,
            network_registration: None,
            network_session_factory: None,
        }
    }

    /// Includes the installed single-cursor network driver in explicit Page
    /// publication. The Page's exact session lane is activated before its
    /// portable objects become visible, while the cursor holds any event from
    /// that provisional session until publication commits.
    pub fn with_network_registration(
        mut self,
        registration: ChromiumNetworkPageRegistrationHandle,
        session_factory: Arc<dyn SessionFactory>,
    ) -> Self {
        self.network_registration = Some(registration);
        self.network_session_factory = Some(session_factory);
        self
    }

    async fn create(
        &self,
        context_object_id: ObjectId,
        metadata: CallMetadata,
    ) -> Result<PageInitializer, OperationError<PageCreationErrorDetails>> {
        if metadata != CallMetadata::default() {
            return Err(OperationError::new(
                FailureKind::ProtocolViolation,
                "BrowserContext.newPage does not accept timeout or cancellation metadata",
                None,
            ));
        }
        match self.runtime.is_object_live(context_object_id) {
            Ok(true) => {}
            Ok(false) => {
                return Err(OperationError::new(
                    FailureKind::TargetClosed,
                    format!("BrowserContext `{context_object_id}` is closed"),
                    None,
                ));
            }
            Err(error) => return Err(map_runtime_page_creation_error(error)),
        }
        let browser_context_id = self
            .topology
            .lock()
            .map_err(|_| page_creation_topology_unavailable())?
            .topology()
            .browser_context_route(context_object_id)
            .map(|route| route.browser_context_id().to_owned())
            .ok_or_else(|| {
                OperationError::new(
                    FailureKind::TargetClosed,
                    format!("BrowserContext `{context_object_id}` has no CDP route"),
                    Some(PageCreationErrorDetails::Publication(
                        "portable context is absent from Chromium topology".to_string(),
                    )),
                )
            })?;

        let page_object_id = next_page_object_id(&self.object_ids)?;
        let main_frame_object_id = next_page_object_id(&self.object_ids)?;
        let prepared_runtime = self
            .runtime
            .prepare_object_creation_batch(&[
                ObjectCreationSpec::new(
                    page_object_id,
                    Some(context_object_id),
                    PAGE_OBJECT_KIND.tag,
                ),
                ObjectCreationSpec::new(
                    main_frame_object_id,
                    Some(page_object_id),
                    FRAME_OBJECT_KIND.tag,
                ),
            ])
            .map_err(map_runtime_page_creation_error)?;

        let created = self
            .backend
            .call(CdpPageCreationRequest::new(browser_context_id.clone()))
            .await?;
        let prepared_network = if let (Some(registration), Some(session_factory)) =
            (&self.network_registration, &self.network_session_factory)
        {
            let client = session_factory.create_session(
                created.session_id().to_owned(),
                created.target_id().to_owned(),
            );
            match registration
                .prepare_page_registration(
                    page_object_id,
                    context_object_id,
                    created.session_id().to_owned(),
                    client,
                )
                .await
            {
                Ok(prepared) => Some((registration, prepared)),
                Err(error) => {
                    let primary = map_network_page_creation_error(error);
                    return Err(self
                        .backend
                        .compensate_created_target(created.target_id(), primary)
                        .await);
                }
            }
        } else {
            None
        };
        let publication = || {
            publish_created_page(
                &self.topology,
                &self.page_services,
                prepared_runtime,
                &browser_context_id,
                created.target_id(),
                created.session_id(),
                created.main_frame_id(),
                context_object_id,
                page_object_id,
                main_frame_object_id,
            )
        };
        let publication = match prepared_network {
            Some((registration, prepared)) => {
                match registration.commit_page_registration(prepared, publication) {
                    Ok(Ok(())) => Ok(()),
                    Ok(Err(primary)) => {
                        let primary = match registration.rollback_page_registration(prepared).await
                        {
                            Ok(_) => primary,
                            Err(cleanup) => network_page_creation_cleanup_error(primary, cleanup),
                        };
                        Err(primary)
                    }
                    Err(error) => Err(map_network_page_creation_error(error)),
                }
            }
            None => publication(),
        };
        if let Err(primary) = publication {
            return Err(self
                .backend
                .compensate_created_target(created.target_id(), primary)
                .await);
        }

        Ok(PageInitializer::new(
            page_object_id,
            context_object_id,
            PAGE_OBJECT_KIND.tag,
            main_frame_object_id,
            page_object_id,
            FRAME_OBJECT_KIND.tag,
        ))
    }
}

impl Service<Command<BrowserContextNewPage>> for ChromiumBrowserContextNewPageCommandService {
    type Response = CommandResult<BrowserContextNewPage>;
    type Error = Infallible;
    type Future<'a> =
        Pin<Box<dyn Future<Output = Result<Self::Response, Self::Error>> + Send + 'a>>;

    fn call(&self, command: Command<BrowserContextNewPage>) -> Self::Future<'_> {
        let (call_id, object_id, metadata, ()) = command.into_parts();
        Box::pin(async move {
            Ok(CommandResult::new(
                call_id,
                self.create(object_id, metadata).await,
            ))
        })
    }
}

fn next_page_object_id(
    source: &Arc<dyn ObjectIdSource>,
) -> Result<ObjectId, OperationError<PageCreationErrorDetails>> {
    source.next_object_id().map_err(|error| {
        OperationError::new(
            FailureKind::ResourceExhausted,
            error.to_string(),
            Some(PageCreationErrorDetails::Publication(error.to_string())),
        )
    })
}

#[allow(clippy::too_many_arguments)]
fn publish_created_page(
    topology: &SharedChromiumTopology,
    page_services: &CdpPageServices,
    prepared_runtime: PreparedObjectCreationBatch,
    browser_context_id: &str,
    target_id: &str,
    session_id: &str,
    main_frame_id: &str,
    context_object_id: ObjectId,
    page_object_id: ObjectId,
    main_frame_object_id: ObjectId,
) -> Result<(), OperationError<PageCreationErrorDetails>> {
    let mut topology = topology
        .lock()
        .map_err(|_| page_creation_topology_unavailable())?;
    let epoch = topology.topology().epoch();
    let target = CdpPageTarget::new(target_id, session_id, browser_context_id);
    let main_frame = CdpFrameAttachment::main(target_id, main_frame_id);
    let prepared_topology = topology
        .prepare_transition(move |candidate| {
            let attached = candidate.attach_page(
                epoch,
                target,
                CdpPageObjectIds::new(page_object_id, main_frame_object_id),
            )?;
            let rebound = candidate.attach_frame(epoch, main_frame, main_frame_object_id)?;
            Ok((attached, rebound))
        })
        .map_err(map_topology_page_creation_error)?;
    let expected = [
        CdpTopologyEffect::Lifecycle(ControlMessage::Create {
            object_id: page_object_id,
            parent: Some(context_object_id),
            kind: PAGE_OBJECT_KIND.tag,
        }),
        CdpTopologyEffect::Lifecycle(ControlMessage::Create {
            object_id: main_frame_object_id,
            parent: Some(page_object_id),
            kind: FRAME_OBJECT_KIND.tag,
        }),
    ];
    if prepared_topology.output().0.effects() != expected
        || prepared_topology
            .output()
            .1
            .effects()
            .iter()
            .any(|effect| matches!(effect, CdpTopologyEffect::Lifecycle(_)))
    {
        return Err(OperationError::new(
            FailureKind::ProtocolViolation,
            "Chromium topology produced unexpected effects for explicit Page creation",
            Some(PageCreationErrorDetails::Publication(format!(
                "attach effects: {:?}; frame effects: {:?}",
                prepared_topology.output().0.effects(),
                prepared_topology.output().1.effects()
            ))),
        ));
    }
    let prepared_routes = page_services
        .prepare_synchronization(prepared_topology.topology())
        .map_err(|error| {
            OperationError::new(
                FailureKind::ResourceExhausted,
                error.to_string(),
                Some(PageCreationErrorDetails::Publication(error.to_string())),
            )
        })?;
    prepared_runtime
        .commit()
        .map_err(map_runtime_page_creation_error)?;
    prepared_topology.commit();
    prepared_routes.commit();
    Ok(())
}

fn page_creation_topology_unavailable() -> OperationError<PageCreationErrorDetails> {
    OperationError::new(
        FailureKind::Cleanup,
        "Chromium topology state is unavailable during Page creation",
        Some(PageCreationErrorDetails::Publication(
            "topology mutex is poisoned".to_string(),
        )),
    )
}

fn map_runtime_page_creation_error(
    error: RuntimeStateError,
) -> OperationError<PageCreationErrorDetails> {
    let kind = match error {
        RuntimeStateError::TransportClosed => FailureKind::TransportClosed,
        RuntimeStateError::Resource(_)
        | RuntimeStateError::ProductionResource(_)
        | RuntimeStateError::ControlMessageCapacityExceeded { .. } => {
            FailureKind::ResourceExhausted
        }
        _ => FailureKind::ProtocolViolation,
    };
    OperationError::new(
        kind,
        format!("runtime could not prepare Page creation: {error}"),
        Some(PageCreationErrorDetails::Publication(error.to_string())),
    )
}

fn map_topology_page_creation_error(
    error: CdpTopologyProductionError,
) -> OperationError<PageCreationErrorDetails> {
    OperationError::new(
        FailureKind::ResourceExhausted,
        format!("Chromium topology could not publish Page creation: {error}"),
        Some(PageCreationErrorDetails::Publication(error.to_string())),
    )
}

fn map_network_page_creation_error(
    error: ChromiumNetworkEventDriverError,
) -> OperationError<PageCreationErrorDetails> {
    let kind = match error {
        ChromiumNetworkEventDriverError::PageLaneCapacityExceeded { .. }
        | ChromiumNetworkEventDriverError::Production(_)
        | ChromiumNetworkEventDriverError::Subscriptions(
            ChromiumNetworkSubscriptionStateError::PageLaneCapacityExceeded { .. }
            | ChromiumNetworkSubscriptionStateError::BrowserContextCapacityExceeded { .. },
        ) => FailureKind::ResourceExhausted,
        ChromiumNetworkEventDriverError::InheritedActivation { .. }
        | ChromiumNetworkEventDriverError::InheritedCompensation { .. }
        | ChromiumNetworkEventDriverError::Native { .. } => FailureKind::Backend,
        ChromiumNetworkEventDriverError::DriverUnavailable => FailureKind::Cleanup,
        _ => FailureKind::ProtocolViolation,
    };
    OperationError::new(
        kind,
        format!("Chromium network lane could not join Page creation: {error}"),
        Some(PageCreationErrorDetails::Publication(error.to_string())),
    )
}

fn network_page_creation_cleanup_error(
    primary: OperationError<PageCreationErrorDetails>,
    cleanup: ChromiumNetworkEventDriverError,
) -> OperationError<PageCreationErrorDetails> {
    OperationError::new(
        FailureKind::Cleanup,
        "BrowserContext.newPage publication failed and its provisional network lane could not be rolled back",
        Some(PageCreationErrorDetails::Cleanup {
            primary: primary.to_string(),
            cleanup: cleanup.to_string(),
        }),
    )
}

fn publish_created_context(
    topology: &SharedChromiumTopology,
    prepared_runtime: PreparedObjectCreation,
    browser_context_id: &str,
    object_id: ObjectId,
    browser_object_id: ObjectId,
) -> Result<(), OperationError<ContextCreationErrorDetails>> {
    let mut topology = topology.lock().map_err(|_| {
        OperationError::new(
            FailureKind::Cleanup,
            "Chromium topology state is unavailable after context creation",
            Some(ContextCreationErrorDetails::Publication(
                "topology mutex is poisoned".to_string(),
            )),
        )
    })?;
    let epoch = topology.topology().epoch();
    let native_id = browser_context_id.to_owned();
    let prepared_topology = topology
        .prepare_transition(move |candidate| {
            candidate.register_context(epoch, native_id, object_id, CdpContextOwnership::Owned)
        })
        .map_err(map_topology_context_creation_error)?;
    let expected = CdpTopologyEffect::Lifecycle(ControlMessage::Create {
        object_id,
        parent: Some(browser_object_id),
        kind: BROWSER_CONTEXT_OBJECT_KIND.tag,
    });
    if prepared_topology.output().effects() != [expected] {
        return Err(OperationError::new(
            FailureKind::ProtocolViolation,
            "Chromium topology produced unexpected effects for a new empty context",
            Some(ContextCreationErrorDetails::Publication(format!(
                "unexpected topology effects: {:?}",
                prepared_topology.output().effects()
            ))),
        ));
    }
    prepared_runtime
        .commit()
        .map_err(map_runtime_context_creation_error)?;
    prepared_topology.commit();
    Ok(())
}

async fn compensate_failed_context_publication(
    client: &dyn CdpClient,
    browser_context_id: &str,
    primary: OperationError<ContextCreationErrorDetails>,
) -> Result<BrowserContextInitializer, OperationError<ContextCreationErrorDetails>> {
    match CdpBrowserContextCloseService::close_route(
        client,
        browser_context_id,
        CdpContextOwnership::Owned,
    )
    .await
    {
        Ok(()) => Err(primary),
        Err(cleanup) => Err(OperationError::new(
            FailureKind::Cleanup,
            "Browser.newContext publication failed and its native compensation also failed",
            Some(ContextCreationErrorDetails::Cleanup {
                primary: primary.to_string(),
                cleanup: cleanup.to_string(),
            }),
        )),
    }
}

fn map_runtime_context_creation_error(
    error: RuntimeStateError,
) -> OperationError<ContextCreationErrorDetails> {
    let kind = match error {
        RuntimeStateError::TransportClosed => FailureKind::TransportClosed,
        RuntimeStateError::ObjectGraph(_)
        | RuntimeStateError::UnknownObjectKind { .. }
        | RuntimeStateError::MissingRequiredParent { .. }
        | RuntimeStateError::InvalidParentKind { .. }
        | RuntimeStateError::UnsupportedLifecycleMessage { .. } => FailureKind::ProtocolViolation,
        RuntimeStateError::ControlMessageCapacityExceeded { .. }
        | RuntimeStateError::LifecycleTransactionIdExhausted
        | RuntimeStateError::ProductionResource(_)
        | RuntimeStateError::Resource(_) => FailureKind::ResourceExhausted,
        _ => FailureKind::Cleanup,
    };
    OperationError::new(
        kind,
        format!("runtime could not prepare BrowserContext creation: {error}"),
        Some(ContextCreationErrorDetails::Publication(error.to_string())),
    )
}

fn map_topology_context_creation_error(
    error: CdpTopologyProductionError,
) -> OperationError<ContextCreationErrorDetails> {
    let kind = match &error {
        CdpTopologyProductionError::Resource(_)
        | CdpTopologyProductionError::CapacityOverflow
        | CdpTopologyProductionError::RetainedBytesInvariant { .. }
        | CdpTopologyProductionError::Topology(CdpTopologyError::CapacityExceeded { .. })
        | CdpTopologyProductionError::Topology(CdpTopologyError::ObjectGraph(
            ObjectGraphError::CapacityExceeded { .. },
        )) => FailureKind::ResourceExhausted,
        CdpTopologyProductionError::Topology(_) => FailureKind::ProtocolViolation,
        _ => FailureKind::Cleanup,
    };
    OperationError::new(
        kind,
        format!("Chromium topology could not publish BrowserContext creation: {error}"),
        Some(ContextCreationErrorDetails::Publication(error.to_string())),
    )
}

/// Remote-only decorator that sends the exact context `Create` initializer
/// before allowing the typed Browser.newContext result to complete.
pub struct OrderedBrowserNewContextCommandService<Inner, Source, Codec, Transport> {
    service: Arc<Inner>,
    control: OrderedRuntimeControl<Source, Codec, Transport>,
}

impl<Inner, Source, Codec, Transport>
    OrderedBrowserNewContextCommandService<Inner, Source, Codec, Transport>
{
    pub const fn new(
        service: Arc<Inner>,
        control: OrderedRuntimeControl<Source, Codec, Transport>,
    ) -> Self {
        Self { service, control }
    }
}

impl<Inner, Source, Codec, Transport> Service<Command<BrowserNewContext>>
    for OrderedBrowserNewContextCommandService<Inner, Source, Codec, Transport>
where
    Inner: Service<
            Command<BrowserNewContext>,
            Response = CommandResult<BrowserNewContext>,
            Error = Infallible,
        > + 'static,
    Source: pwright_runtime_control::ControlMessageSource + Send + Sync + 'static,
    Codec: WireCodec<ControlMessage> + 'static,
    Transport: pwright_transport::FrameTransport + 'static,
{
    type Response = CommandResult<BrowserNewContext>;
    type Error = Infallible;
    type Future<'a> =
        Pin<Box<dyn Future<Output = Result<Self::Response, Self::Error>> + Send + 'a>>;

    fn call(&self, command: Command<BrowserNewContext>) -> Self::Future<'_> {
        let call_id = command.call_id();
        Box::pin(async move {
            let barrier = match self.control.begin_barrier().await {
                Ok(barrier) => barrier,
                Err(error) => {
                    return Ok(context_creation_ordering_failure(
                        call_id,
                        map_control_gate_failure(error),
                    ));
                }
            };
            let result = match self.service.call(command).await {
                Ok(result) => result,
                Err(never) => match never {},
            };
            let initializer = match result.outcome() {
                Ok(initializer) => *initializer,
                Err(_) => return Ok(result),
            };
            match barrier
                .send_through_creation(
                    initializer.object_id,
                    Some(initializer.parent_id),
                    initializer.object_kind,
                )
                .await
            {
                Ok(_) => Ok(result),
                Err(_) => Ok(context_creation_ordering_failure(
                    call_id,
                    FailureKind::Cleanup,
                )),
            }
        })
    }
}

fn context_creation_ordering_failure(
    call_id: pwright_core::CallId,
    kind: FailureKind,
) -> CommandResult<BrowserNewContext> {
    CommandResult::new(
        call_id,
        Err(OperationError::new(
            kind,
            "Browser.newContext could not publish its initializer before completion",
            Some(ContextCreationErrorDetails::Publication(
                "ordered remote creation fence failed".to_string(),
            )),
        )),
    )
}

/// Remote-only fence that sends the handle `Create` initializer before the
/// typed `evaluateHandle` result becomes observable.
pub struct OrderedEvaluateHandleCommandService<Inner, Dispose, Source, Codec, Transport> {
    service: Arc<Inner>,
    dispose: Arc<Dispose>,
    control: OrderedRuntimeControl<Source, Codec, Transport>,
}

impl<Inner, Dispose, Source, Codec, Transport>
    OrderedEvaluateHandleCommandService<Inner, Dispose, Source, Codec, Transport>
{
    pub const fn new(
        service: Arc<Inner>,
        dispose: Arc<Dispose>,
        control: OrderedRuntimeControl<Source, Codec, Transport>,
    ) -> Self {
        Self {
            service,
            dispose,
            control,
        }
    }
}

impl<Inner, Dispose, Source, Codec, Transport> Service<Command<EvaluateHandle>>
    for OrderedEvaluateHandleCommandService<Inner, Dispose, Source, Codec, Transport>
where
    Inner: Service<
            Command<EvaluateHandle>,
            Response = CommandResult<EvaluateHandle>,
            Error = Infallible,
        > + 'static,
    Dispose: Service<Command<HandleDispose>, Response = CommandResult<HandleDispose>, Error = Infallible>
        + 'static,
    Source: ControlMessageSource + Send + Sync + 'static,
    Codec: WireCodec<ControlMessage> + 'static,
    Transport: FrameTransport + 'static,
{
    type Response = CommandResult<EvaluateHandle>;
    type Error = Infallible;
    type Future<'a> =
        Pin<Box<dyn Future<Output = Result<Self::Response, Self::Error>> + Send + 'a>>;

    fn call(&self, command: Command<EvaluateHandle>) -> Self::Future<'_> {
        let call_id = command.call_id();
        Box::pin(async move {
            let barrier = match self.control.begin_barrier().await {
                Ok(barrier) => barrier,
                Err(error) => {
                    return Ok(handle_creation_ordering_failure(
                        call_id,
                        map_control_gate_failure(error),
                    ));
                }
            };
            let result = match self.service.call(command).await {
                Ok(result) => result,
                Err(never) => match never {},
            };
            let initializer = match result.outcome() {
                Ok(initializer) => initializer.clone(),
                Err(_) => return Ok(result),
            };
            if barrier
                .send_through_creation(
                    initializer.object_id,
                    Some(initializer.parent_id),
                    initializer.object_kind,
                )
                .await
                .is_ok()
            {
                return Ok(result);
            }
            let cleanup = match self
                .dispose
                .call(Command::<HandleDispose>::new(
                    call_id,
                    initializer.object_id,
                    CallMetadata::default(),
                    (),
                ))
                .await
            {
                Ok(disposal) => match disposal.into_outcome() {
                    Ok(()) => "ordered creation failed; native Handle was released".to_owned(),
                    Err(error) => {
                        format!("ordered creation failed and Handle compensation failed: {error}")
                    }
                },
                Err(never) => match never {},
            };
            Ok(handle_creation_ordering_cleanup_failure(call_id, cleanup))
        })
    }
}

fn handle_creation_ordering_failure(
    call_id: pwright_core::CallId,
    kind: FailureKind,
) -> CommandResult<EvaluateHandle> {
    CommandResult::new(
        call_id,
        Err(OperationError::new(
            kind,
            "Frame.evaluateHandle could not publish its initializer before completion",
            Some(HandleEvaluationErrorDetails::Cleanup {
                primary: "handle evaluation succeeded".to_owned(),
                cleanup: "ordered remote creation fence failed".to_owned(),
            }),
        )),
    )
}

fn handle_creation_ordering_cleanup_failure(
    call_id: pwright_core::CallId,
    cleanup: String,
) -> CommandResult<EvaluateHandle> {
    CommandResult::new(
        call_id,
        Err(OperationError::new(
            FailureKind::Cleanup,
            "Frame.evaluateHandle could not publish its initializer before completion",
            Some(HandleEvaluationErrorDetails::Cleanup {
                primary: "handle evaluation succeeded".to_owned(),
                cleanup,
            }),
        )),
    )
}

/// Remote-only disposal fence. A successful result is not observable until
/// the Handle's child-last `Dispose` has crossed the shared ordered stream.
pub struct OrderedHandleDisposeCommandService<Inner, Source, Codec, Transport> {
    service: Arc<Inner>,
    control: OrderedRuntimeControl<Source, Codec, Transport>,
}

impl<Inner, Source, Codec, Transport>
    OrderedHandleDisposeCommandService<Inner, Source, Codec, Transport>
{
    pub const fn new(
        service: Arc<Inner>,
        control: OrderedRuntimeControl<Source, Codec, Transport>,
    ) -> Self {
        Self { service, control }
    }
}

impl<Inner, Source, Codec, Transport> Service<Command<HandleDispose>>
    for OrderedHandleDisposeCommandService<Inner, Source, Codec, Transport>
where
    Inner: Service<Command<HandleDispose>, Response = CommandResult<HandleDispose>, Error = Infallible>
        + 'static,
    Source: ControlMessageSource + Send + Sync + 'static,
    Codec: WireCodec<ControlMessage> + 'static,
    Transport: FrameTransport + 'static,
{
    type Response = CommandResult<HandleDispose>;
    type Error = Infallible;
    type Future<'a> =
        Pin<Box<dyn Future<Output = Result<Self::Response, Self::Error>> + Send + 'a>>;

    fn call(&self, command: Command<HandleDispose>) -> Self::Future<'_> {
        let call_id = command.call_id();
        let object_id = command.object_id();
        Box::pin(async move {
            let barrier = match self.control.begin_barrier().await {
                Ok(barrier) => barrier,
                Err(error) => {
                    return Ok(handle_disposal_ordering_failure(
                        call_id,
                        map_control_gate_failure(error),
                        "Handle disposal was rejected before native work",
                    ));
                }
            };
            let result = match self.service.call(command).await {
                Ok(result) => result,
                Err(never) => match never {},
            };
            if result.outcome().is_err() {
                return Ok(result);
            }
            match barrier.send_through_disposal(object_id).await {
                Ok(_) => Ok(result),
                Err(_) => Ok(handle_disposal_ordering_failure(
                    call_id,
                    FailureKind::Cleanup,
                    "native Handle disposal succeeded",
                )),
            }
        })
    }
}

fn handle_disposal_ordering_failure(
    call_id: pwright_core::CallId,
    kind: FailureKind,
    primary: &'static str,
) -> CommandResult<HandleDispose> {
    CommandResult::new(
        call_id,
        Err(OperationError::new(
            kind,
            "Handle.dispose could not publish its lifecycle before completion",
            Some(HandleLifecycleErrorDetails::Cleanup {
                primary: primary.to_owned(),
                cleanup: "ordered remote lifecycle completion failed".to_owned(),
            }),
        )),
    )
}

