/// Remote-only decorator that publishes the Page subtree disposal before an
/// ordinary Page.close result.
pub struct OrderedPageCloseCommandService<Inner, Source, Codec, Transport> {
    service: Arc<Inner>,
    control: OrderedRuntimeControl<Source, Codec, Transport>,
}

impl<Inner, Source, Codec, Transport>
    OrderedPageCloseCommandService<Inner, Source, Codec, Transport>
{
    pub const fn new(
        service: Arc<Inner>,
        control: OrderedRuntimeControl<Source, Codec, Transport>,
    ) -> Self {
        Self { service, control }
    }
}

impl<Inner, Source, Codec, Transport> Service<Command<PageClose>>
    for OrderedPageCloseCommandService<Inner, Source, Codec, Transport>
where
    Inner: Service<Command<PageClose>, Response = CommandResult<PageClose>, Error = Infallible>
        + 'static,
    Source: pwright_runtime_control::ControlMessageSource + Send + Sync + 'static,
    Codec: WireCodec<ControlMessage> + 'static,
    Transport: pwright_transport::FrameTransport + 'static,
{
    type Response = CommandResult<PageClose>;
    type Error = Infallible;
    type Future<'a> =
        Pin<Box<dyn Future<Output = Result<Self::Response, Self::Error>> + Send + 'a>>;

    fn call(&self, command: Command<PageClose>) -> Self::Future<'_> {
        let call_id = command.call_id();
        let object_id = command.object_id();
        Box::pin(async move {
            let barrier = match self.control.begin_barrier().await {
                Ok(barrier) => barrier,
                Err(error) => {
                    return Ok(page_close_ordering_failure(
                        call_id,
                        map_control_gate_failure(error),
                    ));
                }
            };
            let result = match self.service.call(command).await {
                Ok(result) => result,
                Err(never) => match never {},
            };
            if result.outcome().is_err() {
                return Ok(result);
            }
            match barrier.send_through_disposal(object_id).await {
                Ok(_) => Ok(result),
                Err(_error) => Ok(page_close_ordering_failure(call_id, FailureKind::Cleanup)),
            }
        })
    }
}

fn page_close_ordering_failure(
    call_id: pwright_core::CallId,
    kind: FailureKind,
) -> CommandResult<PageClose> {
    CommandResult::new(
        call_id,
        Err(OperationError::new(
            kind,
            "Page.close could not publish its lifecycle before completion",
            Some(PageLifecycleErrorDetails::Backend(
                "ordered remote lifecycle completion failed".to_string(),
            )),
        )),
    )
}

type PageCloseFutureOutput = Result<CommandResult<PageClose>, Infallible>;
type BoxPageCloseFuture = Pin<Box<dyn Future<Output = PageCloseFutureOutput> + Send + 'static>>;

/// Classifies owner retirement after an abandoned public call. It never changes
/// the operation result or commits native topology on failure.
pub trait PageCloseRetirement: Send + Sync + 'static {
    fn retired(outcome: &Result<(), OperationError<PageLifecycleErrorDetails>>) -> bool;
}

pub struct RequirePageCloseSuccess;
impl PageCloseRetirement for RequirePageCloseSuccess {
    fn retired(outcome: &Result<(), OperationError<PageLifecycleErrorDetails>>) -> bool {
        outcome.is_ok()
    }
}

