fn map_page_route_close_error(
    error: CdpPageRouteError,
) -> OperationError<PageLifecycleErrorDetails> {
    let kind = match &error {
        CdpPageRouteError::FrameNavigation(error) => error.kind(),
        CdpPageRouteError::WorldTargetClosed { .. } | CdpPageRouteError::NativeRetirementSealed => {
            FailureKind::TargetClosed
        }
        CdpPageRouteError::WorldReadinessCapacityExceeded { .. }
        | CdpPageRouteError::WorldReadinessResource(_) => FailureKind::ResourceExhausted,
        CdpPageRouteError::CapacityExceeded { .. }
        | CdpPageRouteError::RetainedBytesInvariant { .. }
        | CdpPageRouteError::EvaluationCapacityExceeded { .. }
        | CdpPageRouteError::EvaluationRetainedBytesInvariant { .. }
        | CdpPageRouteError::HandleEvaluationCapacityExceeded { .. }
        | CdpPageRouteError::HandleEvaluationRetainedBytesInvariant { .. }
        | CdpPageRouteError::LocatorCapacityExceeded { .. }
        | CdpPageRouteError::LocatorRetainedBytesInvariant { .. }
        | CdpPageRouteError::NetworkSubscriptions(
            ChromiumNetworkSubscriptionStateError::PageLaneCapacityExceeded { .. }
            | ChromiumNetworkSubscriptionStateError::BrowserContextCapacityExceeded { .. },
        )
        | CdpPageRouteError::InputAdmission(_)
        | CdpPageRouteError::Resources(_)
        | CdpPageRouteError::Resource(_) => FailureKind::ResourceExhausted,
        CdpPageRouteError::NativeIdTooLong { .. }
        | CdpPageRouteError::MainFrameUnavailable { .. }
        | CdpPageRouteError::FramePageUnavailable { .. }
        | CdpPageRouteError::LocatorInputOwnerUnavailable { .. } => FailureKind::ProtocolViolation,
        CdpPageRouteError::LocatorScreenshotParentUnavailable { .. } => FailureKind::Cleanup,
        CdpPageRouteError::PageCrashed { .. } => FailureKind::BrowserCrashed,
        CdpPageRouteError::StatePoisoned | CdpPageRouteError::NetworkSubscriptions(_) => {
            FailureKind::Cleanup
        }
    };
    OperationError::new(
        kind,
        format!("Page route state could not complete close: {error}"),
        Some(PageLifecycleErrorDetails::Backend(error.to_string())),
    )
}

fn map_handle_route_page_close_error(
    error: OperationError<HandleEvaluationErrorDetails>,
) -> OperationError<PageLifecycleErrorDetails> {
    OperationError::new(
        error.kind(),
        format!("Handle routes could not complete Page close: {error}"),
        Some(PageLifecycleErrorDetails::Backend(error.to_string())),
    )
}

fn map_handle_leaf_route_page_close_error(
    error: ChromiumHandleLeafLifecycleRouteError,
) -> OperationError<PageLifecycleErrorDetails> {
    OperationError::new(
        FailureKind::Cleanup,
        format!("Handle lifecycle leaf could not complete Page close: {error}"),
        Some(PageLifecycleErrorDetails::Backend(error.to_string())),
    )
}

fn map_network_page_close_error(
    error: ChromiumNetworkEventDriverError,
) -> OperationError<PageLifecycleErrorDetails> {
    let kind = network_driver_failure_kind(&error);
    OperationError::new(
        kind,
        format!("network lane could not complete Page close: {error}"),
        Some(PageLifecycleErrorDetails::Backend(error.to_string())),
    )
}

fn network_driver_failure_kind(error: &ChromiumNetworkEventDriverError) -> FailureKind {
    match error {
        ChromiumNetworkEventDriverError::PageLaneCapacityExceeded { .. }
        | ChromiumNetworkEventDriverError::Production(_)
        | ChromiumNetworkEventDriverError::Subscriptions(
            ChromiumNetworkSubscriptionStateError::PageLaneCapacityExceeded { .. }
            | ChromiumNetworkSubscriptionStateError::BrowserContextCapacityExceeded { .. },
        ) => FailureKind::ResourceExhausted,
        ChromiumNetworkEventDriverError::InheritedActivation { .. }
        | ChromiumNetworkEventDriverError::InheritedCompensation { .. }
        | ChromiumNetworkEventDriverError::Native { .. } => FailureKind::Backend,
        ChromiumNetworkEventDriverError::DriverUnavailable => FailureKind::Cleanup,
        _ => FailureKind::ProtocolViolation,
    }
}

/// Runtime surface required by the Chromium topology synchronization bridge.
pub trait ChromiumTopologyRuntime {
    fn apply_topology_lifecycle(
        &self,
        messages: &[ControlMessage],
    ) -> Result<Vec<pwright_core::ObjectRecord<ObjectKindTag>>, RuntimeStateError>;

    fn interrupt_crashed_page(
        &self,
        page: ObjectId,
        status: &str,
        error_code: i64,
    ) -> Result<(), RuntimeStateError>;

    fn page_services(&self) -> &CdpPageServices;
}

impl ChromiumTopologyRuntime for DirectDispatcher<CdpPageServices> {
    fn apply_topology_lifecycle(
        &self,
        messages: &[ControlMessage],
    ) -> Result<Vec<pwright_core::ObjectRecord<ObjectKindTag>>, RuntimeStateError> {
        self.apply_lifecycle_batch(messages)
    }

    fn interrupt_crashed_page(
        &self,
        page: ObjectId,
        _status: &str,
        _error_code: i64,
    ) -> Result<(), RuntimeStateError> {
        self.ensure_subtree_idle(page)
    }

    fn page_services(&self) -> &CdpPageServices {
        self.service()
    }
}

impl<Cancellation, Deadlines, Cleanup> ChromiumTopologyRuntime
    for ControlledDispatcher<CdpPageServices, Cancellation, Deadlines, Cleanup>
where
    Cancellation: Send + Sync,
    Deadlines: Send + Sync,
    Cleanup: Send + Sync,
{
    fn apply_topology_lifecycle(
        &self,
        messages: &[ControlMessage],
    ) -> Result<Vec<pwright_core::ObjectRecord<ObjectKindTag>>, RuntimeStateError> {
        self.apply_lifecycle_batch(messages)
    }

    fn interrupt_crashed_page(
        &self,
        page: ObjectId,
        status: &str,
        error_code: i64,
    ) -> Result<(), RuntimeStateError> {
        self.interrupt_subtree_calls(
            page,
            RuntimeCallFailure::new(
                FailureKind::BrowserCrashed,
                format!("Page `{page}` crashed with status `{status}` and error code {error_code}"),
            ),
        )
        .map(|_| ())
    }

    fn page_services(&self) -> &CdpPageServices {
        self.service()
    }
}

/// Applies one committed CDP topology update to runtime object ownership and
/// then refreshes target-aware page routes from the same topology snapshot.
///
/// Controlled runtimes cancel calls in disposed subtrees. Direct runtimes are
/// suitable only when the caller guarantees that affected objects are idle.
pub fn synchronize_topology_update<Runtime>(
    runtime: &Runtime,
    topology: &ProductionCdpTopology,
    update: &CdpTopologyUpdate,
) -> Result<(), ChromiumCompositionError>
where
    Runtime: ChromiumTopologyRuntime,
{
    let mut handle_retirement =
        prepare_aggregate_handle_topology_retirement(runtime.page_services(), update)?;
    let routes = runtime
        .page_services()
        .prepare_synchronization(topology.topology())?;
    let mut lifecycle = handle_retirement
        .as_ref()
        .into_iter()
        .flat_map(PreparedChromiumAggregateHandleTopologyRetirement::lifecycle_messages)
        .collect::<Vec<_>>();
    lifecycle.extend(topology_lifecycle_messages(update));
    apply_topology_interruptions(runtime, update)?;
    let removed = runtime.apply_topology_lifecycle(&lifecycle)?;
    if let Some(retirement) = &mut handle_retirement {
        retirement.include_removed(&removed);
    }
    routes.commit();
    if let Some(retirement) = handle_retirement {
        retirement.commit();
    }
    Ok(())
}

/// Stages a production topology mutation, validates its complete route table,
/// atomically applies its runtime lifecycle batch, and only then publishes the
/// topology and routes.
///
/// Any error before the runtime batch commits drops both prepared candidates
/// and leaves all three live views unchanged. After batch admission, route and
/// topology publication are infallible moves while command route lookup is
/// excluded by the prepared route guard.
pub fn transact_topology_update<Runtime>(
    topology: &mut ProductionCdpTopology,
    runtime: &Runtime,
    apply: impl FnOnce(
        &mut pwright_backend_cdp::CdpTopology,
    ) -> Result<CdpTopologyUpdate, pwright_backend_cdp::CdpTopologyError>,
) -> Result<CdpTopologyUpdate, ChromiumCompositionError>
where
    Runtime: ChromiumTopologyRuntime,
{
    transact_topology_update_with_destruction(topology, runtime, apply, None)
}

fn transact_topology_update_with_destruction<Runtime>(
    topology: &mut ProductionCdpTopology,
    runtime: &Runtime,
    apply: impl FnOnce(
        &mut pwright_backend_cdp::CdpTopology,
    ) -> Result<CdpTopologyUpdate, pwright_backend_cdp::CdpTopologyError>,
    destruction: Option<native_world_retirement::Destruction<'_>>,
) -> Result<CdpTopologyUpdate, ChromiumCompositionError>
where
    Runtime: ChromiumTopologyRuntime,
{
    let prepared = topology.prepare_transition(apply)?;
    let mut handle_retirement =
        prepare_aggregate_handle_topology_retirement(runtime.page_services(), prepared.output())?;
    let routes = runtime
        .page_services()
        .prepare_synchronization(prepared.topology())?;
    if let Some(destruction) = destruction {
        routes.observe_native_destruction(destruction)?;
    }
    let mut lifecycle = handle_retirement
        .as_ref()
        .into_iter()
        .flat_map(PreparedChromiumAggregateHandleTopologyRetirement::lifecycle_messages)
        .collect::<Vec<_>>();
    lifecycle.extend(topology_lifecycle_messages(prepared.output()));
    apply_topology_interruptions(runtime, prepared.output())?;
    let removed = runtime.apply_topology_lifecycle(&lifecycle)?;
    if let Some(retirement) = &mut handle_retirement {
        retirement.include_removed(&removed);
    }
    routes.commit();
    if let Some(retirement) = handle_retirement {
        retirement.commit();
    }
    Ok(prepared.commit())
}

fn topology_lifecycle_messages(update: &CdpTopologyUpdate) -> Vec<ControlMessage> {
    update
        .effects()
        .iter()
        .filter_map(|effect| match effect {
            CdpTopologyEffect::Lifecycle(message) => Some(*message),
            _ => None,
        })
        .collect()
}

fn apply_topology_interruptions<Runtime>(
    runtime: &Runtime,
    update: &CdpTopologyUpdate,
) -> Result<(), RuntimeStateError>
where
    Runtime: ChromiumTopologyRuntime,
{
    for effect in update.effects() {
        if let CdpTopologyEffect::PageCrashed {
            page,
            status,
            error_code,
        } = effect
        {
            runtime.interrupt_crashed_page(*page, status, *error_code)?;
        }
    }
    Ok(())
}

/// Applies backend subscription cleanup for every object disposed by an
/// already-committed topology update. Missing Page routes are treated as
/// successfully retired by the Chromium activator; other failures retain the
/// failed logical route so the caller can retry this same update.
pub async fn deactivate_disposed_page_subscriptions<Runtime, Codec>(
    update: &CdpTopologyUpdate,
    controls: &mut ActivatedRuntimeControlReceiver<
        Runtime,
        Codec,
        ChromiumPageSubscriptionActivator,
    >,
) -> Result<
    usize,
    Box<
        ActivatedRuntimeControlError<
            RuntimeControlReceiveError<<Codec as WireCodec<ControlMessage>>::Error>,
            ChromiumSubscriptionActivationError,
        >,
    >,
>
where
    Codec: WireCodec<ControlMessage>,
{
    let mut deactivated = 0usize;
    for message in topology_lifecycle_messages(update) {
        if let ControlMessage::Dispose { object_id } = message {
            deactivated = deactivated.saturating_add(
                controls
                    .deactivate_and_forget_object(object_id)
                    .await
                    .map_err(Box::new)?,
            );
        }
    }
    Ok(deactivated)
}

