    pub fn handle_lifecycle_handlers<Service>(
        &self,
        service: Arc<Service>,
    ) -> Result<Option<HandleLifecycleServerHandlers<Service>>, ProductionResourceError> {
        self.handle_lifecycle_protocol().map(|protocol| {
            protocol.map(|protocol| {
                handle_lifecycle_server_handlers(
                    Arc::new(protocol),
                    HandleLifecycleServerServices {
                        handle_dispose: service,
                    },
                )
            })
        })
    }

    /// Builds a cancellation-safe in-process Handle-evaluation handler. The
    /// continuation executor is caller-owned and is reserved before CDP work.
    pub fn handle_evaluation_handlers<Create, Dispose, Operations, Continuation>(
        &self,
        create: Arc<Create>,
        dispose: Arc<Dispose>,
        operations: Arc<Operations>,
        continuation: Continuation,
    ) -> HandleEvaluationHandlersResult<Create, Dispose, Operations, Continuation>
    where
        Continuation: ReservedCleanupExecutor + Clone,
    {
        self.handle_evaluation_protocol().map(|protocol| {
            protocol.map(|protocol| {
                let continuable =
                    ContinuableEvaluateHandleCommandService::new(create, dispose, continuation);
                handle_evaluation_server_handlers(
                    Arc::new(protocol),
                    HandleEvaluationServerServices {
                        evaluate_handle: Arc::new(continuable),
                        handle_evaluate: Arc::clone(&operations),
                        handle_evaluate_handle: Arc::clone(&operations),
                        handle_get_properties: Arc::clone(&operations),
                        handle_get_property: Arc::clone(&operations),
                        handle_json_value: operations,
                    },
                )
            })
        })
    }

    /// Builds value evaluation from the exact limits negotiated for this
    /// connection. No handle capability is installed implicitly.
    pub fn remote_evaluation_handlers<Service, Authorization>(
        &self,
        service: Arc<Service>,
        accepted: &AcceptedServerHandshake<Authorization>,
    ) -> Result<Option<EvaluationServerHandlers<Service>>, ProductionResourceError> {
        if accepted_capability_version(
            accepted.hello(),
            pwright_cap_evaluation::EVALUATION_CAPABILITY_ID,
        )
        .is_none()
        {
            return Ok(None);
        }
        self.profile
            .evaluation
            .map(|profile| {
                let protocol = accepted
                    .application_protocol(EvaluationCodec::new(profile.codec()))
                    .with_production_resources(&self.resources)?;
                Ok(evaluation_server_handlers(
                    Arc::new(protocol),
                    EvaluationServerServices {
                        evaluate_value: service,
                    },
                ))
            })
            .transpose()
    }

    /// Installs only the negotiated Handle-disposal protocol and fences its
    /// success behind the shared ordered lifecycle stream.
    pub fn remote_handle_lifecycle_handlers<Service, Runtime, Transport, Authorization>(
        &self,
        service: Arc<Service>,
        control: &ChromiumRemoteControlOutbound<Runtime, Transport>,
        accepted: &AcceptedServerHandshake<Authorization>,
    ) -> Result<
        Option<ChromiumRemoteHandleLifecycleHandlers<Service, Runtime, Transport>>,
        ProductionResourceError,
    > {
        if accepted_capability_version(accepted.hello(), HANDLE_LIFECYCLE_CAPABILITY_ID).is_none() {
            return Ok(None);
        }
        self.profile
            .handle_lifecycle
            .map(|profile| {
                let protocol = accepted
                    .application_protocol(HandleLifecycleCodec::new(profile.codec()))
                    .with_production_resources(&self.resources)?;
                let ordered = OrderedHandleDisposeCommandService::new(
                    service,
                    OrderedRuntimeControl::clone(control),
                );
                Ok(handle_lifecycle_server_handlers(
                    Arc::new(protocol),
                    HandleLifecycleServerServices {
                        handle_dispose: Arc::new(ordered),
                    },
                ))
            })
            .transpose()
    }

    /// Installs only negotiated Handle evaluation. The fixed decorator order
    /// is raw creation -> ordered Create -> continuation ownership; abandoned
    /// calls dispose through the same ordered Handle-lifecycle service.
    pub fn remote_handle_evaluation_handlers<
        Create,
        Dispose,
        Operations,
        Continuation,
        Runtime,
        Transport,
        Authorization,
    >(
        &self,
        create: Arc<Create>,
        dispose: Arc<Dispose>,
        operations: Arc<Operations>,
        continuation: Continuation,
        control: &ChromiumRemoteControlOutbound<Runtime, Transport>,
        accepted: &AcceptedServerHandshake<Authorization>,
    ) -> ChromiumRemoteHandleEvaluationHandlersResult<
        Create,
        Dispose,
        Operations,
        Runtime,
        Transport,
        Continuation,
    >
    where
        Continuation: ReservedCleanupExecutor + Clone,
    {
        let Some(capability_version) =
            accepted_capability_version(accepted.hello(), HANDLE_EVALUATION_CAPABILITY_ID)
        else {
            return Ok(None);
        };
        self.profile
            .handle_evaluation
            .map(|profile| {
                let protocol = accepted
                    .application_protocol(
                        HandleEvaluationCodec::new(profile.codec())
                            .with_capability_version(capability_version),
                    )
                    .with_production_resources(&self.resources)?;
                Ok(ChromiumRemoteHandleEvaluationHandler::new(
                    Arc::new(protocol),
                    create,
                    operations,
                    dispose,
                    continuation,
                    OrderedRuntimeControl::clone(control),
                ))
            })
            .transpose()
    }

