    /// Binds the optional Handle producer and disposer to the exact route
    /// table owned by this attachment's controlled Page runtime.
    pub fn handle_services<Deadlines, Cleanup>(
        &self,
        runtime: &ControlledDispatcher<CdpPageServices, CdpPageServices, Deadlines, Cleanup>,
    ) -> Result<Option<AttachedHandleServices>, ChromiumCompositionError>
    where
        Deadlines: DeadlineScheduler,
        Cleanup: CleanupExecutor,
    {
        let Some(profile) = self.prepared.profile.handle_evaluation else {
            return Ok(None);
        };
        let routes = runtime.service().handle_routes().ok_or_else(|| {
            ChromiumCompositionError::InvalidHandleSetup(
                "Handle evaluation runtime has no lifecycle route table".to_owned(),
            )
        })?;
        let object_ids: Arc<dyn ObjectIdSource> = self.object_ids.clone();
        let create = ChromiumEvaluateHandleCommandService::new(
            runtime.service().clone(),
            runtime.lifecycle_handle(),
            object_ids,
            routes.clone(),
            profile.native_id_bytes(),
            profile.preview_bytes(),
        );
        let operations = ChromiumHandleOperationCommandService::new(
            runtime.service().clone(),
            runtime.lifecycle_handle(),
            self.object_ids.clone(),
            routes.clone(),
            profile.native_id_bytes(),
            profile.preview_bytes(),
            CdpHandlePropertyLimits::new(
                profile.codec().value().max_entries(),
                profile.codec().value().max_string_bytes(),
            )
            .map_err(|error| ChromiumCompositionError::InvalidHandleSetup(error.to_string()))?,
        );
        let dispose = ChromiumHandleDisposeCommandService::new(runtime.lifecycle_handle(), routes);
        Ok(Some((create, dispose, operations)))
    }

    /// Binds the complete Handle command family to the independent evaluation
    /// and lifecycle leaves while reusing this aggregate's live Frame/world
    /// topology resolver.
    pub fn handle_leaf_services<Deadlines, Cleanup, AdoptionContinuation>(
        &self,
        runtime: &ControlledDispatcher<CdpPageServices, CdpPageServices, Deadlines, Cleanup>,
        adoption_continuation: AdoptionContinuation,
    ) -> Result<Option<AttachedHandleLeafServices>, ChromiumCompositionError>
    where
        Deadlines: DeadlineScheduler,
        Cleanup: CleanupExecutor,
        AdoptionContinuation: ReservedCleanupExecutor,
    {
        let Some(profile) = self.prepared.profile.handle_evaluation else {
            return Ok(None);
        };
        let routes = runtime.service().handle_leaf_routes().ok_or_else(|| {
            ChromiumCompositionError::InvalidHandleSetup(
                "Handle leaf evaluation runtime has no lifecycle-leaf route table".to_owned(),
            )
        })?;
        let properties = CdpHandlePropertyLimits::new(
            profile.codec().value().max_entries(),
            profile.codec().value().max_string_bytes(),
        )
        .map_err(|error| ChromiumCompositionError::InvalidHandleSetup(error.to_string()))?;
        let backend = ChromiumHandleLeafEvaluationBackendProfile::new(
            profile.backend(),
            profile.native_id_bytes(),
            profile.preview_bytes(),
            properties,
        );
        let resolver: Arc<dyn ChromiumHandleLeafRouteResolver> =
            Arc::new(runtime.service().clone());
        let mut evaluation = ChromiumHandleLeafEvaluationCommandService::new_with_route_resolver(
            runtime.lifecycle_handle(),
            self.object_ids.clone(),
            resolver,
            routes.clone(),
            backend,
        );
        if let Some(profile) = self.prepared.profile.handle_element_adoption() {
            let adoption = CdpElementHandleAdoptionBatchService::new_with_production_resources(
                profile,
                &self.prepared.resources,
            )
            .map_err(|error| ChromiumCompositionError::InvalidHandleSetup(error.to_string()))?;
            evaluation =
                evaluation.with_element_handle_adoption(Arc::new(adoption), adoption_continuation);
        }
        let dispose =
            ChromiumHandleLeafDisposeCommandService::new(runtime.lifecycle_handle(), routes);
        Ok(Some((evaluation, dispose)))
    }

