    pub fn new_direct_runtime<Service>(
        &mut self,
        service: Service,
    ) -> Result<DirectDispatcher<Service>, ChromiumCompositionError> {
        if self.runtime_installed {
            return Err(ChromiumCompositionError::RuntimeAlreadyInstalled);
        }
        let runtime = self
            .prepared
            .new_direct_runtime(service, self.browser_object_id)?;
        self.runtime_installed = true;
        Ok(runtime)
    }

    pub fn new_controlled_runtime<Service, Cancellation, Deadlines, Cleanup>(
        &mut self,
        service: Service,
        cancellation: Cancellation,
        deadlines: Deadlines,
        cleanup: Cleanup,
    ) -> Result<
        ControlledDispatcher<Service, Cancellation, Deadlines, Cleanup>,
        ChromiumCompositionError,
    >
    where
        Deadlines: DeadlineScheduler,
        Cleanup: CleanupExecutor,
    {
        if self.runtime_installed {
            return Err(ChromiumCompositionError::RuntimeAlreadyInstalled);
        }
        let runtime = self.prepared.new_controlled_runtime(
            service,
            cancellation,
            deadlines,
            cleanup,
            self.browser_object_id,
        )?;
        self.runtime_installed = true;
        Ok(runtime)
    }

    /// Installs the concrete target-aware Page service exactly once.
    ///
    /// The returned runtime owns the route table. After topology transitions,
    /// call `runtime.service().synchronize(&composition.topology()?)` before
    /// accepting commands that depend on the changed routes.
    pub fn new_page_runtime(
        &mut self,
    ) -> Result<DirectDispatcher<CdpPageServices>, ChromiumCompositionError> {
        if self.runtime_installed {
            return Err(ChromiumCompositionError::RuntimeAlreadyInstalled);
        }
        let session_factory: Arc<dyn SessionFactory> =
            Arc::new(CdpSessionFactory::new(Arc::clone(&self.connection)));
        let services = CdpPageServices::new_with_production_resources(
            session_factory,
            &self.prepared.profile,
            &self.prepared.resources,
        )?;
        {
            let topology = self.topology()?;
            services.synchronize(&topology)?;
        }
        let runtime = self
            .prepared
            .new_direct_runtime(services, self.browser_object_id)?;
        self.runtime_installed = true;
        Ok(runtime)
    }

    /// Installs a target-aware Page runtime with explicit deadline and bounded
    /// cleanup plugins. The same route table handles commands and their
    /// target-specific cancellation cleanup.
    pub fn new_controlled_page_runtime<Deadlines, Cleanup>(
        &mut self,
        deadlines: Deadlines,
        cleanup: Cleanup,
    ) -> Result<
        ControlledDispatcher<CdpPageServices, CdpPageServices, Deadlines, Cleanup>,
        ChromiumCompositionError,
    >
    where
        Deadlines: DeadlineScheduler,
        Cleanup: CleanupExecutor,
    {
        if self.runtime_installed {
            return Err(ChromiumCompositionError::RuntimeAlreadyInstalled);
        }
        let session_factory: Arc<dyn SessionFactory> =
            Arc::new(CdpSessionFactory::new(Arc::clone(&self.connection)));
        let services = CdpPageServices::new_with_production_resources(
            session_factory,
            &self.prepared.profile,
            &self.prepared.resources,
        )?;
        {
            let topology = self.topology()?;
            services.synchronize(&topology)?;
        }
        let runtime = self.prepared.new_controlled_runtime(
            services.clone(),
            services,
            deadlines,
            cleanup,
            self.browser_object_id,
        )?;
        self.runtime_installed = true;
        Ok(runtime)
    }

    /// Installs the target-aware aggregate runtime with Handle route ownership
    /// delegated to the independent lifecycle leaf. Existing callers keep the
    /// compatibility registry through `new_controlled_page_runtime`.
    pub fn new_controlled_page_runtime_with_handle_leaf<Deadlines, Cleanup>(
        &mut self,
        deadlines: Deadlines,
        cleanup: Cleanup,
    ) -> Result<
        ControlledDispatcher<CdpPageServices, CdpPageServices, Deadlines, Cleanup>,
        ChromiumCompositionError,
    >
    where
        Deadlines: DeadlineScheduler,
        Cleanup: CleanupExecutor,
    {
        if self.runtime_installed {
            return Err(ChromiumCompositionError::RuntimeAlreadyInstalled);
        }
        let lifecycle = self.prepared.profile.handle_lifecycle().ok_or_else(|| {
            ChromiumCompositionError::InvalidHandleSetup(
                "Handle lifecycle must be selected before leaf route ownership".to_owned(),
            )
        })?;
        let routes = ChromiumHandleLeafLifecycleRoutes::new_with_production_resources(
            lifecycle.routes().leaf_profile(),
            &self.prepared.resources,
        )
        .map_err(|error| ChromiumCompositionError::InvalidHandleSetup(error.to_string()))?;
        let session_factory: Arc<dyn SessionFactory> =
            Arc::new(CdpSessionFactory::new(Arc::clone(&self.connection)));
        let services = CdpPageServices::new_with_production_resources(
            session_factory,
            &self.prepared.profile,
            &self.prepared.resources,
        )?
        .with_handle_leaf_routes(routes);
        {
            let topology = self.topology()?;
            services.synchronize(&topology)?;
        }
        let runtime = self.prepared.new_controlled_runtime(
            services.clone(),
            services,
            deadlines,
            cleanup,
            self.browser_object_id,
        )?;
        self.runtime_installed = true;
        Ok(runtime)
    }

