    /// runtime, transport, accepted handshake, and production ledger.
    pub fn remote_control_parts<Runtime, Transport, Authorization>(
        &self,
        runtime: Arc<Runtime>,
        transport: Arc<Transport>,
        accepted: &AcceptedServerHandshake<Authorization>,
    ) -> Result<Option<ChromiumRemoteControlParts<Runtime, Transport>>, ChromiumCompositionError>
    {
        self.prepared
            .remote_control_parts(runtime, transport, accepted)
    }

    /// Composes one accepted Browser terminal-event installation around the
    /// caller's existing control handler and ordered control lane.
    ///
    /// The returned publisher is the same one shared by native-disconnect
    /// cleanup and the liveness backend; pass a clone to an owned
    /// `Browser.close` service so both terminal paths remain at-most-once.
    pub fn remote_browser_disconnect_parts<Inner, Source, Transport, Authorization>(
        &self,
        inner: Inner,
        lifecycle: ControlledLifecycleHandle,
        control: &ChromiumRemoteControlOutbound<Source, Transport>,
        transport: Arc<Transport>,
        accepted: &AcceptedServerHandshake<Authorization>,
    ) -> Result<
        Option<ChromiumRemoteBrowserDisconnectParts<Inner, Source, Transport>>,
        ProductionResourceError,
    > {
        let Some(disconnected) = self.prepared.remote_browser_disconnected_publisher(
            self.browser_object_id,
            transport,
            accepted,
        )?
        else {
            return Ok(None);
        };
        let liveness = ChromiumEventfulCdpLivenessBackend::new(
            self.connection_liveness_backend(),
            lifecycle.clone(),
            self.browser_object_id,
            disconnected.clone(),
        );
        let signal = liveness.native_disconnect_signal();
        let control_handler = BrowserDisconnectedControlHandler::new(
            inner,
            signal,
            lifecycle,
            self.browser_object_id,
            OrderedRuntimeControl::clone(control),
            disconnected.clone(),
        );
        Ok(Some((control_handler, liveness, disconnected)))
    }

