    /// Builds one negotiated typed-event queue/outbound pair selected by this
    /// exact attachment. Omitted event capabilities still return `None`.
    pub fn remote_event_parts<S, Codec, Transport, Authorization>(
        &self,
        codec: Codec,
        transport: Arc<Transport>,
        accepted: &AcceptedServerHandshake<Authorization>,
        overflow: OverflowPolicy,
        retained_bytes: fn(&Event<S>) -> usize,
    ) -> Result<Option<ChromiumRemoteEventParts<S, Codec, Transport>>, ServerEventProductionError>
    where
        S: CapabilityEventSpec,
        S::Payload: Send,
        Transport: ProductionFrameTransport + ?Sized,
    {
        self.prepared
            .remote_event_parts(codec, transport, accepted, overflow, retained_bytes)
    }

