    macro_rules! delegate_test_wire_codec {
        ($message:ty, $field:ident, $codec:ty, $error:ty) => {
            impl WireCodec<$message> for NavigationLocatorV2ClientCodec {
                type Error = String;

                fn encode_parts(&self, message: &$message) -> Result<EncodedParts, Self::Error> {
                    <$codec as WireCodec<$message>>::encode_parts(&self.$field, message)
                        .map_err(|error: $error| error.to_string())
                }

                fn decode_frame(&self, frame: WireFrame) -> Result<$message, Self::Error> {
                    <$codec as WireCodec<$message>>::decode_frame(&self.$field, frame)
                        .map_err(|error: $error| error.to_string())
                }
            }
        };
    }

    delegate_test_wire_codec!(
        Command<Goto>,
        navigation,
        NavigationCodec,
        NavigationCodecError
    );
    delegate_test_wire_codec!(
        CommandResult<Goto>,
        navigation,
        NavigationCodec,
        NavigationCodecError
    );
    delegate_test_wire_codec!(
        Command<locator_v2::Click>,
        locator,
        LocatorV2Codec,
        LocatorCodecError
    );
    delegate_test_wire_codec!(
        CommandResult<locator_v2::Click>,
        locator,
        LocatorV2Codec,
        LocatorCodecError
    );

