    struct MemoryTransport {
        incoming: Mutex<VecDeque<WireFrame>>,
        sent: Mutex<Vec<WireFrame>>,
    }

    impl MemoryTransport {
        fn new(incoming: impl IntoIterator<Item = WireFrame>) -> Self {
            Self {
                incoming: Mutex::new(incoming.into_iter().collect()),
                sent: Mutex::new(Vec::new()),
            }
        }
    }

    impl FrameTransport for MemoryTransport {
        type Error = Infallible;
        type Send<'a> = Ready<Result<(), Self::Error>>;
        type Receive<'a> = Ready<Result<Option<WireFrame>, Self::Error>>;

        fn send(&self, frame: WireFrame) -> Self::Send<'_> {
            self.sent
                .lock()
                .expect("sent frames should be available")
                .push(frame);
            ready(Ok(()))
        }

        fn receive(&self) -> Self::Receive<'_> {
            ready(Ok(self
                .incoming
                .lock()
                .expect("incoming frames should be available")
                .pop_front()))
        }
    }

    impl ShutdownFrameTransport for MemoryTransport {
        type Shutdown<'a> = Ready<Result<(), Self::Error>>;

        fn shutdown(&self) -> Self::Shutdown<'_> {
            ready(Ok(()))
        }
    }

    struct ProductionMemoryTransport {
        inner: MemoryTransport,
        ledger: ResourceLedger,
        requirements: ResourceRequirements,
        shutdowns: Arc<AtomicUsize>,
    }

    impl ProductionMemoryTransport {
        fn new(
            incoming: impl IntoIterator<Item = WireFrame>,
            resources: &ProductionResourceLedger,
            requirements: ResourceRequirements,
        ) -> Self {
            Self {
                inner: MemoryTransport::new(incoming),
                ledger: resources
                    .claim(requirements)
                    .expect("production memory transport was declared"),
                requirements,
                shutdowns: Arc::new(AtomicUsize::new(0)),
            }
        }

        fn shutdown_counter(&self) -> Arc<AtomicUsize> {
            Arc::clone(&self.shutdowns)
        }

        fn push_incoming(&self, frame: WireFrame) {
            self.inner
                .incoming
                .lock()
                .expect("incoming frames should be available")
                .push_back(frame);
        }

        fn sent_frames(&self) -> Vec<WireFrame> {
            self.inner
                .sent
                .lock()
                .expect("sent frames should be available")
                .clone()
        }
    }

    impl FrameTransport for ProductionMemoryTransport {
        type Error = Infallible;
        type Send<'a> = Ready<Result<(), Self::Error>>;
        type Receive<'a> = Ready<Result<Option<WireFrame>, Self::Error>>;

        fn send(&self, frame: WireFrame) -> Self::Send<'_> {
            self.inner.send(frame)
        }

        fn receive(&self) -> Self::Receive<'_> {
            self.inner.receive()
        }
    }

    impl ProductionFrameTransport for ProductionMemoryTransport {
        fn production_resources(&self) -> ProductionTransportResources<'_> {
            ProductionTransportResources::new(&self.ledger, self.requirements)
        }
    }

    impl ShutdownFrameTransport for ProductionMemoryTransport {
        type Shutdown<'a> = Ready<Result<(), Self::Error>>;

        fn shutdown(&self) -> Self::Shutdown<'_> {
            self.shutdowns.fetch_add(1, Ordering::SeqCst);
            ready(Ok(()))
        }
    }

    /// Server half of a real bounded, full-duplex in-memory connection. The
    /// peer half remains an ordinary `MemoryFrameTransport`, while this half
    /// proves that it was declared against the attachment's exact ledger.
    struct ProductionPairedMemoryTransport {
        inner: MemoryFrameTransport,
        ledger: ResourceLedger,
        requirements: ResourceRequirements,
    }

    impl ProductionPairedMemoryTransport {
        fn new(
            inner: MemoryFrameTransport,
            resources: &ProductionResourceLedger,
            requirements: ResourceRequirements,
        ) -> Self {
            Self {
                inner,
                ledger: resources
                    .claim(requirements)
                    .expect("paired production transport was declared"),
                requirements,
            }
        }
    }

    impl FrameTransport for ProductionPairedMemoryTransport {
        type Error = <MemoryFrameTransport as FrameTransport>::Error;
        type Send<'a> = <MemoryFrameTransport as FrameTransport>::Send<'a>;
        type Receive<'a> = <MemoryFrameTransport as FrameTransport>::Receive<'a>;

        fn send(&self, frame: WireFrame) -> Self::Send<'_> {
            self.inner.send(frame)
        }

        fn receive(&self) -> Self::Receive<'_> {
            self.inner.receive()
        }
    }

    impl ProductionFrameTransport for ProductionPairedMemoryTransport {
        fn production_resources(&self) -> ProductionTransportResources<'_> {
            ProductionTransportResources::new(&self.ledger, self.requirements)
        }
    }

    impl ShutdownFrameTransport for ProductionPairedMemoryTransport {
        type Shutdown<'a> = <MemoryFrameTransport as ShutdownFrameTransport>::Shutdown<'a>;

        fn shutdown(&self) -> Self::Shutdown<'_> {
            self.inner.shutdown()
        }
    }

    #[derive(Clone, Copy)]
    struct UnhandledCommands;

    impl ConcurrentServerFrameHandler<ProductionMemoryTransport> for UnhandledCommands {
        type Event = Infallible;
        type Error = Infallible;
        type Future = Ready<Result<ServerFrameDisposition<Self::Event>, Self::Error>>;

        fn handle_concurrently(
            &self,
            frame: WireFrame,
            _transport: Arc<ProductionMemoryTransport>,
        ) -> Self::Future {
            ready(Ok(ServerFrameDisposition::Unhandled(frame)))
        }
    }

    #[derive(Clone, Copy)]
    struct UnhandledControls;

    impl ServerControlFrameHandler for UnhandledControls {
        type Event = Infallible;
        type Error = Infallible;
        type Future<'a> = Ready<Result<ServerFrameDisposition<Self::Event>, Self::Error>>;
        type CloseFuture<'a> = Ready<Result<Option<Self::Event>, Self::Error>>;

        fn handle_control<'a>(&'a mut self, frame: WireFrame) -> Self::Future<'a> {
            ready(Ok(ServerFrameDisposition::Unhandled(frame)))
        }

        fn handle_transport_closed<'a>(&'a mut self) -> Self::CloseFuture<'a> {
            ready(Ok(None))
        }
    }

    impl RecordingSessionFactory {
        fn client(&self, target_id: &str) -> Arc<FakeCdpClient> {
            Arc::clone(
                self.clients
                    .lock()
                    .expect("fake session clients should be available")
                    .get(target_id)
                    .expect("target should have a fake client"),
            )
        }

        fn set_network_gate(&self, gate: Option<Arc<tokio::sync::Notify>>) {
            *self
                .network_gate
                .lock()
                .expect("fake network gate should be available") = gate;
        }

        fn method_names_for_target(&self, target_id: &str) -> Vec<String> {
            self.client_history
                .lock()
                .expect("fake client history should be available")
                .iter()
                .filter(|(target, _)| target == target_id)
                .flat_map(|(_, client)| client.method_names())
                .collect()
        }
    }

    impl SessionFactory for RecordingSessionFactory {
        fn create_session(&self, session_id: String, target_id: String) -> Arc<dyn CdpClient> {
            self.created
                .lock()
                .expect("created routes should be available")
                .push((session_id, target_id.clone()));
            let client = Arc::new(FakeCdpClient::from_html("<title>route</title>"));
            client.set_navigate_response(serde_json::json!({
                "frameId": format!("frame-{target_id}"),
                "loaderId": format!("loader-{target_id}")
            }));
            client.set_network_gate(
                self.network_gate
                    .lock()
                    .expect("fake network gate should be available")
                    .clone(),
            );
            self.client_history
                .lock()
                .expect("fake client history should be available")
                .push((target_id.clone(), Arc::clone(&client)));
            self.clients
                .lock()
                .expect("fake session clients should be available")
                .insert(target_id, Arc::clone(&client));
            client
        }
    }

