    #[test]
    fn controlled_target_concurrency_is_opt_in_without_increasing_shared_budgets() {
        // Arrange
        let serial = base_profile();
        let requirements = serial.requirements();
        let limits = serial.runtime;
        // Act
        let concurrent = serial
            .clone()
            .with_controlled_target_concurrency(std::num::NonZeroUsize::new(8).unwrap());
        // Assert
        assert_eq!(serial.controlled_target_concurrency().get(), 1);
        assert_eq!(concurrent.controlled_target_concurrency().get(), 8);
        assert_eq!(concurrent.runtime, limits);
        assert_eq!(concurrent.requirements(), requirements);
    }

    fn base_profile_with_runtime(runtime: RuntimeLimits) -> ChromiumAttachProductionProfile {
        base_profile_with_runtime_and_topology(runtime, CdpTopologyLimits::new(16, 4, 4, 8, 8, 128))
    }

    fn base_profile_with_runtime_and_topology(
        runtime: RuntimeLimits,
        topology_limits: CdpTopologyLimits,
    ) -> ChromiumAttachProductionProfile {
        let connection = pwright_cdp::CdpConnectionProductionProfile::new(
            pwright_core::ResourceScope::Connection,
            ConnectionConfig::default(),
        );
        let topology = pwright_backend_cdp::CdpTopologyProductionProfile::new(
            topology_limits,
            pwright_core::ResourceScope::extension(7, 1),
        )
        .expect("topology profile should validate");
        let supervisor = pwright_server_wire::ServerSupervisorLimits::new(2)
            .expect("supervisor limits should validate");
        let page_routes = CdpPageRouteProductionProfile::from_topology(
            pwright_core::ResourceScope::extension(7, 4),
            topology,
        );
        ChromiumAttachProductionProfile::new(connection, topology, page_routes, runtime, supervisor)
    }

    fn two_page_network_context() -> (
        CdpPageServices,
        Arc<RecordingSessionFactory>,
        ChromiumNetworkSubscriptionRegistry,
        ProductionCdpTopology,
    ) {
        let adapter = CdpNetworkEventProductionProfile::new(
            NetworkLifecycleLimits::new(2, 64, 256, 16, 32, 8, 256, 64, 64, 128),
            ResourceScope::extension(95, 2),
        )
        .expect("network adapter profile should validate");
        let network = ChromiumNetworkEventsProductionProfile::new_with_context_limit(adapter, 2, 1)
            .expect("two Page lanes in one Context should validate");
        let profile = base_profile_with_runtime(RuntimeLimits::new(24, 4).with_active_commands(2))
            .with_network_events(network);
        let requirements = profile.requirements();
        let resources = ProductionResourceLedger::new(exact_limits(requirements), requirements)
            .expect("network composition plan should fit");
        let epoch = ConnectionEpoch::new(1);
        let mut topology =
            ProductionCdpTopology::new(ObjectId::new(1), epoch, profile.topology(), &resources)
                .expect("topology should build");
        topology
            .register_context(
                epoch,
                "context-a",
                ObjectId::new(2),
                CdpContextOwnership::External,
            )
            .expect("Context should register");
        for (target, session, page, frame) in [
            ("target-a", "session-a", 3, 4),
            ("target-b", "session-b", 5, 6),
        ] {
            topology
                .attach_page(
                    epoch,
                    CdpPageTarget::new(target, session, "context-a"),
                    CdpPageObjectIds::new(ObjectId::new(page), ObjectId::new(frame)),
                )
                .expect("Page should attach");
        }
        let factory = Arc::new(RecordingSessionFactory::default());
        let services =
            CdpPageServices::new_with_production_resources(factory.clone(), &profile, &resources)
                .expect("network Page services should build");
        services
            .synchronize(&topology)
            .expect("Page routes should synchronize");
        let subscriptions = services
            .network_subscription_registry()
            .expect("network subscription registry should exist");
        subscriptions
            .register_page_lane(ObjectId::new(3), ObjectId::new(2), "session-a".to_owned())
            .expect("first Page lane should prepare");
        subscriptions
            .register_page_lane(ObjectId::new(5), ObjectId::new(2), "session-b".to_owned())
            .expect("second Page lane should prepare");
        (services, factory, subscriptions, topology)
    }

