    #[test]
    fn aggregate_handle_route_profile_converts_to_the_leaf_without_drift() {
        // Arrange
        let aggregate =
            ChromiumHandleRouteProductionProfile::new(ResourceScope::extension(7, 10), 4, 128, 256);

        // Act
        let leaf = aggregate.leaf_profile();

        // Assert
        assert_eq!(leaf.scope(), aggregate.resource_scope());
        assert_eq!(leaf.max_handles(), aggregate.max_handles());
        assert_eq!(leaf.max_native_id_bytes(), aggregate.max_native_id_bytes());
        assert_eq!(leaf.max_preview_bytes(), aggregate.max_preview_bytes());
        assert_eq!(leaf.requirements(), aggregate.requirements());
    }

    #[test]
    fn aggregate_page_event_profile_converts_to_the_leaf_without_drift() {
        // Arrange
        let aggregate = all_capabilities_profile(all_capabilities_handshake_profile());
        let selected = |event| {
            aggregate
                .remote_events()
                .iter()
                .find(|profile| profile.event() == event)
                .copied()
                .expect("all-capabilities profile should select every Page event")
        };
        let load = selected(PAGE_LOAD_EVENT_TAG);
        let context_page = selected(BROWSER_CONTEXT_PAGE_EVENT_TAG);
        let popup = selected(PAGE_POPUP_EVENT_TAG);

        // Act
        let leaf = aggregate
            .page_events_leaf_profile()
            .expect("complete Page-event selection should convert");

        // Assert
        assert_eq!(leaf.wire_version(), load.wire().version());
        assert_eq!(leaf.send_limits(), load.wire().send_limits());
        assert_eq!(leaf.receive_limits(), load.wire().receive_limits());
        assert_eq!(leaf.page_load_capacity(), load.capacity());
        assert_eq!(leaf.context_page_capacity(), context_page.capacity());
        assert_eq!(leaf.popup_capacity(), popup.capacity());
        assert_eq!(
            leaf.requirements(),
            load.requirements()
                .combine_concurrent(context_page.requirements())
                .combine_concurrent(popup.requirements())
        );
    }

    #[test]
    fn aggregate_page_event_profile_requires_all_three_lanes() {
        // Arrange
        let mut aggregate = all_capabilities_profile(all_capabilities_handshake_profile());
        aggregate
            .remote_events
            .retain(|profile| profile.event() != PAGE_POPUP_EVENT_TAG);

        // Act
        let leaf = aggregate.page_events_leaf_profile();

        // Assert
        assert_eq!(leaf, None);
    }

    #[test]
    fn aggregate_page_event_profile_rejects_mixed_wire_profiles() {
        // Arrange
        let mut aggregate = all_capabilities_profile(all_capabilities_handshake_profile());
        let popup = aggregate
            .remote_events
            .iter_mut()
            .find(|profile| profile.event() == PAGE_POPUP_EVENT_TAG)
            .expect("all-capabilities profile should select page.popup");
        popup.wire = CapabilityWireProfile::new(
            ProtocolVersion::new(1, 1),
            popup.wire.send_limits(),
            popup.wire.receive_limits(),
        );

        // Act
        let leaf = aggregate.page_events_leaf_profile();

        // Assert
        assert_eq!(leaf, None);
    }

    #[test]
    fn aggregate_network_event_delivery_converts_to_the_leaf_without_drift() {
        // Arrange
        let aggregate = all_capabilities_profile(all_capabilities_handshake_profile());
        let remote = aggregate
            .remote_network_events()
            .expect("all-capabilities profile should select ordered network delivery");

        // Act
        let leaf = aggregate
            .network_event_delivery_leaf_profile()
            .expect("matching network normalization and delivery should convert");

        // Assert
        assert_eq!(leaf.wire_version(), remote.wire().version());
        assert_eq!(leaf.send_limits(), remote.wire().send_limits());
        assert_eq!(leaf.receive_limits(), remote.wire().receive_limits());
        assert_eq!(leaf.codec(), remote.codec());
        assert_eq!(leaf.capacity(), remote.capacity());
        assert_eq!(
            leaf.max_retained_bytes_per_event(),
            remote.max_retained_bytes_per_event()
        );
        assert_eq!(leaf.requirements(), remote.requirements());
    }

    #[test]
    fn aggregate_network_event_delivery_requires_matching_normalization_limits() {
        // Arrange
        let mut aggregate = all_capabilities_profile(all_capabilities_handshake_profile());
        let remote = aggregate
            .remote_network_events
            .as_mut()
            .expect("all-capabilities profile should select ordered network delivery");
        remote.codec.url_bytes = remote.codec.url_bytes.saturating_add(1);

        // Act
        let leaf = aggregate.network_event_delivery_leaf_profile();

        // Assert
        assert_eq!(leaf, None);
    }

