    #[test]
    fn element_handle_adoption_is_an_opt_in_backend_without_a_new_capability() {
        // Arrange
        let base = base_profile_with_runtime(RuntimeLimits::new(24, 4))
            .with_handle_lifecycle(handle_lifecycle_profile())
            .with_handle_evaluation(handle_evaluation_profile());
        let capability_count = base.capabilities().len();
        let without_adoption = base.requirements();
        let profile = base.with_handle_element_adoption(handle_element_adoption_profile());
        let requirements = profile.requirements();

        // Act
        let prepared = PreparedChromiumAttach::new(profile.clone(), exact_limits(requirements))
            .expect("opted-in ElementHandle adoption should fit its exact plan");

        // Assert
        assert_eq!(profile.capabilities().len(), capability_count);
        assert!(profile.handle_element_adoption().is_some());
        assert!(
            requirements.class(ResourceClass::RemoteHandle).global
                > without_adoption.class(ResourceClass::RemoteHandle).global
        );
        assert_eq!(prepared.capability_manifest().len(), capability_count);
    }

