    type ContextCreationRuntime = ControlledDispatcher<(), (), NoDeadlineScheduler, CleanupQueue>;

    fn context_creation_state() -> (
        ContextCreationRuntime,
        Arc<Mutex<ProductionCdpTopology>>,
        Arc<FakeCdpClient>,
        ChromiumBrowserNewContextCommandService,
    ) {
        let epoch = ConnectionEpoch::new(1);
        let profile = base_profile_with_runtime(
            RuntimeLimits::new(16, 4)
                .with_active_commands(2)
                .with_control_messages(8),
        )
        .with_context_lifecycle(context_lifecycle_profile())
        .with_context_creation(context_creation_profile());
        let prepared =
            PreparedChromiumAttach::new(profile.clone(), exact_limits(profile.requirements()))
                .expect("context creation composition should prepare");
        let runtime = prepared
            .new_controlled_runtime(
                (),
                (),
                NoDeadlineScheduler,
                CleanupQueue::new(2),
                ObjectId::new(1),
            )
            .expect("controlled runtime should construct");
        assert!(runtime.pop_control_message().unwrap().is_some());
        let topology = Arc::new(Mutex::new(
            ProductionCdpTopology::new(
                ObjectId::new(1),
                epoch,
                profile.topology(),
                prepared.resources(),
            )
            .expect("production topology should construct"),
        ));
        let cdp = Arc::new(FakeCdpClient::from_html(""));
        cdp.set_create_browser_context_response("context-created");
        let backend = CdpBrowserContextCreationService::new(
            cdp.clone(),
            context_creation_profile().backend(),
        )
        .unwrap();
        let object_ids: Arc<dyn ObjectIdSource> = Arc::new(AtomicObjectIdSource::new(2).unwrap());
        let service = ChromiumBrowserNewContextCommandService::new(
            backend,
            cdp.clone(),
            Arc::clone(&topology),
            runtime.lifecycle_handle(),
            object_ids,
            ObjectId::new(1),
        );
        (runtime, topology, cdp, service)
    }

