    type ContextCloseRuntime = ControlledDispatcher<(), (), NoDeadlineScheduler, CleanupQueue>;

    fn context_close_state(
        ownership: CdpContextOwnership,
    ) -> (ContextCloseRuntime, Arc<Mutex<ProductionCdpTopology>>) {
        let epoch = ConnectionEpoch::new(1);
        let profile = base_profile_with_runtime(
            RuntimeLimits::new(16, 4)
                .with_active_commands(2)
                .with_control_messages(8),
        )
        .with_context_lifecycle(context_lifecycle_profile());
        let limits = exact_limits(profile.requirements());
        let prepared = PreparedChromiumAttach::new(profile.clone(), limits)
            .expect("context lifecycle composition should prepare");
        let runtime = prepared
            .new_controlled_runtime(
                (),
                (),
                NoDeadlineScheduler,
                CleanupQueue::new(2),
                ObjectId::new(1),
            )
            .expect("controlled runtime should construct");
        runtime
            .register_object(
                ObjectId::new(2),
                Some(ObjectId::new(1)),
                BROWSER_CONTEXT_OBJECT_KIND.tag,
            )
            .expect("context should register");
        runtime
            .register_object(
                ObjectId::new(3),
                Some(ObjectId::new(2)),
                PAGE_OBJECT_KIND.tag,
            )
            .expect("page should register");
        runtime
            .register_object(
                ObjectId::new(4),
                Some(ObjectId::new(3)),
                FRAME_OBJECT_KIND.tag,
            )
            .expect("frame should register");
        while runtime
            .pop_control_message()
            .expect("control outbox should remain readable")
            .is_some()
        {}

        let mut topology = ProductionCdpTopology::new(
            ObjectId::new(1),
            epoch,
            profile.topology(),
            prepared.resources(),
        )
        .expect("production topology should construct");
        topology
            .register_context(epoch, "context-a", ObjectId::new(2), ownership)
            .expect("context should map");
        topology
            .attach_page(
                epoch,
                CdpPageTarget::new("target-a", "session-a", "context-a"),
                CdpPageObjectIds::new(ObjectId::new(3), ObjectId::new(4)),
            )
            .expect("page should map");
        (runtime, Arc::new(Mutex::new(topology)))
    }

    type PageCloseRuntime =
        ControlledDispatcher<CdpPageServices, CdpPageServices, NoDeadlineScheduler, CleanupQueue>;

    fn page_close_state() -> (
        PageCloseRuntime,
        Arc<Mutex<ProductionCdpTopology>>,
        Arc<FakeCdpClient>,
        Arc<FakeCdpClient>,
    ) {
        let epoch = ConnectionEpoch::new(1);
        let profile = base_profile_with_runtime(
            RuntimeLimits::new(16, 4)
                .with_active_commands(2)
                .with_control_messages(8),
        )
        .with_page_lifecycle(page_lifecycle_profile());
        let prepared =
            PreparedChromiumAttach::new(profile.clone(), exact_limits(profile.requirements()))
                .unwrap();
        let mut topology = ProductionCdpTopology::new(
            ObjectId::new(1),
            epoch,
            profile.topology(),
            prepared.resources(),
        )
        .unwrap();
        topology
            .register_context(
                epoch,
                "context-a",
                ObjectId::new(2),
                CdpContextOwnership::Owned,
            )
            .unwrap();
        topology
            .attach_page(
                epoch,
                CdpPageTarget::new("target-a", "session-a", "context-a"),
                CdpPageObjectIds::new(ObjectId::new(3), ObjectId::new(4)),
            )
            .unwrap();
        let topology = Arc::new(Mutex::new(topology));
        let session_factory = Arc::new(RecordingSessionFactory::default());
        let services = CdpPageServices::new_with_production_resources(
            session_factory.clone(),
            &profile,
            prepared.resources(),
        )
        .unwrap();
        services.synchronize(&topology.lock().unwrap()).unwrap();
        let runtime = prepared
            .new_controlled_runtime(
                services.clone(),
                services,
                NoDeadlineScheduler,
                CleanupQueue::new(2),
                ObjectId::new(1),
            )
            .unwrap();
        runtime
            .register_object(
                ObjectId::new(2),
                Some(ObjectId::new(1)),
                BROWSER_CONTEXT_OBJECT_KIND.tag,
            )
            .unwrap();
        runtime
            .register_object(
                ObjectId::new(3),
                Some(ObjectId::new(2)),
                PAGE_OBJECT_KIND.tag,
            )
            .unwrap();
        runtime
            .register_object(
                ObjectId::new(4),
                Some(ObjectId::new(3)),
                FRAME_OBJECT_KIND.tag,
            )
            .unwrap();
        while runtime.pop_control_message().unwrap().is_some() {}
        (
            runtime,
            topology,
            Arc::new(FakeCdpClient::from_html("")),
            session_factory.client("target-a"),
        )
    }

