    fn handle_remote_client_hello(handshake: ChromiumRemoteHandshakeProfile) -> WireFrame {
        let codec = HandshakeCodec::new(handshake.negotiation_limits());
        let capability = |id: CapabilityId| {
            CapabilityRequirement::new(
                WireCapabilityId::new(id.as_str(), codec.limits().capability_id_bytes)
                    .expect("Handle capability ID should fit"),
                ProtocolVersion::new(1, 0),
            )
        };
        let client = ClientHello::new(
            VersionPolicy::exact(ProtocolVersion::new(1, 0)),
            wire_profile().receive_limits(),
            CapabilityRequest::new(
                vec![
                    capability(HANDLE_LIFECYCLE_CAPABILITY_ID),
                    capability(HANDLE_EVALUATION_CAPABILITY_ID),
                    control_protocol_requirement()
                        .expect("control protocol requirement should build"),
                ],
                Vec::new(),
                codec.limits(),
            )
            .expect("Handle capability request should build"),
        );
        let encoded = codec
            .encode_parts(&client)
            .expect("ClientHello should encode");
        WireFrame::new(
            ProtocolVersion::new(1, 0),
            FrameRoute::Handshake,
            encoded.payload().to_vec(),
            encoded.attachments().to_vec(),
            handshake.server_receive_limits(),
        )
        .expect("Handle ClientHello should fit")
    }

