    fn all_capabilities_profile(
        handshake: ChromiumRemoteHandshakeProfile,
    ) -> ChromiumAttachProductionProfile {
        all_capabilities_profile_with_topology(
            handshake,
            CdpTopologyLimits::new(16, 4, 4, 8, 8, 128),
        )
    }

    fn all_capabilities_profile_with_topology(
        handshake: ChromiumRemoteHandshakeProfile,
        topology_limits: CdpTopologyLimits,
    ) -> ChromiumAttachProductionProfile {
        let all_wire = CapabilityWireProfile::new(
            ProtocolVersion::new(1, 0),
            FrameLimits::new(4096, 1, 64, 4096),
            FrameLimits::new(4096, 1, 64, 4096),
        );
        let context_creation = context_creation_profile();
        let context_lifecycle = context_lifecycle_profile();
        let page_creation = page_creation_profile();
        let page_lifecycle = page_lifecycle_profile();
        let evaluation = evaluation_profile();
        let handle_lifecycle = handle_lifecycle_profile();
        let handle_evaluation = handle_evaluation_profile();
        let navigation = navigation_profile();
        let locator = locator_profile();
        let locator_screenshot = locator_screenshot_profile();
        let content = content_profile();
        let dom_content = dom_content_profile();
        let network_lifecycle =
            NetworkLifecycleLimits::new(8, 64, 256, 16, 32, 8, 256, 64, 64, 128);
        let network_adapter = CdpNetworkEventProductionProfile::new(
            network_lifecycle,
            ResourceScope::extension(95, 2),
        )
        .expect("all-capability network adapter profile should validate");
        let network = ChromiumNetworkEventsProductionProfile::new(network_adapter, 4)
            .expect("all-capability network driver profile should validate");
        let base = base_profile_with_runtime_and_topology(
            RuntimeLimits::new(128, 8)
                .with_active_commands(4)
                .with_control_messages(64),
            topology_limits,
        )
        .with_supervisor(
            pwright_server_wire::ServerSupervisorLimits::new(4)
                .expect("all-capability supervisor limits should validate"),
        )
        .with_context_creation(ContextCreationInstallationProfile::new(
            context_creation.backend(),
            context_creation.codec(),
            all_wire,
        ))
        .with_context_lifecycle(ContextLifecycleInstallationProfile::new(
            context_lifecycle.codec(),
            all_wire,
        ))
        .with_page_creation(PageCreationInstallationProfile::new(
            page_creation.backend(),
            page_creation.codec(),
            all_wire,
        ))
        .with_page_lifecycle(PageLifecycleInstallationProfile::new(
            page_lifecycle.backend(),
            page_lifecycle.codec(),
            all_wire,
        ))
        .with_evaluation(EvaluationInstallationProfile::new(
            evaluation.backend(),
            evaluation.codec(),
            all_wire,
        ))
        .with_handle_lifecycle(HandleLifecycleInstallationProfile::new(
            handle_lifecycle.routes(),
            handle_lifecycle.codec(),
            all_wire,
        ))
        .with_handle_evaluation(HandleEvaluationInstallationProfile::new(
            handle_evaluation.backend(),
            handle_evaluation.native_id_bytes(),
            handle_evaluation.preview_bytes(),
            handle_evaluation.codec(),
            all_wire,
        ))
        .with_navigation(NavigationInstallationProfile::new(
            navigation.backend(),
            navigation.codec(),
            all_wire,
        ))
        .with_locator(LocatorInstallationProfile::new(
            locator.backend(),
            locator.codec(),
            all_wire,
        ))
        .with_locator_screenshot(LocatorScreenshotInstallationProfile::new(
            locator_screenshot.locator_backend(),
            locator_screenshot.screenshot_backend(),
            locator_screenshot.codec(),
            all_wire,
        ))
        .with_content(ContentInstallationProfile::new(
            content.backend(),
            content.codec(),
            all_wire,
        ))
        .with_dom_content(DomContentInstallationProfile::new(
            dom_content.backend(),
            dom_content.codec(),
            all_wire,
        ))
        .with_network_events(network)
        .with_utility_world(ChromiumUtilityWorldProfile::playwright_compatible())
        .with_page_events();
        let topology_events = ChromiumTopologyEventDriverProductionProfile::from_profiles(
            ResourceScope::extension(7, 6),
            base.connection(),
            base.topology(),
        )
        .expect("all-capability topology-event profile should validate");
        let discovery = ChromiumPageDiscoveryProductionProfile::from_profiles(
            base.connection(),
            base.topology(),
        );
        base.with_topology_events(topology_events)
            .with_page_discovery(discovery)
            .with_remote_handshake(handshake)
            .with_remote_control(remote_control_profile())
            .with_remote_event(ChromiumRemoteEventProfile::new::<PageLoad>(all_wire, 4, 0))
            .with_remote_event(ChromiumRemoteEventProfile::new::<BrowserContextPage>(
                all_wire,
                4,
                size_of::<u64>(),
            ))
            .with_remote_event(ChromiumRemoteEventProfile::new::<PagePopup>(
                all_wire,
                4,
                size_of::<u64>(),
            ))
            .with_remote_network_events(ChromiumRemoteNetworkEventProfile::new(
                all_wire,
                NetworkEventsCodecLimits::from_lifecycle(network_lifecycle),
                16,
                4096,
            ))
            .with_derived_reclaiming_event_fanout()
            .expect("all selected event consumers should derive a bounded fanout")
    }

