    const UNINSTALLED_EVENT_CAPABILITY_ID: CapabilityId =
        CapabilityId::new("test.uninstalled-events");
    const UNINSTALLED_EVENT_ID: EventId = EventId::new("test.uninstalled-event");
    const UNINSTALLED_EVENT_TAG: EventTag = EventTag::new(9_000_001);
    const UNINSTALLED_EVENT_IDS: &[EventId] = &[UNINSTALLED_EVENT_ID];

    struct UninstalledEventCapability;

    impl Capability for UninstalledEventCapability {
        const DESCRIPTOR: CapabilityDescriptor = CapabilityDescriptor::new(
            PluginInfo::new(
                UNINSTALLED_EVENT_CAPABILITY_ID,
                "Uninstalled test events",
                ProtocolVersion::new(1, 0),
            ),
            &[],
            &[],
        )
        .with_events(UNINSTALLED_EVENT_IDS);
    }

    struct UninstalledEvent;

    impl EventSpec for UninstalledEvent {
        const EVENT: EventTag = UNINSTALLED_EVENT_TAG;
        type Payload = ();
    }

    impl CapabilityEventSpec for UninstalledEvent {
        type Capability = UninstalledEventCapability;
        const EVENT_ID: EventId = UNINSTALLED_EVENT_ID;
        const TARGET_OBJECT_KINDS: &'static [pwright_core::ObjectKindId] = &[PAGE_OBJECT_KIND.id];
    }

    fn exact_limits(requirements: pwright_core::ResourceRequirements) -> ResourceLimits {
        let mut limits = ResourceLimits::deny_all(requirements.scopes, requirements.leases);
        for class in ResourceClass::ALL {
            let required = requirements.class(class);
            limits = limits.with_class(class, required.global, required.per_scope);
        }
        limits
    }

    struct LivePageRuntime {
        page: ObjectId,
    }

    impl CancellationTarget for LivePageRuntime {
        fn cancel_call(
            &self,
            _call_id: CallId,
            _cancellation: CancellationId,
            _reason: CancellationReason,
        ) -> Result<CancellationRequestOutcome, RuntimeStateError> {
            Ok(CancellationRequestOutcome::Requested)
        }

        fn is_object_live(&self, object_id: ObjectId) -> Result<bool, RuntimeStateError> {
            Ok(object_id == self.page)
        }
    }

