    #[test]
    fn handle_plugins_install_without_value_evaluation() {
        // Arrange
        let profile = base_profile_with_runtime(RuntimeLimits::new(20, 4).with_active_commands(2))
            .with_handle_lifecycle(handle_lifecycle_profile())
            .with_handle_evaluation(handle_evaluation_profile());
        let requirements = profile.requirements();

        // Act
        let prepared = PreparedChromiumAttach::new(profile.clone(), exact_limits(requirements))
            .expect("independent Handle plugins should prepare");
        let session_factory: Arc<dyn SessionFactory> = Arc::new(RecordingSessionFactory::default());
        let services = CdpPageServices::new_with_production_resources(
            session_factory,
            &profile,
            prepared.resources(),
        )
        .expect("Handle routes should use their declared production plan");
        let handle_lifecycle = WireCapabilityId::new("pwright.handle_lifecycle", 128).unwrap();
        let handle_evaluation = WireCapabilityId::new("pwright.handle_evaluation", 128).unwrap();
        let value_evaluation = WireCapabilityId::new("pwright.evaluation", 128).unwrap();

        // Assert
        assert_eq!(profile.capabilities().len(), 2);
        assert_eq!(prepared.capability_manifest().len(), 2);
        assert!(
            prepared
                .capability_manifest()
                .support(&handle_lifecycle)
                .is_some()
        );
        assert!(
            prepared
                .capability_manifest()
                .support(&handle_evaluation)
                .is_some()
        );
        assert!(
            prepared
                .capability_manifest()
                .support(&value_evaluation)
                .is_none()
        );
        assert!(
            prepared
                .backend_manifest()
                .supports(CDP_HANDLE_DISPOSE_FEATURE)
        );
        assert!(
            prepared
                .backend_manifest()
                .supports(CDP_EVALUATE_HANDLE_FEATURE)
        );
        assert!(
            !prepared
                .backend_manifest()
                .supports(CDP_EVALUATE_VALUE_FEATURE)
        );
        assert!(services.evaluation.is_none());
        assert!(services.handle_evaluation.is_some());
        assert!(services.handle_routes().is_some());
        assert!(prepared.evaluation_protocol().unwrap().is_none());
        assert!(prepared.handle_lifecycle_protocol().unwrap().is_some());
        assert!(prepared.handle_evaluation_protocol().unwrap().is_some());
    }

    #[tokio::test]
    async fn negotiated_handle_plugins_install_only_after_handshake_selection() {
        // Arrange
        let handshake = handle_remote_handshake_profile();
        let profile = base_profile_with_runtime(
            RuntimeLimits::new(20, 4)
                .with_active_commands(2)
                .with_control_messages(8),
        )
        .with_handle_lifecycle(handle_lifecycle_profile())
        .with_handle_evaluation(handle_evaluation_profile())
        .with_remote_handshake(handshake)
        .with_remote_control(remote_control_profile());
        let requirements = profile.requirements();
        let prepared = PreparedChromiumAttach::new(profile, exact_limits(requirements))
            .expect("remote Handle composition should prepare");
        let (codec, config) = prepared
            .remote_handshake_parts()
            .expect("Handle handshake should be installed");
        let mut supervisor = prepared
            .new_supervisor(MemoryTransport::new([handle_remote_client_hello(
                handshake,
            )]))
            .expect("Handle supervisor should fit the production plan");
        let mut gate = AllowUnauthenticated;
        let accepted = supervisor
            .accept_handshake(&codec, &config, &mut gate)
            .await
            .expect("Handle capabilities should negotiate with their dependency");
        let runtime = Arc::new(
            prepared
                .new_direct_runtime((), ObjectId::new(1))
                .expect("Handle runtime should fit the production plan"),
        );
        let control = prepared
            .remote_control_outbound(
                Arc::clone(&runtime),
                Arc::clone(supervisor.transport()),
                &accepted,
            )
            .expect("ordered Handle lifecycle should fit")
            .expect("remote control was selected");

        // Act
        let lifecycle = prepared
            .remote_handle_lifecycle_handlers(Arc::new(()), &control, &accepted)
            .expect("negotiated lifecycle handler should fit");
        let evaluation = prepared
            .remote_handle_evaluation_handlers(
                Arc::new(()),
                Arc::new(()),
                Arc::new(()),
                CleanupQueue::new(1),
                &control,
                &accepted,
            )
            .expect("negotiated evaluation handler should fit");

        // Assert
        assert!(lifecycle.is_some());
        assert!(evaluation.is_some());
        assert_eq!(accepted.hello().enabled_capabilities().len(), 3);
        assert!(
            accepted
                .hello()
                .enabled_capabilities()
                .iter()
                .any(|capability| {
                    capability.id().as_str() == HANDLE_LIFECYCLE_CAPABILITY_ID.as_str()
                })
        );
        assert!(
            accepted
                .hello()
                .enabled_capabilities()
                .iter()
                .any(|capability| {
                    capability.id().as_str() == HANDLE_EVALUATION_CAPABILITY_ID.as_str()
                })
        );
    }

    #[tokio::test]
    async fn content_only_composition_captures_budgeted_bytes_through_the_page_router() {
        // Arrange
        let profile = base_profile().with_content(content_profile());
        let requirements = profile.requirements();
        let prepared = PreparedChromiumAttach::new(profile.clone(), exact_limits(requirements))
            .expect("content-only composition should prepare");
        let epoch = ConnectionEpoch::new(1);
        let mut topology = ProductionCdpTopology::new(
            ObjectId::new(1),
            epoch,
            profile.topology(),
            prepared.resources(),
        )
        .expect("production topology should build");
        topology
            .register_context(
                epoch,
                "context-a",
                ObjectId::new(2),
                CdpContextOwnership::External,
            )
            .expect("context should register");
        topology
            .attach_page(
                epoch,
                CdpPageTarget::new("target-a", "session-a", "context-a"),
                CdpPageObjectIds::new(ObjectId::new(3), ObjectId::new(4)),
            )
            .expect("Page should attach");
        let factory = Arc::new(RecordingSessionFactory::default());
        let services = CdpPageServices::new_with_production_resources(
            factory.clone(),
            &profile,
            prepared.resources(),
        )
        .expect("Page services should use the production plan");
        services
            .synchronize(&topology)
            .expect("Page route should synchronize");
        let runtime = prepared
            .new_direct_runtime(services, ObjectId::new(1))
            .expect("direct runtime should use the production plan");
        runtime
            .register_object(
                ObjectId::new(2),
                Some(ObjectId::new(1)),
                BROWSER_CONTEXT_OBJECT_KIND.tag,
            )
            .unwrap();
        runtime
            .register_object(
                ObjectId::new(3),
                Some(ObjectId::new(2)),
                PAGE_OBJECT_KIND.tag,
            )
            .unwrap();
        runtime
            .register_object(
                ObjectId::new(4),
                Some(ObjectId::new(3)),
                FRAME_OBJECT_KIND.tag,
            )
            .unwrap();
        let command = Command::<PageScreenshot>::new(
            CallId::new(18),
            ObjectId::new(3),
            CallMetadata::default(),
            ScreenshotOptions {
                format: Some(ScreenshotFormat::Png),
                ..ScreenshotOptions::default()
            },
        );

        // Act
        let result = runtime.call(command).await.unwrap().into_outcome().unwrap();
        let handlers = prepared
            .content_handlers(Arc::new(runtime))
            .expect("content protocol should fit")
            .expect("content handler should be installed");

        // Assert
        let content = WireCapabilityId::new("pwright.content", 128).unwrap();
        assert_eq!(prepared.capability_manifest().len(), 1);
        assert!(prepared.capability_manifest().support(&content).is_some());
        assert!(
            prepared
                .backend_manifest()
                .supports(CDP_PAGE_SCREENSHOT_FEATURE)
        );
        assert_eq!(result.as_bytes(), b"mock");
        assert_eq!(result.format(), ScreenshotFormat::Png);
        assert_eq!(
            factory.client("target-a").method_names(),
            ["Page.captureScreenshot"]
        );
        drop(handlers);
        drop(result);
    }

    #[test]
    fn locator_screenshot_profile_installs_no_locator_or_page_screenshot_surface() {
        // Arrange
        let profile = base_profile().with_locator_screenshot(locator_screenshot_profile());
        let requirements = profile.requirements();

        // Act
        let prepared = PreparedChromiumAttach::new(profile, exact_limits(requirements))
            .expect("Locator screenshot-only composition should prepare");
        let locator_screenshot =
            WireCapabilityId::new(LOCATOR_SCREENSHOT_CAPABILITY_ID.as_str(), 128)
                .expect("capability ID should fit");
        let locator = WireCapabilityId::new("pwright.locator", 128).unwrap();
        let content = WireCapabilityId::new("pwright.content", 128).unwrap();

        // Assert
        assert_eq!(prepared.capability_manifest().len(), 1);
        assert!(
            prepared
                .capability_manifest()
                .support(&locator_screenshot)
                .is_some()
        );
        assert_eq!(prepared.capability_manifest().support(&locator), None);
        assert_eq!(prepared.capability_manifest().support(&content), None);
        assert!(
            prepared
                .backend_manifest()
                .supports(CDP_LOCATOR_SCREENSHOT_FEATURE)
        );
        assert!(
            !prepared
                .backend_manifest()
                .supports(CDP_PAGE_SCREENSHOT_FEATURE)
        );
        assert!(
            prepared
                .locator_screenshot_handlers(Arc::new(()))
                .unwrap()
                .is_some()
        );
        assert!(prepared.locator_handlers(Arc::new(())).unwrap().is_none());
        assert!(prepared.content_handlers(Arc::new(())).unwrap().is_none());
    }

