    #[tokio::test]
    async fn unnegotiated_dom_content_installs_no_handler_and_reaches_no_cdp_backend() {
        // Arrange a server that offers DOM content and a client that requests
        // no optional capability.
        let handshake = content_remote_handshake_profile();
        let base = base_profile()
            .with_dom_content(dom_content_profile())
            .with_remote_handshake(handshake);
        let topology_events = ChromiumTopologyEventDriverProductionProfile::from_profiles(
            ResourceScope::extension(7, 8),
            base.connection(),
            base.topology(),
        )
        .expect("topology-event profile should validate");
        let profile = base
            .with_topology_events(topology_events)
            .with_utility_world(ChromiumUtilityWorldProfile::playwright_compatible());
        let prepared =
            PreparedChromiumAttach::new(profile.clone(), exact_limits(profile.requirements()))
                .expect("remote DOM-content composition should prepare");
        let (handshake_codec, handshake_config) = prepared
            .remote_handshake_parts()
            .expect("remote handshake should be installed");
        let transport = ProductionMemoryTransport::new(
            [empty_remote_client_hello(handshake)],
            prepared.resources(),
            handshake.transport_requirements(),
        );
        let mut supervisor = prepared
            .new_supervisor(transport)
            .expect("supervisor should use the production plan");
        let mut gate = AllowUnauthenticated;
        let accepted = supervisor
            .accept_handshake(&handshake_codec, &handshake_config, &mut gate)
            .await
            .expect("empty capability handshake should succeed");
        let factory = Arc::new(RecordingSessionFactory::default());
        let _available_backend =
            factory.create_session("session-a".to_owned(), "target-a".to_owned());
        let services = CdpPageServices::new_with_production_resources(
            factory.clone(),
            &profile,
            prepared.resources(),
        )
        .expect("offered backend services should fit their declared plan");
        let client = factory.client("target-a");

        // Act
        let handlers = prepared
            .remote_dom_content_handlers(Arc::new(services), &accepted)
            .expect("omitted capability should not fail application installation");

        // Assert: there is no command entrypoint capable of reaching CDP.
        assert!(accepted.hello().enabled_capabilities().is_empty());
        assert!(handlers.is_none());
        assert!(client.calls().is_empty());
    }

    #[tokio::test]
    async fn control_only_handshake_installs_no_application_path_or_resource_claim() {
        // Arrange a server that offers every current application capability
        // and a client that deliberately accepts none of them.
        let handshake = all_capabilities_handshake_profile();
        let profile = all_capabilities_profile(handshake);
        let prepared =
            PreparedChromiumAttach::new(profile.clone(), exact_limits(profile.requirements()))
                .expect("all-capability composition should prepare");
        let (handshake_codec, handshake_config) = prepared
            .remote_handshake_parts()
            .expect("remote handshake should be installed");
        let transport = ProductionMemoryTransport::new(
            [control_only_remote_client_hello(handshake)],
            prepared.resources(),
            handshake.transport_requirements(),
        );
        let mut supervisor = prepared
            .new_supervisor(transport)
            .expect("supervisor should use the production plan");
        let mut gate = AllowUnauthenticated;
        let accepted = supervisor
            .accept_handshake(&handshake_codec, &handshake_config, &mut gate)
            .await
            .expect("empty capability handshake should succeed");
        let runtime = Arc::new(DirectDispatcher::new(
            (),
            RuntimeLimits::new(8, 1).with_control_messages(8),
        ));
        let control = prepared
            .remote_control_outbound(runtime, Arc::clone(supervisor.transport()), &accepted)
            .expect("negotiated control writer should fit the production plan")
            .expect("control protocol should be selected");
        let before = prepared
            .resources()
            .metrics()
            .expect("production metrics should be available");

        // Act: ask every application installer for the tree it would expose on
        // this exact accepted connection.
        let absent = [
            prepared
                .remote_context_creation_handlers(Arc::new(()), &control, &accepted)
                .expect("omitted context creation should not fail")
                .is_none(),
            prepared
                .remote_context_lifecycle_handlers(Arc::new(()), &control, &accepted)
                .expect("omitted context lifecycle should not fail")
                .is_none(),
            prepared
                .remote_page_creation_handlers(Arc::new(()), &control, &accepted)
                .expect("omitted page creation should not fail")
                .is_none(),
            prepared
                .remote_page_lifecycle_handlers(Arc::new(()), Arc::new(()), &control, &accepted)
                .expect("omitted page lifecycle should not fail")
                .is_none(),
            prepared
                .remote_handle_lifecycle_handlers(Arc::new(()), &control, &accepted)
                .expect("omitted Handle lifecycle should not fail")
                .is_none(),
            prepared
                .remote_handle_evaluation_handlers(
                    Arc::new(()),
                    Arc::new(()),
                    Arc::new(()),
                    CleanupQueue::new(1),
                    &control,
                    &accepted,
                )
                .expect("omitted Handle evaluation should not fail")
                .is_none(),
            prepared
                .remote_content_handlers(Arc::new(()), &accepted)
                .expect("omitted content should not fail")
                .is_none(),
            prepared
                .remote_dom_content_handlers(Arc::new(()), &accepted)
                .expect("omitted DOM content should not fail")
                .is_none(),
            prepared
                .remote_evaluation_handlers(Arc::new(()), &accepted)
                .expect("omitted evaluation should not fail")
                .is_none(),
            prepared
                .remote_navigation_handlers(Arc::new(()), &accepted)
                .expect("omitted navigation should not fail")
                .is_none(),
            prepared
                .remote_selected_locator_handlers(Arc::new(()), &accepted)
                .expect("omitted locator should not fail")
                .is_none(),
            prepared
                .remote_locator_screenshot_handlers(Arc::new(()), &accepted)
                .expect("omitted Locator screenshot should not fail")
                .is_none(),
            prepared
                .remote_event_parts::<PageLoad, _, _, _>(
                    PageEventsCodec,
                    Arc::clone(supervisor.transport()),
                    &accepted,
                    OverflowPolicy::RejectNewest,
                    retained_page_load_bytes,
                )
                .expect("omitted page-events channel should not fail")
                .is_none(),
        ];
        let after = prepared
            .resources()
            .metrics()
            .expect("production metrics should remain available");

        // Assert
        assert_eq!(accepted.hello().enabled_capabilities().len(), 1);
        assert_eq!(
            accepted.hello().enabled_capabilities()[0].id().as_str(),
            CONTROL_PROTOCOL_ID
        );
        assert!(absent.into_iter().all(|is_absent| is_absent));
        assert_eq!(after, before);
    }

    #[test]
    fn attach_factory_prepares_distinct_connection_resource_ledgers() {
        // Arrange
        let profile = base_profile().with_navigation(navigation_profile());
        let limits = exact_limits(profile.requirements());
        let factory = ChromiumAttachFactory::new(profile.clone(), limits, ObjectId::new(1))
            .expect("valid reusable attachment recipe should compile");

        // Act
        let first = factory
            .prepare()
            .expect("first connection preparation should succeed");
        let second = factory
            .prepare()
            .expect("second connection preparation should succeed");

        // Assert
        let first_ledger = first
            .resources()
            .claim(profile.requirements())
            .expect("first preparation should expose its declared plan");
        let second_ledger = second
            .resources()
            .claim(profile.requirements())
            .expect("second preparation should expose its declared plan");
        assert!(!first_ledger.shares_budget_with(&second_ledger));
        assert_eq!(factory.browser_object_id(), ObjectId::new(1));
        assert_eq!(factory.initial_epoch(), ConnectionEpoch::new(1));
        assert_eq!(factory.limits(), limits);
        assert_eq!(factory.profile().capabilities(), profile.capabilities());
    }

