    #[tokio::test]
    #[ignore = "requires the dedicated Chrome CDP process and PWRIGHT_CDP_WS_URL"]
    async fn live_navigation_recipe_negotiates_runs_and_shuts_down_one_connection() {
        // Arrange
        let endpoint = CdpWebSocketEndpoint::parse(
            std::env::var("PWRIGHT_CDP_WS_URL")
                .expect("PWRIGHT_CDP_WS_URL must identify the dedicated Chrome endpoint"),
        )
        .expect("dedicated Chrome endpoint should parse");
        let handshake = remote_handshake_profile();
        let navigation = navigation_profile();
        let navigation_protocol = navigation.unbudgeted_protocol();
        let base = base_profile();
        let profile = ChromiumAttachProductionProfile::new(
            base.connection().clone(),
            base.topology(),
            base.page_routes(),
            base.runtime(),
            pwright_server_wire::ServerSupervisorLimits::new(2)
                .expect("supervisor limits should validate")
                .with_eof_policy(ServerEofPolicy::DrainActive),
        )
        .with_navigation(navigation)
        .with_remote_handshake(handshake);
        let limits = exact_limits(profile.requirements());
        let factory = ChromiumAttachFactory::new(profile, limits, ObjectId::new(1))
            .expect("remote attachment factory should validate");
        let hello = navigation_remote_client_hello(handshake);
        let seed = factory
            .attach_remote(endpoint, |resources: &ProductionResourceLedger| {
                Ok::<_, Infallible>(ProductionMemoryTransport::new(
                    [hello],
                    resources,
                    handshake.transport_requirements(),
                ))
            })
            .await
            .expect("fresh native and remote transport should stage together");
        let browser = CdpSession::browser(Arc::clone(seed.composition().connection()));
        let browser_context_id = browser
            .target_create_browser_context(None, None)
            .await
            .expect("temporary browser context should open");
        let target_id = browser
            .target_create_in_context("about:blank", &browser_context_id)
            .await
            .expect("temporary Page target should open");
        let session_id = browser
            .target_attach(&target_id)
            .await
            .expect("temporary Page target should attach");
        let epoch = seed
            .composition()
            .topology()
            .expect("topology should be available")
            .topology()
            .epoch();
        seed.composition()
            .with_topology_mut(|topology| {
                topology
                    .register_context(
                        epoch,
                        &browser_context_id,
                        ObjectId::new(2),
                        CdpContextOwnership::Owned,
                    )
                    .expect("temporary context should register");
                topology
                    .attach_page(
                        epoch,
                        CdpPageTarget::new(&target_id, session_id, &browser_context_id),
                        CdpPageObjectIds::new(ObjectId::new(3), ObjectId::new(4)),
                    )
                    .expect("temporary Page should register");
            })
            .expect("topology should remain available");
        let connection = seed
            .install_runtime(ChromiumNavigationRuntimeInstaller)
            .expect("navigation runtime should install");
        connection
            .runtime()
            .register_object(
                ObjectId::new(2),
                Some(ObjectId::new(1)),
                BROWSER_CONTEXT_OBJECT_KIND.tag,
            )
            .expect("temporary context should enter the runtime graph");
        connection
            .runtime()
            .register_object(
                ObjectId::new(3),
                Some(ObjectId::new(2)),
                PAGE_OBJECT_KIND.tag,
            )
            .expect("temporary Page should enter the runtime graph");
        let command = Command::<BeginNavigation>::new(
            CallId::new(71),
            ObjectId::new(3),
            CallMetadata::default(),
            BeginNavigationParams::new("data:text/html,<title>pwright-navigation-recipe</title>"),
        );
        let transport = Arc::clone(connection.supervisor().transport());
        transport.push_incoming(
            navigation_protocol
                .encode(&command)
                .expect("navigation command should encode"),
        );
        let shutdowns = transport.shutdown_counter();
        let mut gate = AllowUnauthenticated;
        let accepted = connection
            .accept_handshake(&mut gate)
            .await
            .expect("navigation handshake should be accepted");
        assert_eq!(accepted.accepted().hello().enabled_capabilities().len(), 1);
        let mut application = accepted
            .install_application(ChromiumNavigationApplicationInstaller)
            .expect("navigation-only application should install");

        // Act
        let reason = application
            .run(|_| Ok::<_, Infallible>(()))
            .await
            .expect("navigation command followed by EOF should complete");

        // Assert
        let result_frame = transport
            .sent_frames()
            .into_iter()
            .find(|frame| {
                frame.route()
                    == FrameRoute::Result {
                        call_id: CallId::new(71),
                    }
            })
            .expect("server should return the navigation result");
        let result: pwright_core::CommandResult<BeginNavigation> = navigation_protocol
            .decode(result_frame)
            .expect("navigation result should decode");
        assert!(result.outcome().is_ok());
        assert_eq!(reason, ServerSupervisorCloseReason::EndOfStream);
        assert_eq!(shutdowns.load(Ordering::SeqCst), 1);
        assert!(!application.composition().connection().is_closed());
        browser
            .target_dispose_browser_context(&browser_context_id)
            .await
            .expect("temporary browser context should close");
    }

