    #[tokio::test]
    #[ignore = "requires the dedicated Chrome CDP process and PWRIGHT_CDP_WS_URL"]
    async fn live_all_capabilities_recipe_accepts_locator_v2_and_preserves_chrome() {
        // Arrange
        let endpoint = CdpWebSocketEndpoint::parse(
            std::env::var("PWRIGHT_CDP_WS_URL")
                .expect("PWRIGHT_CDP_WS_URL must identify the dedicated Chrome endpoint"),
        )
        .expect("dedicated Chrome endpoint should parse");
        let handshake = all_capabilities_handshake_profile();
        let profile = all_capabilities_profile(handshake);
        let locator = profile
            .locator()
            .expect("all-capability profile should select locator");
        let profile = profile.with_locator(
            LocatorInstallationProfile::new(locator.backend(), locator.codec(), locator.wire())
                .with_v2_track(),
        );
        let limits = exact_limits(profile.requirements());
        let factory = ChromiumAttachFactory::new(profile, limits, ObjectId::new(1))
            .expect("all-capability attachment factory should validate");
        let reattach_factory = factory.clone();
        let hello = all_capabilities_remote_client_hello(handshake, ProtocolVersion::new(2, 5));
        let application = factory
            .attach_remote(endpoint.clone(), |resources: &ProductionResourceLedger| {
                Ok::<_, Infallible>(ProductionMemoryTransport::new(
                    [hello],
                    resources,
                    handshake.transport_requirements(),
                ))
            })
            .await
            .expect("all-capability remote connection should stage")
            .install_runtime(ChromiumAllCapabilitiesRuntimeInstaller::new(8))
            .expect("all-capability controlled runtime should install");
        let mut gate = AllowUnauthenticated;
        let accepted = application
            .accept_handshake(&mut gate)
            .await
            .expect("all-capability handshake should be accepted");

        // Act
        let application = accepted
            .install_application(ChromiumAllCapabilitiesApplicationInstaller::new(Arc::new(
                ImmediatePageClosePoll,
            )))
            .expect("all selected plugins should assemble without degradation");

        // Assert
        fn assert_all_capabilities_type(
            _application: &ChromiumAllCapabilitiesApplication<ProductionMemoryTransport, ()>,
        ) {
        }
        assert_all_capabilities_type(&application);
        assert_eq!(
            application.accepted().hello().enabled_capabilities().len(),
            15
        );
        assert_eq!(
            application.runtime().as_ref().inner().live_object_count(),
            Ok(1)
        );
        assert_eq!(
            application
                .controls()
                .inner()
                .receiver()
                .subscription_metrics()
                .active(),
            0
        );
        assert_eq!(
            application
                .composition()
                .connection()
                .reclaiming_event_metrics()
                .expect("all-capability recipe should use reclaiming CDP events")
                .subscribers,
            3,
            "topology, network, and PageLoad retain the three steady cursors"
        );
        let network_registry = application.state().clone();
        assert_eq!(
            network_registry
                .metrics()
                .expect("installed network registry should be readable")
                .registered_page_lanes(),
            0
        );
        drop(application);
        assert_eq!(
            network_registry
                .metrics()
                .expect("dropped network registry should remain inspectable")
                .registered_page_lanes(),
            0
        );
        let reattached = reattach_factory
            .attach(endpoint)
            .await
            .expect("all-capability connection drop must not terminate external Chrome");
        assert!(!reattached.connection().is_closed());
    }

    #[tokio::test]
    #[ignore = "requires the dedicated Chrome CDP process and PWRIGHT_CDP_WS_URL"]
    async fn live_all_capabilities_recipe_reclaims_concurrent_navigation_and_locator_cursors() {
        // Arrange a negotiated all-capability connection with the production
        // single-cursor network driver and the Locator 2.x wire contract.
        let endpoint = CdpWebSocketEndpoint::parse(
            std::env::var("PWRIGHT_CDP_WS_URL")
                .expect("PWRIGHT_CDP_WS_URL must identify the dedicated Chrome endpoint"),
        )
        .expect("dedicated Chrome endpoint should parse");
        let handshake = all_capabilities_handshake_profile();
        let profile = all_capabilities_profile(handshake);
        let navigation = profile
            .navigation()
            .expect("all-capability profile should select navigation");
        let locator = profile
            .locator()
            .expect("all-capability profile should select locator");
        let profile = profile.with_locator(
            LocatorInstallationProfile::new(locator.backend(), locator.codec(), locator.wire())
                .with_v2_track(),
        );
        assert_eq!(profile.required_reclaiming_event_subscribers(), 10);
        let limits = exact_limits(profile.requirements());
        let factory = ChromiumAttachFactory::new(profile, limits, ObjectId::new(1))
            .expect("all-capability attachment factory should validate");
        let client_endpoint = Arc::new(Mutex::new(None::<MemoryFrameTransport>));
        let client_endpoint_slot = Arc::clone(&client_endpoint);
        let transport_requirements = handshake.transport_requirements();
        let connection = factory
            .attach_remote(endpoint, move |resources: &ProductionResourceLedger| {
                let (client, server) = MemoryFrameTransport::pair(128);
                *client_endpoint_slot
                    .lock()
                    .expect("client endpoint slot should be available") = Some(client);
                Ok::<_, Infallible>(ProductionPairedMemoryTransport::new(
                    server,
                    resources,
                    transport_requirements,
                ))
            })
            .await
            .expect("all-capability remote connection should stage")
            .install_runtime(ChromiumAllCapabilitiesRuntimeInstaller::new(8))
            .expect("all-capability controlled runtime should install");
        let client_transport = client_endpoint
            .lock()
            .expect("client endpoint slot should be available")
            .take()
            .expect("transport builder should publish the client endpoint");
        let client_hello = all_capabilities_client_hello(handshake, ProtocolVersion::new(2, 5));
        let client_handshake_protocol = WireProtocol::new_directional(
            HandshakeCodec::new(handshake.negotiation_limits()),
            handshake.versions(),
            ProtocolVersion::new(1, 0),
            handshake.server_receive_limits(),
            client_hello.receive_limits(),
        )
        .expect("client handshake protocol should validate");
        let mut gate = AllowUnauthenticated;
        let (accepted, negotiated) = tokio::time::timeout(Duration::from_secs(10), async {
            tokio::join!(
                connection.accept_handshake(&mut gate),
                EncodedClientHandshake::new(client_transport)
                    .establish(client_handshake_protocol, client_hello),
            )
        })
        .await
        .expect("both handshake peers should make progress");
        let accepted = accepted.expect("server should accept every capability");
        let negotiated = negotiated.expect("client should validate the server hello");
        let mut application = accepted
            .install_application(ChromiumAllCapabilitiesApplicationInstaller::new(Arc::new(
                ImmediatePageClosePoll,
            )))
            .expect("all selected plugins should assemble");
        let cdp_connection = Arc::clone(application.composition().connection());
        let page_services = application
            .runtime()
            .as_ref()
            .inner()
            .as_ref()
            .service()
            .clone();
        let browser = CdpSession::browser(Arc::clone(&cdp_connection));
        let mut temporary_targets = Vec::new();
        for _ in 0..4 {
            temporary_targets.push(
                browser
                    .target_create("about:blank")
                    .await
                    .expect("temporary Page should open"),
            );
        }

        let server_hello = negotiated.hello();
        let locator_version = server_hello
            .enabled_capability_version(
                &WireCapabilityId::new(
                    pwright_cap_locator::LOCATOR_CAPABILITY_ID.as_str(),
                    handshake.negotiation_limits().capability_id_bytes,
                )
                .expect("Locator capability ID should fit negotiation limits"),
            )
            .expect("Locator should be negotiated");
        assert_eq!(locator_version, ProtocolVersion::new(2, 5));
        let selected_version = server_hello.selected_version();
        let server_receive_limits = server_hello.server_receive_limits();
        let client_receive_limits = server_hello.client_receive_limits();
        let control_codec = NegotiatedControlCodec::for_client(server_hello)
            .expect("the client should select the negotiated control version");
        let lifecycle_protocol = WireProtocol::new_exact_directional(
            control_codec,
            selected_version,
            server_receive_limits,
            client_receive_limits,
        );
        let client_codec = NavigationLocatorV2ClientCodec::new(
            NavigationCodec::new(navigation.codec()),
            LocatorV2Codec::new(locator.codec()).with_capability_version(locator_version),
        );
        let (channel, mut driver) = negotiated
            .into_channel_with_control(client_codec, control_codec, 4)
            .expect("navigation, Locator, and control should share negotiated wire limits");
        let command_channel = channel.clone();
        let client = Client::new(channel, AtomicCallIdSource::new(100));
        let mut lifecycle = ClientLifecycleHandler::new(client, lifecycle_protocol);
        let progress = Arc::new(AtomicUsize::new(0));
        let completed_commands = Arc::new(AtomicUsize::new(0));
        let observed_page_loads = Arc::new(AtomicUsize::new(0));
        let client_progress = Arc::clone(&progress);
        let client_completed_commands = Arc::clone(&completed_commands);
        let client_observed_page_loads = Arc::clone(&observed_page_loads);

        // Act: discover four Pages, then keep two Locator click barriers alive
        // with deliberate pointer delays while two Goto waits overlap them.
        let client_run = async {
            let mut page_ids = Vec::new();
            while page_ids.len() < 4 {
                match driver
                    .drive_once_with(&mut lifecycle)
                    .await
                    .expect("client lifecycle driver should remain healthy during discovery")
                {
                    RoutedDriverEvent::Handled(ClientLifecycleEvent::Created(initializer))
                        if initializer.kind() == PageKind::OBJECT_KIND =>
                    {
                        page_ids.push(initializer.id());
                    }
                    RoutedDriverEvent::Handled(_) | RoutedDriverEvent::Unhandled(_) => {}
                    RoutedDriverEvent::Closed(reason) => {
                        panic!("remote connection closed during Page discovery: {reason:?}")
                    }
                    RoutedDriverEvent::Delivered(call) => panic!(
                        "unexpected delivered call {} during Page discovery",
                        call.call_id()
                    ),
                    RoutedDriverEvent::IgnoredAbandoned(call_id) => {
                        panic!("unexpected abandoned call {call_id} during Page discovery")
                    }
                }
            }
            client_progress.store(1, Ordering::SeqCst);
            let initial_locator_contexts = loop {
                let contexts = page_ids
                    .iter()
                    .map(|page| {
                        page_services
                            .locator_route(*page)
                            .ok()
                            .flatten()
                            .and_then(|service| service.unique_context_id().map(ToOwned::to_owned))
                    })
                    .collect::<Vec<_>>();
                if contexts.iter().all(Option::is_some) {
                    break contexts
                        .into_iter()
                        .map(|context| context.expect("every context was checked above"))
                        .collect::<Vec<_>>();
                }
                tokio::time::sleep(Duration::from_millis(10)).await;
            };

            let page_event_protocol = WireProtocol::new_exact_directional(
                PageEventsCodec,
                selected_version,
                server_receive_limits,
                client_receive_limits,
            );
            let page_loads = pwright_client_events::TypedEventHandler::<PageLoad, _>::new(
                page_event_protocol,
                16,
                OverflowPolicy::RejectNewest,
            );
            let mut handlers = lifecycle.or_else(page_loads);
            let mut page_load_count = 0_usize;

            let button_document = "data:text/html,%3Cbutton%20id%3D%22hold%22%20style%3D%22width%3A120px%3Bheight%3A80px%22%3Ehold%3C%2Fbutton%3E";
            for (offset, page) in page_ids.iter().copied().enumerate() {
                let setup = command_channel.call(Command::<Goto>::new(
                    CallId::new(1 + u64::try_from(offset).expect("setup offset should fit u64")),
                    page,
                    CallMetadata::default(),
                    GotoParams::new(button_document),
                ));
                tokio::pin!(setup);
                let result = loop {
                    tokio::select! {
                        result = &mut setup => break result,
                        incoming = driver.drive_once_with(&mut handlers) => {
                            match incoming.expect("client driver should remain healthy during fixture navigation") {
                                RoutedDriverEvent::Handled(Either::Right(_)) => {
                                    page_load_count = page_load_count.saturating_add(1);
                                    client_observed_page_loads.store(page_load_count, Ordering::SeqCst);
                                }
                                RoutedDriverEvent::Closed(reason) => {
                                    return Err(format!(
                                        "remote connection closed during fixture navigation: {reason:?}"
                                    ));
                                }
                                RoutedDriverEvent::Handled(Either::Left(_))
                                | RoutedDriverEvent::Delivered(_)
                                | RoutedDriverEvent::IgnoredAbandoned(_)
                                | RoutedDriverEvent::Unhandled(_) => {}
                            }
                        }
                    }
                };
                result
                    .expect("fixture navigation transport should remain infallible")
                    .into_outcome()
                    .expect("fixture Page should load its button document");
            }
            client_progress.store(5, Ordering::SeqCst);
            loop {
                let routes_advanced =
                    page_ids
                        .iter()
                        .zip(&initial_locator_contexts)
                        .all(|(page, initial)| {
                            page_services
                                .locator_route(*page)
                                .ok()
                                .flatten()
                                .and_then(|service| {
                                    service.unique_context_id().map(ToOwned::to_owned)
                                })
                                .is_some_and(|current| current != *initial)
                        });
                if routes_advanced {
                    break;
                }
                tokio::time::sleep(Duration::from_millis(10)).await;
            }

            // Make renderer-world readiness observable before measuring
            // transient cursor overlap. Trial clicks run the full Locator
            // actionability path but neither dispatch input nor install a
            // navigation barrier.
            for (offset, page) in page_ids[2..].iter().copied().enumerate() {
                client_progress.store(10 + offset, Ordering::SeqCst);
                let probe = command_channel.call(Command::<locator_v2::Click>::new(
                    CallId::new(5 + u64::try_from(offset).expect("probe offset should fit u64")),
                    page,
                    CallMetadata::default(),
                    ClickParamsV2::new(
                        Selector::css("body").expect("test selector should validate"),
                        ClickOptionsV2::new().with_trial(true),
                    ),
                ));
                tokio::pin!(probe);
                let result = loop {
                    tokio::select! {
                        result = &mut probe => break result,
                        incoming = driver.drive_once_with(&mut handlers) => {
                            match incoming.expect("client driver should remain healthy during Locator readiness") {
                                RoutedDriverEvent::Handled(Either::Right(_)) => {
                                    page_load_count = page_load_count.saturating_add(1);
                                    client_observed_page_loads.store(page_load_count, Ordering::SeqCst);
                                }
                                RoutedDriverEvent::Closed(reason) => {
                                    return Err(format!(
                                        "remote connection closed during Locator readiness: {reason:?}"
                                    ));
                                }
                                RoutedDriverEvent::Handled(Either::Left(_))
                                | RoutedDriverEvent::Delivered(_)
                                | RoutedDriverEvent::IgnoredAbandoned(_)
                                | RoutedDriverEvent::Unhandled(_) => {}
                            }
                        }
                    }
                };
                result
                    .expect("Locator readiness transport should remain infallible")
                    .into_outcome()
                    .expect("trial click should prove Locator readiness");
            }

            let click_options = ClickOptionsV2::new().with_delay(Duration::from_secs(3));
            let click_options_one = click_options.clone();
            let click_options_two = click_options;
            let click_one = async {
                let result = command_channel
                    .call(Command::<locator_v2::Click>::new(
                        CallId::new(9),
                        page_ids[2],
                        CallMetadata::default(),
                        ClickParamsV2::new(
                            Selector::css("body").expect("test selector should validate"),
                            click_options_one,
                        ),
                    ))
                    .await;
                client_completed_commands.fetch_or(4, Ordering::SeqCst);
                result
            };
            let click_two = async {
                let result = command_channel
                    .call(Command::<locator_v2::Click>::new(
                        CallId::new(10),
                        page_ids[3],
                        CallMetadata::default(),
                        ClickParamsV2::new(
                            Selector::css("body").expect("test selector should validate"),
                            click_options_two,
                        ),
                    ))
                    .await;
                client_completed_commands.fetch_or(8, Ordering::SeqCst);
                result
            };
            tokio::pin!(click_one, click_two);
            client_progress.store(2, Ordering::SeqCst);

            let slow_document = "data:text/html,<script>const end=Date.now()+2000;while(Date.now()<end){}</script><main>loaded</main>";
            let goto_one = async {
                let result = command_channel
                    .call(Command::<Goto>::new(
                        CallId::new(7),
                        page_ids[0],
                        CallMetadata::default(),
                        GotoParams::new(slow_document),
                    ))
                    .await;
                client_completed_commands.fetch_or(1, Ordering::SeqCst);
                result
            };
            let goto_two = async {
                let result = command_channel
                    .call(Command::<Goto>::new(
                        CallId::new(8),
                        page_ids[1],
                        CallMetadata::default(),
                        GotoParams::new(slow_document),
                    ))
                    .await;
                client_completed_commands.fetch_or(2, Ordering::SeqCst);
                result
            };
            let commands =
                async { tokio::join!(goto_one, goto_two, &mut click_one, &mut click_two) };
            tokio::pin!(commands);
            let results = loop {
                tokio::select! {
                    results = &mut commands => break results,
                    incoming = driver.drive_once_with(&mut handlers) => {
                        match incoming.expect("client driver should remain healthy during concurrent commands") {
                            RoutedDriverEvent::Handled(Either::Right(_)) => {
                                page_load_count = page_load_count.saturating_add(1);
                                client_observed_page_loads.store(page_load_count, Ordering::SeqCst);
                            }
                            RoutedDriverEvent::Closed(reason) => {
                                return Err(format!(
                                    "remote connection closed during concurrent commands: {reason:?}"
                                ));
                            }
                            RoutedDriverEvent::Handled(Either::Left(_))
                            | RoutedDriverEvent::Delivered(_)
                            | RoutedDriverEvent::IgnoredAbandoned(_)
                            | RoutedDriverEvent::Unhandled(_) => {}
                        }
                    }
                }
            };
            client_progress.store(3, Ordering::SeqCst);
            results
                .0
                .expect("Goto transport should remain infallible")
                .into_outcome()
                .expect("first Goto should succeed");
            results
                .1
                .expect("Goto transport should remain infallible")
                .into_outcome()
                .expect("second Goto should succeed");
            results
                .2
                .expect("Locator transport should remain infallible")
                .into_outcome()
                .expect("first click should succeed");
            results
                .3
                .expect("Locator transport should remain infallible")
                .into_outcome()
                .expect("second click should succeed");

            while page_load_count < 2
                || cdp_connection
                    .reclaiming_event_metrics()
                    .expect("reclaiming fanout metrics should remain available")
                    .queued_events
                    != 0
            {
                match driver
                    .drive_once_with(&mut handlers)
                    .await
                    .expect("client driver should drain PageLoad events")
                {
                    RoutedDriverEvent::Handled(Either::Right(_)) => {
                        page_load_count = page_load_count.saturating_add(1);
                        client_observed_page_loads.store(page_load_count, Ordering::SeqCst);
                    }
                    RoutedDriverEvent::Closed(reason) => {
                        return Err(format!(
                            "remote connection closed while draining events: {reason:?}"
                        ));
                    }
                    RoutedDriverEvent::Handled(Either::Left(_))
                    | RoutedDriverEvent::Delivered(_)
                    | RoutedDriverEvent::IgnoredAbandoned(_)
                    | RoutedDriverEvent::Unhandled(_) => {}
                }
            }
            let after_commands = cdp_connection
                .reclaiming_event_metrics()
                .expect("reclaiming fanout metrics should remain available");
            client_progress.store(4, Ordering::SeqCst);
            let close = driver
                .graceful_close()
                .await
                .expect("client and server should complete the Close/CloseAck barrier");
            Ok::<_, String>((page_load_count, after_commands, close))
        };
        let server_run = application.run(|_| Ok::<_, Infallible>(()));
        let run = tokio::time::timeout(Duration::from_secs(30), async {
            tokio::join!(server_run, client_run)
        })
        .await;
        let (server_result, client_result) = match run {
            Ok(result) => result,
            Err(error) => {
                for target in &temporary_targets {
                    browser
                        .target_close(target)
                        .await
                        .expect("timed-out temporary target should close");
                }
                panic!(
                    "concurrent navigation and Locator proof timed out at stage {}, completed mask {:#06b}, PageLoad events {}, fanout {:?}: {error}",
                    progress.load(Ordering::SeqCst),
                    completed_commands.load(Ordering::SeqCst),
                    observed_page_loads.load(Ordering::SeqCst),
                    cdp_connection.reclaiming_event_metrics(),
                );
            }
        };
        let (page_load_count, after_commands, close) = match client_result {
            Ok(result) => result,
            Err(error) => panic!("{error}; server outcome: {server_result:?}"),
        };

        // Assert: this recipe uses one shared network cursor. Command polling
        // guarantees at least 3 steady + 2 Goto + 1 click cursors overlap;
        // both click barriers may overlap as well. The configured bound of 10
        // additionally admits the alternative four-independent-network-lane
        // assembly.
        assert_eq!(
            server_result.expect("server application should close cleanly"),
            ServerSupervisorCloseReason::PeerGracefulClose
        );
        assert!(page_load_count >= 2);
        assert_eq!(after_commands.subscribers, 3);
        assert!((6..=7).contains(&after_commands.peak_subscribers));
        assert_eq!(after_commands.queued_events, 0);
        assert_eq!(after_commands.lagged_deliveries, 0);
        assert_eq!(close.woken_calls(), 0);
        assert!(!cdp_connection.is_closed());
        for target in temporary_targets {
            browser
                .target_close(&target)
                .await
                .expect("temporary target should close while external Chrome remains live");
        }
        browser
            .target_get_targets()
            .await
            .expect("externally owned Chrome should remain reachable");
    }

    #[tokio::test]
    #[ignore = "requires the dedicated Chrome CDP process and PWRIGHT_CDP_WS_URL"]
    async fn live_negotiated_handle_argument_round_trips_through_typed_client() {
        // Arrange a real bidirectional remote connection around external Chrome.
        let endpoint = CdpWebSocketEndpoint::parse(
            std::env::var("PWRIGHT_CDP_WS_URL")
                .expect("PWRIGHT_CDP_WS_URL must identify the dedicated Chrome endpoint"),
        )
        .expect("dedicated Chrome endpoint should parse");
        let handshake = all_capabilities_handshake_profile();
        let profile = all_capabilities_profile_with_topology(
            handshake,
            CdpTopologyLimits::new(48, 8, 24, 32, 48, 128),
        );
        let handle_lifecycle = profile
            .handle_lifecycle()
            .expect("all-capability profile should select Handle lifecycle");
        let profile = profile.with_handle_lifecycle(HandleLifecycleInstallationProfile::new(
            ChromiumHandleRouteProductionProfile::new(
                ResourceScope::extension(7, 10),
                12,
                128,
                256,
            ),
            handle_lifecycle.codec(),
            handle_lifecycle.wire(),
        ));
        let handle_profile = profile
            .handle_evaluation()
            .expect("all-capability profile should select Handle evaluation");
        let profile =
            profile.with_handle_element_adoption(CdpElementHandleAdoptionProductionProfile::new(
                ResourceScope::extension(7, 31),
                CdpHandleEvaluationLimits::new(
                    handle_profile.backend().limits(),
                    handle_profile.native_id_bytes(),
                    handle_profile.preview_bytes(),
                ),
                1,
                4,
            ));
        let limits = exact_limits(profile.requirements());
        let factory = ChromiumAttachFactory::new(profile, limits, ObjectId::new(1))
            .expect("all-capability attachment factory should validate");
        let client_endpoint = Arc::new(Mutex::new(None::<MemoryFrameTransport>));
        let client_endpoint_slot = Arc::clone(&client_endpoint);
        let transport_requirements = handshake.transport_requirements();
        let connection = factory
            .attach_remote(endpoint, move |resources: &ProductionResourceLedger| {
                let (client, server) = MemoryFrameTransport::pair(128);
                *client_endpoint_slot
                    .lock()
                    .expect("client endpoint slot should be available") = Some(client);
                Ok::<_, Infallible>(ProductionPairedMemoryTransport::new(
                    server,
                    resources,
                    transport_requirements,
                ))
            })
            .await
            .expect("all-capability remote connection should stage")
            .install_runtime(ChromiumAllCapabilitiesRuntimeInstaller::new(8))
            .expect("all-capability controlled runtime should install");
        let client_transport = client_endpoint
            .lock()
            .expect("client endpoint slot should be available")
            .take()
            .expect("transport builder should publish the client endpoint");
        let client_hello = all_capabilities_client_hello(handshake, ProtocolVersion::new(1, 0));
        let client_handshake_protocol = WireProtocol::new_directional(
            HandshakeCodec::new(handshake.negotiation_limits()),
            handshake.versions(),
            ProtocolVersion::new(1, 0),
            handshake.server_receive_limits(),
            client_hello.receive_limits(),
        )
        .expect("client handshake protocol should validate");
        let mut gate = AllowUnauthenticated;
        let (accepted, negotiated) = tokio::time::timeout(Duration::from_secs(10), async {
            tokio::join!(
                connection.accept_handshake(&mut gate),
                EncodedClientHandshake::new(client_transport)
                    .establish(client_handshake_protocol, client_hello),
            )
        })
        .await
        .expect("both handshake peers should make progress");
        let accepted = accepted.expect("server should accept all capabilities");
        let negotiated = negotiated.expect("client should validate the server hello");
        let mut application = accepted
            .install_application(ChromiumAllCapabilitiesApplicationInstaller::new(Arc::new(
                ImmediatePageClosePoll,
            )))
            .expect("all selected plugins should assemble");
        let browser = CdpSession::browser(Arc::clone(application.composition().connection()));
        let temporary_target = browser
            .target_create("data:text/html,<main>negotiated-handle-argument</main>")
            .await
            .expect("temporary Page should open");

        let server_hello = negotiated.hello();
        let handle_version = server_hello
            .enabled_capabilities()
            .iter()
            .find(|capability| capability.id().as_str() == HANDLE_EVALUATION_CAPABILITY_ID.as_str())
            .map(|capability| capability.version())
            .expect("Handle evaluation should be negotiated");
        assert_eq!(handle_version, ProtocolVersion::new(1, 2));
        let control_codec = NegotiatedControlCodec::for_client(server_hello)
            .expect("the client should select the negotiated control version");
        let handle_codec = HandleEvaluationCodec::new(handle_profile.codec())
            .with_capability_version(handle_version);
        let lifecycle_protocol = WireProtocol::new_exact_directional(
            control_codec,
            server_hello.selected_version(),
            server_hello.server_receive_limits(),
            server_hello.client_receive_limits(),
        );
        let (channel, mut driver) = negotiated
            .into_channel_with_control(handle_codec, control_codec, 2)
            .expect("Handle evaluation and control should share negotiated wire limits");
        let client = Client::new(channel, AtomicCallIdSource::new(1));
        let mut lifecycle = ClientLifecycleHandler::new(client, lifecycle_protocol);

        // Act: discover one Frame, create an ElementHandle, then pass that
        // portable Handle through the second encoded command.
        let client_run = async {
            let mut initializers = BTreeMap::new();
            let (browser_initializer, context_initializer, page_initializer, frame_initializer) = loop {
                match driver
                    .drive_once_with(&mut lifecycle)
                    .await
                    .expect("client lifecycle driver should remain healthy during discovery")
                {
                    RoutedDriverEvent::Handled(ClientLifecycleEvent::Created(initializer)) => {
                        initializers.insert(initializer.id(), initializer);
                    }
                    RoutedDriverEvent::Handled(_) | RoutedDriverEvent::Unhandled(_) => {}
                    RoutedDriverEvent::Closed(reason) => {
                        panic!("remote connection closed during discovery: {reason:?}")
                    }
                    RoutedDriverEvent::Delivered(call) => {
                        panic!(
                            "unexpected delivered call {} during discovery",
                            call.call_id()
                        )
                    }
                    RoutedDriverEvent::IgnoredAbandoned(call_id) => {
                        panic!("unexpected abandoned call {call_id} during discovery")
                    }
                }
                let Some(frame) = initializers
                    .values()
                    .find(|candidate| candidate.kind() == FrameKind::OBJECT_KIND)
                    .copied()
                else {
                    continue;
                };
                let Some(page) = frame
                    .parent()
                    .and_then(|parent| initializers.get(&parent))
                    .copied()
                else {
                    continue;
                };
                let Some(context) = page
                    .parent()
                    .and_then(|parent| initializers.get(&parent))
                    .copied()
                else {
                    continue;
                };
                let Some(browser) = context
                    .parent()
                    .and_then(|parent| initializers.get(&parent))
                    .copied()
                else {
                    continue;
                };
                break (browser, context, page, frame);
            };
            let remote_browser = lifecycle
                .client()
                .browser(browser_initializer)
                .expect("announced Browser should become a typed root");
            let context = remote_browser
                .context_from_announcement(context_initializer)
                .expect("announced BrowserContext should become a typed child");
            let page = context
                .page(page_initializer)
                .expect("announced Page should become a typed child");
            let frame = page
                .frame(frame_initializer)
                .expect("announced Frame should become a typed child");

            // Renderer-world publication is intentionally independent from
            // portable object discovery. Let that backend lane catch up before
            // retaining a Handle; the retry below still proves fallback-route
            // invalidation if the transition races this checkpoint.
            tokio::time::sleep(Duration::from_millis(100)).await;
            let mut attempts = 0;
            let (element, tag_name) = loop {
                attempts += 1;
                let first = frame.evaluate_handle(EvaluateHandleParams::expression(
                    "document.createElement('section')",
                ));
                tokio::pin!(first);
                let element = loop {
                    tokio::select! {
                        result = &mut first => break result.expect("ElementHandle creation should succeed"),
                        incoming = driver.drive_once_with(&mut lifecycle) => {
                            let event = incoming.expect("client driver should remain healthy during first evaluation");
                            if let RoutedDriverEvent::Closed(reason) = event {
                                panic!("remote connection closed during first evaluation: {reason:?}");
                            }
                        }
                    }
                };
                let second = frame.evaluate_handle(EvaluateHandleParams::function(
                    "node => node.tagName",
                    &element,
                ));
                tokio::pin!(second);
                let result = loop {
                    tokio::select! {
                        result = &mut second => break result,
                        incoming = driver.drive_once_with(&mut lifecycle) => {
                            let event = incoming.expect("client driver should remain healthy during Handle argument evaluation");
                            assert!(!matches!(event, RoutedDriverEvent::Closed(_)));
                        }
                    }
                };
                match result {
                    Ok(handle) => break (element, handle),
                    Err(error)
                        if attempts < 32
                            && (error.message().contains("exact CDP execution context")
                                || error.kind() == FailureKind::TargetClosed) =>
                    {
                        // Frame Create precedes renderer-world discovery. If
                        // this attempt used the fallback route, world
                        // publication invalidates its Handle; retry only after
                        // that bounded, observable transition.
                        tokio::time::sleep(Duration::from_millis(10)).await;
                    }
                    Err(error) => panic!(
                        "Handle-valued evaluation should succeed after world discovery: {error}"
                    ),
                }
            };
            macro_rules! await_handle_operation {
                ($future:expr, $message:literal) => {{
                    let future = $future;
                    tokio::pin!(future);
                    loop {
                        tokio::select! {
                            result = &mut future => break result.expect($message),
                            incoming = driver.drive_once_with(&mut lifecycle) => {
                                let event = incoming.expect("client driver should remain healthy during Handle-local operation");
                                assert!(!matches!(event, RoutedDriverEvent::Closed(_)));
                            }
                        }
                    }
                }};
            }
            let tag_name_value = await_handle_operation!(
                element.evaluate(
                    pwright_cap_handle_evaluation::HandleEvaluateParams::function_without_argument(
                        "target => target.tagName",
                    ),
                ),
                "Handle.evaluate should return the target tag name"
            );
            let tag_name_json = await_handle_operation!(
                tag_name.json_value(),
                "Handle.jsonValue should decode a retained string"
            );
            let mut object_attempts = 0_u8;
            let object = loop {
                object_attempts = object_attempts.saturating_add(1);
                let future = frame.evaluate_handle(EvaluateHandleParams::expression(
                    "({ answer: 42, child: document.createElement('button') })",
                ));
                tokio::pin!(future);
                let result = loop {
                    tokio::select! {
                        result = &mut future => break result,
                        incoming = driver.drive_once_with(&mut lifecycle) => {
                            let event = incoming.expect("client driver should remain healthy during object creation");
                            assert!(!matches!(event, RoutedDriverEvent::Closed(_)));
                        }
                    }
                };
                match result {
                    Ok(object) => break object,
                    Err(error)
                        if object_attempts < 32
                            && (error.kind() == FailureKind::TargetClosed
                                || error.message().contains("exact CDP execution context")) =>
                    {
                        tokio::time::sleep(Duration::from_millis(10)).await;
                    }
                    Err(error) => panic!("object Handle creation should succeed: {error}"),
                }
            };
            let answer = await_handle_operation!(
                object.get_property("answer"),
                "Handle.getProperty should retain the requested value"
            );
            let answer_value = await_handle_operation!(
                answer.json_value(),
                "property Handle should decode by value"
            );
            let child = await_handle_operation!(
                object.evaluate_handle(
                    pwright_cap_handle_evaluation::HandleEvaluateParams::function_without_argument(
                        "target => target.child",
                    ),
                ),
                "Handle.evaluateHandle should retain a target-relative result"
            );
            let properties = await_handle_operation!(
                object.get_properties(),
                "Handle.getProperties should materialize an atomic property batch"
            );
            let property_names = properties
                .iter()
                .map(|property| property.name.clone())
                .collect::<Vec<_>>();
            let property_kinds = properties
                .iter()
                .map(|property| property.value.is_element())
                .collect::<Vec<_>>();
            let close = driver
                .graceful_close()
                .await
                .expect("client and server should complete the Close/CloseAck barrier");
            (
                element,
                tag_name,
                tag_name_value,
                tag_name_json,
                answer_value,
                child,
                property_names,
                property_kinds,
                close,
            )
        };
        let server_run = application.run(|_| Ok::<_, Infallible>(()));
        tokio::pin!(server_run);
        tokio::pin!(client_run);
        let (server_result, client_result) = tokio::time::timeout(Duration::from_secs(20), async {
            tokio::select! {
                client_result = &mut client_run => (server_run.await, client_result),
                result = &mut server_run => {
                    if let Err(error) = &result {
                        panic!("server application exited before the typed client: {error:?}");
                    }
                    (result, client_run.await)
                }
            }
        })
        .await
        .expect("negotiated Handle argument round trip should not time out");
        let (
            element,
            tag_name,
            tag_name_value,
            tag_name_json,
            answer_value,
            child,
            property_names,
            property_kinds,
            close,
        ) = client_result;

        // Assert the typed result crossed the real wire and external Chrome survives.
        assert_eq!(
            server_result.expect("server application should close cleanly"),
            ServerSupervisorCloseReason::PeerGracefulClose
        );
        assert!(element.is_element());
        assert!(!tag_name.is_element());
        assert_ne!(element.id(), tag_name.id());
        assert_eq!(
            tag_name_value,
            EvaluationValue::String("SECTION".to_owned())
        );
        assert_eq!(tag_name_json, EvaluationValue::String("SECTION".to_owned()));
        assert_eq!(
            answer_value,
            EvaluationValue::Number(
                pwright_cap_evaluation::EvaluationNumber::new(42.0)
                    .expect("42 is a finite evaluation number")
            )
        );
        assert!(child.is_element());
        assert_eq!(property_names, ["answer", "child"]);
        assert_eq!(property_kinds, [false, true]);
        assert_eq!(close.woken_calls(), 0);
        browser
            .target_close(&temporary_target)
            .await
            .expect("temporary target should close while external Chrome remains live");
        browser
            .target_get_targets()
            .await
            .expect("externally owned Chrome should remain reachable");
    }

    #[tokio::test]
    #[ignore = "requires the dedicated Chrome CDP process and PWRIGHT_CDP_WS_URL"]
    async fn live_discovery_create_reaches_typed_client_page_before_navigation() {
        // Arrange a real bidirectional remote connection around external Chrome.
        let endpoint = CdpWebSocketEndpoint::parse(
            std::env::var("PWRIGHT_CDP_WS_URL")
                .expect("PWRIGHT_CDP_WS_URL must identify the dedicated Chrome endpoint"),
        )
        .expect("dedicated Chrome endpoint should parse");
        let handshake = remote_handshake_profile();
        let navigation = navigation_profile();
        let base = base_profile_with_runtime(
            RuntimeLimits::new(16, 4)
                .with_active_commands(2)
                .with_control_messages(16),
        )
        .with_navigation(navigation);
        let topology_events = ChromiumTopologyEventDriverProductionProfile::from_profiles(
            ResourceScope::extension(7, 6),
            base.connection(),
            base.topology(),
        )
        .expect("topology-event profile should validate");
        let discovery = ChromiumPageDiscoveryProductionProfile::from_profiles(
            base.connection(),
            base.topology(),
        );
        let profile = base
            .with_topology_events(topology_events)
            .with_page_discovery(discovery)
            .with_remote_handshake(handshake)
            .with_remote_control(remote_control_profile());
        let limits = exact_limits(profile.requirements());
        let factory = ChromiumAttachFactory::new(profile, limits, ObjectId::new(1))
            .expect("discovering navigation factory should validate");
        let client_endpoint = Arc::new(Mutex::new(None::<MemoryFrameTransport>));
        let client_endpoint_slot = Arc::clone(&client_endpoint);
        let transport_requirements = handshake.transport_requirements();
        let connection = factory
            .attach_remote(endpoint, move |resources: &ProductionResourceLedger| {
                let (client, server) = MemoryFrameTransport::pair(64);
                *client_endpoint_slot
                    .lock()
                    .expect("client endpoint slot should be available") = Some(client);
                Ok::<_, Infallible>(ProductionPairedMemoryTransport::new(
                    server,
                    resources,
                    transport_requirements,
                ))
            })
            .await
            .expect("fresh discovery connection should stage")
            .install_runtime(ChromiumDiscoveringNavigationRuntimeInstaller::new(2))
            .expect("control-aware navigation runtime should install");
        let client_transport = client_endpoint
            .lock()
            .expect("client endpoint slot should be available")
            .take()
            .expect("transport builder should publish the client endpoint");
        let client_hello = discovering_navigation_client_hello(handshake);
        let client_handshake_protocol = WireProtocol::new_directional(
            HandshakeCodec::new(handshake.negotiation_limits()),
            handshake.versions(),
            ProtocolVersion::new(1, 0),
            handshake.server_receive_limits(),
            client_hello.receive_limits(),
        )
        .expect("client handshake protocol should validate");
        let mut gate = AllowUnauthenticated;
        let (accepted, negotiated) = tokio::time::timeout(Duration::from_secs(10), async {
            tokio::join!(
                connection.accept_handshake(&mut gate),
                EncodedClientHandshake::new(client_transport)
                    .establish(client_handshake_protocol, client_hello),
            )
        })
        .await
        .expect("both handshake peers should make progress");
        let accepted = accepted.expect("server should accept navigation and control");
        let negotiated = negotiated.expect("client should validate the server hello");
        let mut application = accepted
            .install_application(ChromiumDiscoveringNavigationApplicationInstaller)
            .expect("discovery recipe should install");
        let browser_session =
            CdpSession::browser(Arc::clone(application.composition().connection()));
        let temporary_target = browser_session
            .target_create("about:blank")
            .await
            .expect("temporary default-context Page should open");

        let server_hello = negotiated.hello();
        let control_codec = NegotiatedControlCodec::for_client(server_hello)
            .expect("the client should select the negotiated control version");
        let lifecycle_protocol = WireProtocol::new_exact_directional(
            control_codec,
            server_hello.selected_version(),
            server_hello.server_receive_limits(),
            server_hello.client_receive_limits(),
        );
        let (channel, mut driver) = negotiated
            .into_channel_with_control(NavigationCodec::new(navigation.codec()), control_codec, 2)
            .expect("navigation and control should share negotiated wire limits");
        let client = Client::new(channel, AtomicCallIdSource::new(1));
        let mut lifecycle = ClientLifecycleHandler::new(client, lifecycle_protocol);
        let progress = Arc::new(AtomicUsize::new(0));
        let client_progress = Arc::clone(&progress);
        let discovered = Arc::new(Mutex::new(Vec::new()));
        let client_discovered = Arc::clone(&discovered);
        let server_events = Arc::new(AtomicUsize::new(0));
        let observed_server_events = Arc::clone(&server_events);

        // Act: only server-to-client Create messages may reveal the Page.
        let client_run = async {
            client_progress.store(1, Ordering::SeqCst);
            let mut initializers = BTreeMap::new();
            let discovery = loop {
                let event = driver
                    .drive_once_with(&mut lifecycle)
                    .await
                    .expect("client lifecycle driver should receive discovery controls");
                let initializer = match event {
                    RoutedDriverEvent::Handled(ClientLifecycleEvent::Created(initializer)) => {
                        initializer
                    }
                    RoutedDriverEvent::Handled(_) => continue,
                    RoutedDriverEvent::Closed(reason) => {
                        break Err(format!(
                            "remote connection closed during discovery: {reason:?}"
                        ));
                    }
                    RoutedDriverEvent::Unhandled(frame) => {
                        break Err(format!(
                            "remote connection produced an unhandled {:?} frame during discovery",
                            frame.route()
                        ));
                    }
                    RoutedDriverEvent::Delivered(call) => {
                        break Err(format!(
                            "remote connection delivered unexpected call {} during discovery",
                            call.call_id()
                        ));
                    }
                    RoutedDriverEvent::IgnoredAbandoned(call_id) => {
                        break Err(format!(
                            "remote connection ignored unexpected call {call_id} during discovery"
                        ));
                    }
                };
                initializers.insert(initializer.id(), initializer);
                client_discovered
                    .lock()
                    .expect("discovery diagnostics should be available")
                    .push(initializer);
                let Some(page) = initializers
                    .values()
                    .find(|candidate| candidate.kind() == PageKind::OBJECT_KIND)
                    .copied()
                else {
                    continue;
                };
                let Some(context) = page
                    .parent()
                    .and_then(|parent| initializers.get(&parent))
                    .copied()
                else {
                    continue;
                };
                let Some(browser) = context
                    .parent()
                    .and_then(|parent| initializers.get(&parent))
                    .copied()
                else {
                    continue;
                };
                break Ok((browser, context, page));
            };
            let (browser_initializer, context_initializer, page_initializer) = discovery?;
            client_progress.store(2, Ordering::SeqCst);
            let browser = lifecycle
                .client()
                .browser(browser_initializer)
                .expect("announced Browser should become a typed root");
            let context = browser
                .context_from_announcement(context_initializer)
                .expect("announced BrowserContext should become a typed child");
            let page = context
                .page(page_initializer)
                .expect("announced Page should become a typed child");
            client_progress.store(3, Ordering::SeqCst);
            let navigation = page.begin_navigation(
                BeginNavigationParams::new(
                    "data:text/html,<title>pwright-client-discovery-navigation</title>",
                ),
                CallMetadata::default(),
            );
            tokio::pin!(navigation);
            let navigation_result = loop {
                tokio::select! {
                    result = &mut navigation => break result,
                    incoming = driver.drive_once_with(&mut lifecycle) => {
                        let event = incoming.expect("client driver should remain healthy during navigation");
                        assert!(!matches!(event, RoutedDriverEvent::Closed(_)));
                    }
                }
            }
            .expect("typed Page navigation should succeed");
            client_progress.store(4, Ordering::SeqCst);
            let close = driver
                .graceful_close()
                .await
                .expect("client and server should complete the Close/CloseAck barrier");
            client_progress.store(5, Ordering::SeqCst);
            Ok::<_, String>((
                browser.id(),
                context.id(),
                page.id(),
                navigation_result,
                close,
            ))
        };
        let server_run = application.run(move |_| {
            observed_server_events.fetch_add(1, Ordering::SeqCst);
            Ok::<_, Infallible>(())
        });
        let (server_result, client_result) = match tokio::time::timeout(
            Duration::from_secs(20),
            async { tokio::join!(server_run, client_run) },
        )
        .await
        {
            Ok(result) => result,
            Err(error) => panic!(
                "discovery, navigation, and graceful close timed out at client stage {}; server events {}; creates {:?}: {error}",
                progress.load(Ordering::SeqCst),
                server_events.load(Ordering::SeqCst),
                discovered
                    .lock()
                    .expect("discovery diagnostics should be available"),
            ),
        };

        // Assert the client used discovered identities and external Chrome survived.
        let (browser_id, context_id, page_id, navigation_result, close) = match client_result {
            Ok(result) => result,
            Err(error) => panic!("{error}; server outcome: {server_result:?}"),
        };
        assert_eq!(
            server_result.expect("server application should close cleanly"),
            ServerSupervisorCloseReason::PeerGracefulClose
        );
        assert_eq!(browser_id, ObjectId::new(1));
        assert_ne!(context_id, browser_id);
        assert_ne!(page_id, context_id);
        assert!(!navigation_result.frame_id.is_empty());
        assert_eq!(close.woken_calls(), 0);
        assert!(!application.composition().connection().is_closed());
        browser_session
            .target_close(&temporary_target)
            .await
            .expect("temporary target should close while external Chrome remains live");
        browser_session
            .target_get_targets()
            .await
            .expect("external Chrome should remain reachable after remote close");
    }

