    #[tokio::test]
    async fn negotiated_browser_disconnected_publisher_uses_the_accepted_shared_transport() {
        // Arrange
        let handshake = remote_handshake_profile();
        let profile = base_profile()
            .with_browser_events(BrowserEventsInstallationProfile::new(wire_profile()))
            .with_remote_handshake(handshake)
            .with_remote_control(remote_control_profile());
        let prepared =
            PreparedChromiumAttach::new(profile.clone(), exact_limits(profile.requirements()))
                .expect("Browser event composition should prepare");
        let (codec, config) = prepared
            .remote_handshake_parts()
            .expect("remote handshake should be installed");
        let transport = ProductionMemoryTransport::new(
            [browser_events_remote_client_hello(handshake)],
            prepared.resources(),
            handshake.transport_requirements(),
        );
        let mut supervisor = prepared
            .new_supervisor(transport)
            .expect("supervisor should share the production plan");
        let mut gate = AllowUnauthenticated;
        let accepted = supervisor
            .accept_handshake(&codec, &config, &mut gate)
            .await
            .expect("Browser event handshake should establish");
        let publisher = prepared
            .remote_browser_disconnected_publisher(
                ObjectId::new(1),
                Arc::clone(supervisor.transport()),
                &accepted,
            )
            .expect("Browser event protocol should fit production resources")
            .expect("Browser events were negotiated");

        // Act
        publisher
            .publish()
            .await
            .expect("Browser disconnected should be written once");
        let frames = supervisor
            .transport()
            .inner
            .sent
            .lock()
            .expect("sent frames should be available");
        let event = frames.last().expect("event frame should be retained");

        // Assert
        assert_eq!(event.payload().len(), BROWSER_DISCONNECTED_PAYLOAD_BYTES);
        assert_eq!(
            event.route(),
            FrameRoute::Event {
                source: ObjectId::new(1),
                event: pwright_cap_browser_events::BROWSER_DISCONNECTED_EVENT_TAG,
            }
        );
        assert!(event.is_budgeted_by(&supervisor.transport().ledger));
    }

