    #[tokio::test]
    async fn remote_control_parts_share_runtime_transport_and_production_ledger() {
        // Arrange
        let profile = base_profile_with_runtime(
            RuntimeLimits::new(16, 4)
                .with_active_commands(2)
                .with_control_messages(4),
        )
        .with_navigation(navigation_profile())
        .with_remote_handshake(remote_handshake_profile())
        .with_remote_control(remote_control_profile());
        let requirements = profile.requirements();
        let prepared = PreparedChromiumAttach::new(profile.clone(), exact_limits(requirements))
            .expect("complete remote profile should prepare");
        let (codec, config) = prepared
            .remote_handshake_parts()
            .expect("remote handshake should be installed");
        let client = ClientHello::new(
            pwright_transport::VersionPolicy::exact(ProtocolVersion::new(1, 0)),
            FrameLimits::new(4096, 0, 0, 4096),
            CapabilityRequest::new(
                Vec::new(),
                vec![
                    control_protocol_requirement()
                        .expect("control protocol requirement should build"),
                ],
                codec.limits(),
            )
            .expect("client control request should build"),
        );
        let encoded = codec
            .encode_parts(&client)
            .expect("client hello should encode");
        let hello = WireFrame::new(
            ProtocolVersion::new(1, 0),
            FrameRoute::Handshake,
            encoded.payload().to_vec(),
            encoded.attachments().to_vec(),
            FrameLimits::new(4096, 0, 0, 4096),
        )
        .expect("client hello should fit");
        let mut supervisor = prepared
            .new_supervisor(MemoryTransport::new([hello]))
            .expect("supervisor should install complete remote resources");
        let mut gate = AllowUnauthenticated;
        let accepted = supervisor
            .accept_handshake(&codec, &config, &mut gate)
            .await
            .expect("remote handshake should establish");
        assert!(
            accepted
                .hello()
                .enabled_capabilities()
                .iter()
                .any(|capability| capability.id().as_str() == CONTROL_PROTOCOL_ID
                    && capability.version() == CONTROL_PROTOCOL_CURRENT_VERSION)
        );
        let runtime = Arc::new(
            prepared
                .new_controlled_runtime(
                    (),
                    (),
                    NoDeadlineScheduler,
                    CleanupQueue::new(2),
                    ObjectId::new(1),
                )
                .expect("controlled runtime should use the shared plan"),
        );
        let (mut controls, outbound) = prepared
            .remote_control_parts(
                Arc::clone(&runtime),
                Arc::clone(supervisor.transport()),
                &accepted,
            )
            .expect("control parts should fit the remote plan")
            .expect("remote control was selected");
        let ledger = prepared
            .resources()
            .claim(pwright_core::ResourceRequirements::none())
            .expect("empty claim should expose the same ledger identity");

        // Act
        let lifecycle = outbound
            .send_once()
            .await
            .expect("queued Browser lifecycle should be sent");
        let client_control = accepted.application_protocol(
            NegotiatedControlCodec::for_client(accepted.hello())
                .expect("client control protocol should use negotiated version"),
        );
        let close = client_control
            .encode(&ControlMessage::Close)
            .expect("negotiated client should encode Close");
        let close_result = controls
            .handle_control(close)
            .await
            .expect("production control handler should acknowledge Close");

        // Assert
        assert!(matches!(
            lifecycle,
            Some(pwright_core::ControlMessage::Create {
                object_id,
                parent: None,
                kind,
            }) if object_id == ObjectId::new(1) && kind == BROWSER_OBJECT_KIND.tag
        ));
        assert!(matches!(
            close_result,
            ServerFrameDisposition::Handled(GracefulCloseControlEvent::CloseAcknowledged {
                cleanup: Some(_)
            })
        ));
        assert_eq!(
            controls.terminal_close_reason(),
            Some(ServerSupervisorCloseReason::PeerGracefulClose)
        );
        assert_eq!(
            runtime
                .control_message_metrics()
                .unwrap()
                .unwrap()
                .current_len,
            0
        );
        let sent = supervisor
            .transport()
            .sent
            .lock()
            .expect("sent frames should be available");
        assert_eq!(sent.len(), 3);
        assert_eq!(sent[1].route(), FrameRoute::Control);
        assert_eq!(
            client_control
                .decode::<ControlMessage>(sent[2].clone())
                .expect("client should decode production CloseAck"),
            ControlMessage::CloseAck
        );
        assert!(sent.iter().all(|frame| frame.is_budgeted_by(&ledger)));
    }

