    #[test]
    fn remote_network_profile_rejects_a_terminal_snapshot_frame_that_cannot_fit() {
        // Arrange
        let lifecycle = NetworkLifecycleLimits::new(2, 64, 256, 16, 32, 8, 256, 64, 64, 128);
        let codec = NetworkEventsCodecLimits::from_lifecycle(lifecycle);
        let adapter =
            CdpNetworkEventProductionProfile::new(lifecycle, ResourceScope::extension(95, 2))
                .expect("network adapter profile should validate");
        let network = ChromiumNetworkEventsProductionProfile::new(adapter, 1)
            .expect("one Page lane should validate");
        let required = codec.maximum_payload_bytes();
        let ordinary_wire = wire_profile();
        let too_small = CapabilityWireProfile::new(
            ordinary_wire.version(),
            FrameLimits::new(required - 1, 0, 0, required - 1),
            ordinary_wire.receive_limits(),
        );
        let remote = ChromiumRemoteNetworkEventProfile::new(
            too_small,
            codec,
            1,
            codec.maximum_retained_event_bytes(),
        );
        let profile = base_profile_with_runtime(
            RuntimeLimits::new(20, 4)
                .with_active_commands(2)
                .with_control_messages(8),
        )
        .with_network_events(network)
        .with_remote_handshake(remote_handshake_profile())
        .with_remote_control(remote_control_profile())
        .with_remote_network_events(remote);
        let requirements = profile.requirements();

        // Act
        let error = match PreparedChromiumAttach::new(profile, exact_limits(requirements)) {
            Ok(_) => panic!("undersized terminal frame should fail during preparation"),
            Err(error) => error,
        };

        // Assert
        assert!(matches!(
            error,
            ChromiumCompositionError::InvalidRemoteNetworkEventsSetup {
                required_payload_bytes,
                send_limits,
                ..
            } if required_payload_bytes == required && send_limits == too_small.send_limits()
        ));
    }

