    #[test]
    fn topology_page_event_publisher_is_optional_bounded_and_loss_explicit() {
        // Arrange
        let protocol = || {
            WireProtocol::new_exact_directional(
                (),
                ProtocolVersion::new(1, 0),
                FrameLimits::new(64, 0, 0, 64),
                FrameLimits::new(64, 0, 0, 64),
            )
        };
        let (context_sender, _context_outbound) =
            TypedEventOutbound::<BrowserContextPage, _, _>::new(
                protocol(),
                (),
                1,
                OverflowPolicy::RejectNewest,
            );
        let (popup_sender, _popup_outbound) = TypedEventOutbound::<PagePopup, _, _>::new(
            protocol(),
            (),
            1,
            OverflowPolicy::RejectNewest,
        );
        let publisher = ChromiumTopologyPageEventPublisher::new(
            Some(context_sender.clone()),
            Some(popup_sender.clone()),
        );
        let effects = [
            CdpTopologyEffect::PageReady {
                page: ObjectId::new(7),
                context: ObjectId::new(2),
            },
            CdpTopologyEffect::PopupLinked {
                opener: ObjectId::new(3),
                popup: ObjectId::new(7),
            },
        ];

        // Act
        let publication = publisher
            .publish_effects(&effects)
            .expect("both discovery events should fit");
        let overflow = publisher
            .publish_effects(&effects[..1])
            .expect_err("a second context event must not be silently lost");
        let inert = ChromiumTopologyPageEventPublisher::default();
        let skipped = inert
            .publish_effects(&effects)
            .expect("uninstalled lanes should own no queue");

        // Assert
        assert_eq!(publication.context_pages, 1);
        assert_eq!(publication.popups, 1);
        assert_eq!(publication.skipped_uninstalled, 0);
        assert_eq!(
            context_sender
                .metrics()
                .expect("metrics")
                .queue()
                .current_len,
            1
        );
        assert_eq!(
            popup_sender.metrics().expect("metrics").queue().current_len,
            1
        );
        assert!(matches!(
            overflow,
            ChromiumTopologyPageEventPublishError::QueueRejected {
                effect_index: 0,
                event: BROWSER_CONTEXT_PAGE_EVENT_TAG,
            }
        ));
        assert!(inert.is_inert());
        assert_eq!(skipped.skipped_uninstalled, 2);
    }

    #[tokio::test]
    async fn topology_page_event_waits_until_related_lifecycle_creates_are_written() {
        // Arrange
        let epoch = ConnectionEpoch::new(1);
        let mut topology = CdpTopology::new(
            ObjectId::new(1),
            epoch,
            CdpTopologyLimits::new(16, 4, 4, 8, 8, 128),
        )
        .expect("topology should build");
        topology
            .register_context(
                epoch,
                "context-a",
                ObjectId::new(2),
                CdpContextOwnership::External,
            )
            .expect("context should register");
        let attached = topology
            .attach_page(
                epoch,
                CdpPageTarget::new("target-a", "session-a", "context-a"),
                CdpPageObjectIds::new(ObjectId::new(3), ObjectId::new(4)),
            )
            .expect("page should attach");
        let bound = topology
            .attach_frame(
                epoch,
                CdpFrameAttachment::main("target-a", "frame-a"),
                ObjectId::new(4),
            )
            .expect("main frame should bind");
        let ready = topology
            .mark_page_ready(epoch, "target-a")
            .expect("page should become ready");
        let update = attached.combine(bound).combine(ready);
        let runtime = Arc::new(DirectDispatcher::new(
            (),
            RuntimeLimits::new(8, 1).with_control_messages(8),
        ));
        runtime
            .register_object(ObjectId::new(1), None, BROWSER_OBJECT_KIND.tag)
            .expect("browser should register");
        runtime
            .register_object(
                ObjectId::new(2),
                Some(ObjectId::new(1)),
                BROWSER_CONTEXT_OBJECT_KIND.tag,
            )
            .expect("context should register");
        while runtime
            .pop_control_message()
            .expect("setup controls should drain")
            .is_some()
        {}
        runtime
            .register_object(
                ObjectId::new(3),
                Some(ObjectId::new(2)),
                PAGE_OBJECT_KIND.tag,
            )
            .expect("page should register");
        runtime
            .register_object(
                ObjectId::new(4),
                Some(ObjectId::new(3)),
                FRAME_OBJECT_KIND.tag,
            )
            .expect("frame should register");
        let transport = Arc::new(MemoryTransport::new([]));
        let control = OrderedRuntimeControl::new(
            Arc::clone(&runtime),
            RuntimeControlDriver::new(control_protocol(), Arc::clone(&transport)),
            2,
        )
        .expect("ordered control should build");
        let event_protocol = WireProtocol::new_exact_directional(
            (),
            ProtocolVersion::new(1, 0),
            FrameLimits::new(64, 0, 0, 64),
            FrameLimits::new(64, 0, 0, 64),
        );
        let (context_sender, _context_outbound) =
            TypedEventOutbound::<BrowserContextPage, _, _>::new(
                event_protocol,
                (),
                1,
                OverflowPolicy::RejectNewest,
            );
        let publisher = ChromiumTopologyPageEventPublisher::new(Some(context_sender.clone()), None);

        // Act
        let publication = publisher
            .publish_after_creation_fence(&update, &control)
            .await
            .expect("lifecycle fence should precede event admission");

        // Assert
        let sent = transport
            .sent
            .lock()
            .expect("sent controls should be available");
        assert_eq!(sent.len(), 2);
        assert!(
            sent.iter()
                .all(|frame| frame.route() == FrameRoute::Control)
        );
        assert_eq!(publication.context_pages, 1);
        assert_eq!(
            context_sender
                .metrics()
                .expect("metrics")
                .queue()
                .current_len,
            1
        );
        assert!(
            runtime
                .pop_control_message()
                .expect("control source should remain available")
                .is_none()
        );
    }

