    #[tokio::test]
    async fn browser_context_subscription_toggles_every_exact_page_session_once() {
        // Arrange
        let (services, factory, subscriptions, mut topology) = two_page_network_context();
        let activator = ChromiumPageSubscriptionActivator::new(services);

        // Act
        activator
            .set_subscription(ObjectId::new(2), NETWORK_REQUEST_EVENT_TAG, true)
            .await
            .expect("Context subscription should enable every Page session");
        let selected = subscriptions
            .is_browser_context_subscribed(ObjectId::new(2), NETWORK_REQUEST_EVENT_TAG)
            .expect("Context interest should be readable");
        topology
            .attach_page(
                ConnectionEpoch::new(1),
                CdpPageTarget::new("target-c", "session-c", "context-a"),
                CdpPageObjectIds::new(ObjectId::new(7), ObjectId::new(8)),
            )
            .expect("future Page candidate should attach");
        let future_page_error = activator
            .services()
            .synchronize(&topology)
            .expect_err("an active Context must not expose a Page before its lane is prepared");
        activator
            .set_subscription(ObjectId::new(2), NETWORK_REQUEST_EVENT_TAG, false)
            .await
            .expect("Context cleanup should disable every Page session");

        // Assert
        assert!(selected);
        assert!(matches!(
            future_page_error,
            CdpPageRouteError::NetworkSubscriptions(
                ChromiumNetworkSubscriptionStateError::InheritedPageLaneUnavailable {
                    browser_context,
                    page,
                }
            ) if browser_context == ObjectId::new(2) && page == ObjectId::new(7)
        ));
        assert_eq!(
            factory.client("target-a").method_names(),
            ["Network.enable", "Network.disable"]
        );
        assert_eq!(
            factory.client("target-b").method_names(),
            ["Network.enable", "Network.disable"]
        );
        assert!(
            !subscriptions
                .is_browser_context_subscribed(ObjectId::new(2), NETWORK_REQUEST_EVENT_TAG)
                .expect("final Context interest should be readable")
        );
        assert!(
            !subscriptions
                .metrics()
                .expect("transaction metrics should be readable")
                .browser_context_transition_in_progress()
        );
    }

    #[tokio::test]
    async fn browser_context_activation_failure_compensates_every_attempted_session() {
        // Arrange
        let (services, factory, subscriptions, _topology) = two_page_network_context();
        factory
            .client("target-b")
            .set_network_errors([Some("enable failed".to_owned()), None]);
        let activator = ChromiumPageSubscriptionActivator::new(services);

        // Act
        let error = activator
            .set_subscription(ObjectId::new(2), NETWORK_REQUEST_EVENT_TAG, true)
            .await
            .expect_err("second Page enable should fail");

        // Assert
        assert!(matches!(
            error,
            super::ChromiumSubscriptionActivationError::BrowserContextCdp {
                browser_context,
                page,
                enabled: true,
                ..
            } if browser_context == ObjectId::new(2) && page == ObjectId::new(5)
        ));
        assert_eq!(
            factory.client("target-a").method_names(),
            ["Network.enable", "Network.disable"]
        );
        assert_eq!(
            factory.client("target-b").method_names(),
            ["Network.enable", "Network.disable"]
        );
        assert!(
            !subscriptions
                .is_browser_context_subscribed(ObjectId::new(2), NETWORK_REQUEST_EVENT_TAG)
                .expect("failed Context interest should remain absent")
        );
        assert!(
            !subscriptions
                .metrics()
                .expect("transaction metrics should be readable")
                .browser_context_transition_in_progress()
        );
    }

    #[tokio::test]
    async fn cancelled_browser_context_enable_is_resumed_as_exact_disable_compensation() {
        // Arrange
        let (services, factory, subscriptions, topology) = two_page_network_context();
        let gate = Arc::new(tokio::sync::Notify::new());
        factory
            .client("target-b")
            .set_network_gate(Some(Arc::clone(&gate)));
        let activator = ChromiumPageSubscriptionActivator::new(services);
        let mut activation =
            Box::pin(activator.set_subscription(ObjectId::new(2), NETWORK_REQUEST_EVENT_TAG, true));

        // Act
        assert!(poll_now(activation.as_mut()).is_pending());
        drop(activation);
        let pending_after_cancel = subscriptions
            .metrics()
            .expect("cancelled transaction metrics should be readable")
            .browser_context_transition_in_progress();
        let topology_error = activator
            .services()
            .synchronize(&topology)
            .expect_err("topology publication must not cross a pending Context transition");
        factory.client("target-b").set_network_gate(None);
        activator
            .set_subscription(ObjectId::new(2), NETWORK_REQUEST_EVENT_TAG, false)
            .await
            .expect("cleanup edge should compensate every possibly enabled session");
        activator
            .services()
            .synchronize(&topology)
            .expect("topology synchronization should resume after compensation");

        // Assert
        assert!(pending_after_cancel);
        assert!(matches!(
            topology_error,
            CdpPageRouteError::NetworkSubscriptions(
                ChromiumNetworkSubscriptionStateError::BrowserContextTransitionInProgress {
                    browser_context
                }
            ) if browser_context == ObjectId::new(2)
        ));
        assert_eq!(
            factory.client("target-a").method_names(),
            ["Network.enable", "Network.disable"]
        );
        assert_eq!(
            factory.client("target-b").method_names(),
            ["Network.enable", "Network.disable"]
        );
        assert!(
            !subscriptions
                .is_browser_context_subscribed(ObjectId::new(2), NETWORK_REQUEST_EVENT_TAG)
                .expect("cancelled enable must not commit Context interest")
        );
        assert!(
            !subscriptions
                .metrics()
                .expect("compensated transaction metrics should be readable")
                .browser_context_transition_in_progress()
        );
    }

