    #[test]
    fn page_interest_edges_do_not_toggle_a_context_owned_network_domain() {
        // Arrange
        let subscriptions = super::ChromiumNetworkSubscriptionRegistry::new_unbudgeted(1);
        subscriptions
            .register_page_lane(ObjectId::new(3), ObjectId::new(2), "session-a".to_owned())
            .expect("Page lane should register");
        subscriptions
            .set_browser_context_interest_for_test(
                ObjectId::new(2),
                NETWORK_REQUEST_EVENT_TAG,
                true,
            )
            .expect("Context interest should install");

        // Act
        let enable = subscriptions
            .begin_transition(
                ObjectId::new(3),
                "session-a",
                NETWORK_REQUEST_EVENT_TAG,
                true,
                false,
            )
            .expect("direct Page interest should prepare");
        let enable_action = enable.action();
        enable.commit().expect("direct Page interest should commit");
        let disable = subscriptions
            .begin_transition(
                ObjectId::new(3),
                "session-a",
                NETWORK_REQUEST_EVENT_TAG,
                false,
                false,
            )
            .expect("direct Page cleanup should prepare");
        let disable_action = disable.action();
        disable.commit().expect("direct Page cleanup should commit");

        // Assert
        assert_eq!(enable_action, super::ChromiumNetworkDomainAction::None);
        assert_eq!(disable_action, super::ChromiumNetworkDomainAction::None);
        assert!(
            subscriptions
                .is_browser_context_subscribed(ObjectId::new(2), NETWORK_REQUEST_EVENT_TAG)
                .expect("Context interest should remain readable")
        );
    }

