    #[tokio::test]
    async fn page_router_targets_the_exact_materialized_cdp_session_and_drops_detached_routes() {
        // Arrange
        let profile = base_profile()
            .with_navigation(navigation_profile())
            .with_locator(locator_profile());
        let resources = ProductionResourceLedger::new(
            exact_limits(profile.requirements()),
            profile.requirements(),
        )
        .expect("concurrent composition plan should fit exactly");
        let epoch = ConnectionEpoch::new(1);
        let mut topology =
            ProductionCdpTopology::new(ObjectId::new(1), epoch, profile.topology(), &resources)
                .expect("production topology should build");
        let factory = Arc::new(RecordingSessionFactory::default());
        let session_factory: Arc<dyn SessionFactory> = factory.clone();
        let services =
            CdpPageServices::new_with_production_resources(session_factory, &profile, &resources)
                .expect("page routes should claim the composition plan");
        let prepared = PreparedChromiumAttach::with_production_resources(profile, &resources)
            .expect("composition should prepare against the same ledger");
        let runtime = prepared
            .new_direct_runtime(services, ObjectId::new(1))
            .expect("page runtime should build");
        transact_topology_update(&mut topology, &runtime, |candidate| {
            candidate.register_context(
                epoch,
                "context-a",
                ObjectId::new(2),
                CdpContextOwnership::External,
            )
        })
        .expect("context transaction should commit");
        transact_topology_update(&mut topology, &runtime, |candidate| {
            candidate.attach_page(
                epoch,
                CdpPageTarget::new("target-a", "session-a", "context-a"),
                CdpPageObjectIds::new(ObjectId::new(3), ObjectId::new(4)),
            )
        })
        .expect("page lifecycle and route transaction should commit");

        // Act
        let result = runtime
            .service()
            .call_for(
                ObjectId::new(3),
                BeginNavigationParams::new("https://example.com/a"),
            )
            .await;
        runtime
            .service()
            .synchronize(&topology)
            .expect("unchanged topology should preserve its route");
        <CdpPageServices as CommandCancellation<BeginNavigation>>::cancel(
            runtime.service(),
            OperationContext::new(
                CallId::new(10),
                ObjectId::new(3),
                MethodTag::new(0x0001_0001),
                None,
            ),
            CancellationReason::Caller,
        )
        .await
        .expect("live page cancellation should target its session");
        transact_topology_update(&mut topology, &runtime, |candidate| {
            candidate.detach_target(epoch, "session-a", Some("target-a"))
        })
        .expect("detached lifecycle and routes should commit together");
        let detached = runtime
            .service()
            .call_for(
                ObjectId::new(3),
                BeginNavigationParams::new("https://example.com/stale"),
            )
            .await;

        // Assert
        assert_eq!(
            result.expect("routed navigation should succeed").frame_id,
            "frame-target-a"
        );
        assert_eq!(
            factory
                .created
                .lock()
                .expect("created routes should be available")
                .as_slice(),
            &[("session-a".to_owned(), "target-a".to_owned())]
        );
        let methods = factory.client("target-a").method_names();
        assert!(methods.contains(&"Page.navigate".to_owned()));
        assert!(methods.contains(&"Page.stopLoading".to_owned()));
        assert_eq!(runtime.service().route_count(), Ok(0));
        assert_eq!(runtime.live_object_count(), Ok(2));
        assert_eq!(
            detached.expect_err("detached route should fail").kind(),
            pwright_core::FailureKind::TargetClosed
        );
    }

    #[test]
    fn rejected_runtime_batch_rolls_back_topology_and_page_routes() {
        // Arrange
        let profile = base_profile_with_runtime(
            RuntimeLimits::new(16, 4)
                .with_active_commands(2)
                .with_control_messages(1),
        )
        .with_navigation(navigation_profile());
        let resources = ProductionResourceLedger::new(
            exact_limits(profile.requirements()),
            profile.requirements(),
        )
        .expect("composition plan should fit exactly");
        let epoch = ConnectionEpoch::new(1);
        let mut topology =
            ProductionCdpTopology::new(ObjectId::new(1), epoch, profile.topology(), &resources)
                .expect("production topology should build");
        let factory = Arc::new(RecordingSessionFactory::default());
        let session_factory: Arc<dyn SessionFactory> = factory;
        let services =
            CdpPageServices::new_with_production_resources(session_factory, &profile, &resources)
                .expect("page routes should claim the composition plan");
        let prepared = PreparedChromiumAttach::with_production_resources(profile, &resources)
            .expect("composition should prepare");
        let runtime = prepared
            .new_direct_runtime(services, ObjectId::new(1))
            .expect("runtime should build");
        assert!(
            runtime
                .pop_control_message()
                .expect("root lifecycle should be readable")
                .is_some()
        );
        transact_topology_update(&mut topology, &runtime, |candidate| {
            candidate.register_context(
                epoch,
                "context-a",
                ObjectId::new(2),
                CdpContextOwnership::External,
            )
        })
        .expect("one context lifecycle message should fit");
        assert!(
            runtime
                .pop_control_message()
                .expect("context lifecycle should be readable")
                .is_some()
        );

        // Act
        let error = transact_topology_update(&mut topology, &runtime, |candidate| {
            candidate.attach_page(
                epoch,
                CdpPageTarget::new("target-a", "session-a", "context-a"),
                CdpPageObjectIds::new(ObjectId::new(3), ObjectId::new(4)),
            )
        })
        .expect_err("page and main-frame messages should not fit one outbox slot");

        // Assert
        assert!(matches!(
            error,
            ChromiumCompositionError::Runtime(RuntimeStateError::ControlMessageCapacityExceeded {
                required: 2,
                remaining: 1,
                limit: 1,
            })
        ));
        assert_eq!(topology.page_object_id("target-a"), None);
        assert_eq!(runtime.live_object_count(), Ok(2));
        assert_eq!(runtime.is_object_live(ObjectId::new(3)), Ok(false));
        assert_eq!(runtime.is_object_live(ObjectId::new(4)), Ok(false));
        assert_eq!(runtime.service().route_count(), Ok(0));
        assert_eq!(runtime.pop_control_message(), Ok(None));
    }

