    #[test]
    fn dropped_started_page_close_transfers_the_exact_transaction() {
        // Arrange
        let (runtime, topology, browser, _page_client) = page_close_state();
        browser.pause_target_close();
        let continuation = CleanupQueue::new(1);
        let raw = Arc::new(ChromiumPageCloseCommandService::new(
            browser.clone(),
            Arc::clone(&topology),
            runtime.service().clone(),
            runtime.lifecycle_handle(),
            page_lifecycle_profile().backend(),
            Arc::new(ImmediatePageClosePoll),
        ));
        let service = ContinuablePageCloseCommandService::new(raw, continuation.clone());
        let mut close = Box::pin(service.call(Command::<PageClose>::new(
            CallId::new(31),
            ObjectId::new(3),
            CallMetadata::default(),
            (),
        )));

        // Act
        assert!(poll_now(close.as_mut()).is_pending());
        assert_eq!(browser.method_names(), ["Target.closeTarget"]);
        assert!(runtime.lifecycle_transaction_active().unwrap());
        drop(close);
        browser.resume_target_close();
        let mut job = continuation.try_take().unwrap().unwrap();
        let completed = poll_now(job.as_mut());

        // Assert
        assert!(matches!(completed, Poll::Ready(Ok(()))));
        assert_eq!(runtime.is_object_live(ObjectId::new(3)), Ok(false));
        assert_eq!(runtime.service().route_count(), Ok(0));
        assert_eq!(topology.lock().unwrap().page_object_id("target-a"), None);
    }

