    #[tokio::test]
    async fn page_close_retires_network_lane_and_reuses_exact_capacity() {
        // Arrange
        let (runtime, topology, browser, _factory, services, driver, creation) =
            network_page_creation_state();
        let registration = driver.registration_handle();
        let first = creation
            .call(Command::<BrowserContextNewPage>::new(
                CallId::new(40),
                ObjectId::new(2),
                CallMetadata::default(),
                (),
            ))
            .await
            .unwrap()
            .into_outcome()
            .expect("first Page should consume the single network lane");
        let close = ChromiumPageCloseCommandService::new(
            browser,
            Arc::clone(&topology),
            services.clone(),
            runtime.lifecycle_handle(),
            page_lifecycle_profile().backend(),
            Arc::new(ImmediatePageClosePoll),
        )
        .with_network_registration(registration);

        // Act
        close
            .call(Command::<PageClose>::new(
                CallId::new(41),
                first.object_id,
                CallMetadata::default(),
                (),
            ))
            .await
            .unwrap()
            .into_outcome()
            .expect("Page close should publish before retiring its network lane");
        let second = creation
            .call(Command::<BrowserContextNewPage>::new(
                CallId::new(42),
                ObjectId::new(2),
                CallMetadata::default(),
                (),
            ))
            .await
            .unwrap()
            .into_outcome()
            .expect("the retired lane capacity should be reusable");

        // Assert
        assert_eq!(driver.page_count(), 1);
        assert_ne!(second.object_id, first.object_id);
        assert_eq!(runtime.is_object_live(first.object_id), Ok(false));
        assert_eq!(runtime.is_object_live(second.object_id), Ok(true));
        assert_eq!(services.route_count(), Ok(1));
        assert_eq!(
            services
                .network_subscription_registry()
                .unwrap()
                .metrics()
                .unwrap()
                .registered_page_lanes(),
            1
        );
    }

