    #[test]
    fn context_close_rejects_before_browser_work_without_continuation_capacity() {
        // Arrange
        let (runtime, topology) = context_close_state(CdpContextOwnership::Owned);
        let cdp = Arc::new(FakeCdpClient::from_html(""));
        let continuation = CleanupQueue::new(0);
        let raw = Arc::new(ChromiumBrowserContextCloseCommandService::new(
            cdp.clone(),
            topology,
            runtime.lifecycle_handle(),
        ));
        let service = ContinuableBrowserContextCloseCommandService::new(raw, continuation);
        let command = Command::<BrowserContextClose>::new(
            CallId::new(9),
            ObjectId::new(2),
            CallMetadata::default(),
            (),
        );

        // Act
        let mut close = Box::pin(service.call(command));
        let result = poll_now(close.as_mut());

        // Assert
        let Poll::Ready(Ok(result)) = result else {
            panic!("missing continuation capacity should reject synchronously");
        };
        assert_eq!(
            result
                .into_outcome()
                .expect_err("close should reject")
                .kind(),
            FailureKind::ResourceExhausted
        );
        assert!(cdp.method_names().is_empty());
        assert_eq!(runtime.is_object_live(ObjectId::new(2)), Ok(true));
    }

    #[tokio::test]
    async fn failed_remote_handle_create_fence_compensates_the_native_handle() {
        #[derive(Debug)]
        struct SendFailure;

        impl std::fmt::Display for SendFailure {
            fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
                formatter.write_str("injected lifecycle send failure")
            }
        }

        impl std::error::Error for SendFailure {}

        struct FailingSendTransport;

        impl FrameTransport for FailingSendTransport {
            type Error = SendFailure;
            type Send<'a> = Ready<Result<(), Self::Error>>;
            type Receive<'a> = Ready<Result<Option<WireFrame>, Self::Error>>;

            fn send(&self, _frame: WireFrame) -> Self::Send<'_> {
                ready(Err(SendFailure))
            }

            fn receive(&self) -> Self::Receive<'_> {
                ready(Ok(None))
            }
        }

        struct ReadyHandleCreate {
            runtime: Arc<DirectDispatcher<()>>,
        }

        impl Service<Command<EvaluateHandle>> for ReadyHandleCreate {
            type Response = CommandResult<EvaluateHandle>;
            type Error = Infallible;
            type Future<'a> = Ready<Result<Self::Response, Self::Error>>;

            fn call(&self, command: Command<EvaluateHandle>) -> Self::Future<'_> {
                self.runtime
                    .register_object(
                        ObjectId::new(5),
                        Some(command.object_id()),
                        ELEMENT_HANDLE_OBJECT_KIND.tag,
                    )
                    .expect("test Handle should enter the runtime");
                ready(Ok(CommandResult::new(
                    command.call_id(),
                    Ok(pwright_cap_handle_evaluation::HandleInitializer::new(
                        ObjectId::new(5),
                        command.object_id(),
                        ELEMENT_HANDLE_OBJECT_KIND.tag,
                        "body",
                    )),
                )))
            }
        }

        struct RecordingHandleDispose {
            runtime: Arc<DirectDispatcher<()>>,
            calls: Arc<AtomicUsize>,
        }

        impl Service<Command<HandleDispose>> for RecordingHandleDispose {
            type Response = CommandResult<HandleDispose>;
            type Error = Infallible;
            type Future<'a> = Ready<Result<Self::Response, Self::Error>>;

            fn call(&self, command: Command<HandleDispose>) -> Self::Future<'_> {
                self.calls.fetch_add(1, Ordering::SeqCst);
                self.runtime
                    .dispose_object(command.object_id())
                    .expect("compensation should retire the test Handle");
                ready(Ok(CommandResult::new(command.call_id(), Ok(()))))
            }
        }

        // Arrange
        let runtime = Arc::new(
            DirectDispatcher::with_object_kinds_and_topology(
                (),
                RuntimeLimits::new(5, 1).with_control_messages(8),
                BROWSER_OBJECT_KIND_CATALOG,
                ObjectTopologyMode::Complete,
            )
            .expect("runtime should build"),
        );
        for (object_id, parent, kind) in [
            (ObjectId::new(1), None, BROWSER_OBJECT_KIND.tag),
            (
                ObjectId::new(2),
                Some(ObjectId::new(1)),
                BROWSER_CONTEXT_OBJECT_KIND.tag,
            ),
            (
                ObjectId::new(3),
                Some(ObjectId::new(2)),
                PAGE_OBJECT_KIND.tag,
            ),
            (
                ObjectId::new(4),
                Some(ObjectId::new(3)),
                FRAME_OBJECT_KIND.tag,
            ),
        ] {
            runtime.register_object(object_id, parent, kind).unwrap();
        }
        while runtime.pop_control_message().unwrap().is_some() {}
        let calls = Arc::new(AtomicUsize::new(0));
        let dispose = Arc::new(RecordingHandleDispose {
            runtime: Arc::clone(&runtime),
            calls: Arc::clone(&calls),
        });
        let control = OrderedRuntimeControl::new(
            Arc::clone(&runtime),
            RuntimeControlDriver::new(control_protocol(), Arc::new(FailingSendTransport)),
            1,
        )
        .expect("ordered control should build");
        let service = OrderedEvaluateHandleCommandService::new(
            Arc::new(ReadyHandleCreate {
                runtime: Arc::clone(&runtime),
            }),
            dispose,
            control,
        );

        // Act
        let result = service
            .call(Command::<EvaluateHandle>::new(
                CallId::new(41),
                ObjectId::new(4),
                CallMetadata::default(),
                EvaluateHandleParams::expression("document.body"),
            ))
            .await
            .unwrap()
            .into_outcome()
            .expect_err("failed Create publication must fail the command");

        // Assert
        assert_eq!(result.kind(), FailureKind::Cleanup);
        assert_eq!(calls.load(Ordering::SeqCst), 1);
        assert_eq!(runtime.is_object_live(ObjectId::new(5)), Ok(false));
        assert!(matches!(
            result.details(),
            Some(pwright_cap_handle_evaluation::HandleEvaluationErrorDetails::Cleanup {
                cleanup,
                ..
            }) if cleanup.contains("native Handle was released")
        ));
    }

